window.__SUMMARY_PARTS__=window.__SUMMARY_PARTS__||[];window.__SUMMARY_PARTS__.push([{"i":60000,"as":"研究人员成功合成纤锌矿相NbAlN极性过渡金属氮化物合金，与GaN基异质结构高度兼容。尽管单质Nb具有强金属性，仍实现了保持底层GaN纤锌矿晶体结构和金属极性的共格外延NbAlN薄膜，并通过环形明场扫描透镜电镜直接观察证实。Nb掺入引起单调晶格膨胀，并形成连续纤锌矿骨架内相容的Nb富集纳米区域。功能上，NbAlN可作为极化工程GaN异质结构的势垒层。","scd":{"b":8.0,"i":4.0,"r":7.0,"d":7.0,"t":5.0},"kp":["材料[极性纤锌矿过渡金属氮化物合金]: NbAlN","制备质量[NbAlN薄膜]: 与GaN基异质结构高度兼容的共格外延生长，保持纤锌矿晶体结构与金属极性"]},{"i":60001,"as":"富锂层状氧化物正极虽因阴离子氧化还原活性具有高比容量，但过渡金属迁移加剧空位聚集，引发多米诺式结构退化。该研究将静电钉扎效应精确引入锂层，通过强静电排斥缓解过渡金属迁移，同时调控氧配体周围的电子分布以稳定氧氧化还原。此外，强静电相互作用赋予材料自适应调整层间距的能力，缓冲（脱）锂过程中层状框架的结构演变，从而打破结构降解的连锁反应。","scd":{"b":7.0,"i":4.0,"r":6.0,"d":6.5,"t":5.0},"kp":["稳定化策略[富锂层状氧化物阴极]: 精确静电钉扎引入Li层抑制过渡金属迁移，并调制电子分布以阻断空位聚集引发的多米诺式结构降解"]},{"i":60002,"as":"水电解中气泡层会阻塞活性位点并增加传输和欧姆损耗。该研究开发表面应变NiMo阴极（s-NiMo），在0.5 M磷酸钾缓冲液（pH 7.0）中实现动力学解耦的氢气泡管理。NiMo与s-NiMo本征HER动力学几乎相同（H*吸附能相近），但在气泡调控运行条件下，s-NiMo在-20 mA/cm²下稳态过电位低63 mV。高速成像显示其氢气泡更小、脱离更快，实现稳定的近中性水电解。","scd":{"b":7.0,"i":4.0,"r":6.5,"d":7.0,"t":5.0},"kp":["电解体系[表面应变NiMo阴极析氢]: 0.5 M磷酸钾缓冲液近中性电解","功能特性[表面应变NiMo阴极]: 动学解耦氢气泡管理，降低气泡层造成的传质与欧姆损耗"]},{"i":60003,"as":"硫化物全固态锂电池高负载正极受限于缓慢的Li+/电子动力学和差的界面兼容性，且传统碳添加剂易与硫化物电解质发生有害副反应。该研究通过一步球磨引入多功能纳米In2O3导电剂，有效介导Li5.5PS4.5Cl1.5（LPSC）与大颗粒NCM811之间的相互作用，提升混合均匀性，构建低曲折度Li+传输网络及快速'NCM-纳米In2O3-NCM'电子通路，实现快速动力学和稳定界面。","scd":{"b":6.5,"i":4.5,"r":6.0,"d":7.0,"t":5.0},"kp":["导电添加剂[硫化物全固态锂电池高负载阴极]: 纳米级In2O3多功能导电剂，一步球磨工艺集成，改善Li+/电子动力学与界面兼容性并避免碳添加剂与硫化物电解质的副反应"]},{"i":60004,"as":"研究将机器学习与高通量计算相结合，从28个构筑单元和9种连接方式组装的11934个hcb型二维共价有机框架中预测可行的光催化整体分解水材料。通过训练10种初始算法并优化性能前4名的超参数，开发出预测带边能级的ETR模型（R²达0.97和0.99），以及KNR和RFR等模型，实现可见光下光催化2D-COF整体分解水材料的快速理性设计与精准合成。","scd":{"b":7.0,"i":3.5,"r":6.5,"d":7.5,"t":5.0},"kp":["数据库构建[光催化整体水分解2D-COF]: 由28个构筑单元和9种连接键组装11934个hcb型2D-COF","筛选方法[2D-COF光催化材料]: 机器学习与高通量计算集成理性设计"]},{"i":60005,"as":"研究发现在三维混合斯格明子-反斯格明子弦中，层相关拓扑结构产生随薄膜厚度改变符号的相互作用，即同一纹理不同层间及相邻三维弦之间出现吸引与排斥的切换。这种垂直不对称的吸引-排斥相互作用驱动正方与三角弦晶格之间的可调谐转变，与实验观察相符，揭示了三维拓扑自旋纹理的层分辨结构和内部奇异性对层内相互作用的根本性影响，超越了刚性管相互作用模型。","scd":{"b":8.0,"i":2.0,"r":6.5,"d":6.0,"t":4.0},"kp":[]},{"i":60006,"as":"高充电深度循环可提升钠离子电池层状氧化物正极能量密度，但会引发严重结构和界面退化。该研究以NaNi1/3Fe1/3Mn1/3O2（NFM111）为原型，采用电压切换策略阐明高充电深度（充电至4.3 V）造成的损伤区域在恢复至中等充电深度循环后的动态和长期演变行为，为电池管理系统在能量密度与循环寿命之间的权衡提供依据。","scd":{"b":7.0,"i":4.0,"r":6.0,"d":7.0,"t":5.0},"kp":["降解抑制策略[O3型NaNi1/3Fe1/3Mn1/3O2钠电阴极]: 电压切换策略抑制高充电深度循环引发的界面降解","核心问题[钠电层状氧化物阴极]: 高DoC循环引发严重结构与界面退化，需在能量密度与循环寿命间权衡"]},{"i":60007,"as":"受人类皮脂物理保护和信号调节功能启发，研究人员开发了由磷酸钨酸钙亚纳米线（PWC）和角鲨烯（Sql，皮脂天然成分）组成的仿生皮脂有机凝胶用于无疤痕伤口愈合。PWC以高粘附力凝胶化角鲨烯，实现伤口滞留和角鲨烯缓释。释放的角鲨烯整合进成纤维细胞质膜，增强脂质双层流动性，通过促进膜相关细胞骨架适应缓解伤口张力，进而抑制YAP蛋白激活，实现疤痕-free愈合。","scd":{"b":8.0,"i":4.0,"r":6.0,"d":7.0,"t":5.0},"kp":["仿生皮脂有机凝胶[无疤痕伤口愈合]: 由磷钨酸钙亚纳米线(PWC)与角鲨烯组成，PWC使角鲨烯凝胶化并高黏附力于伤口滞留与缓释"]},{"i":60008,"as":"研究人员开发离子调控自组装策略合成介孔萨伦（Salen）聚合物纳米球（mDSR）用于光催化海水提铀。部分电离提高原本不溶性Salen配体的水溶性和与甲醛的反应性，同时保持足够的前体-胶束共组装相互作用，引导有序介观结构形成。该策略简便、通用，可容纳一系列结构不同的Salen配体，实现介孔材料的模块化构建，为高性能海水提铀材料设计提供新途径。","scd":{"b":8.0,"i":4.0,"r":6.0,"d":7.0,"t":5.0},"kp":["介孔萨伦聚合物纳米球[光催化海水提铀]: 通过离子调控自组装策略合成，部分离子化提升水溶性及对铀的反应性"]},{"i":60009,"as":"","scd":null,"kp":[]},{"i":60010,"as":"","scd":null,"kp":[]},{"i":60011,"as":"","scd":null,"kp":[]},{"i":60012,"as":"","scd":null,"kp":[]},{"i":60013,"as":"","scd":null,"kp":[]},{"i":60014,"as":"研究报道了一种受中性粒细胞启发的可编程细菌（NPB）系统，结合合成生物学与分子工程技术开发。以非致病性大肠杆菌MG1655为载体，模拟中性粒细胞的'归巢-爆破-杀伤'逻辑执行四阶段程序：优先归巢至缺氧肿瘤区域；通过VHb介导的ROS生成实现超声动力学的细菌裂解与按需载荷释放；响应肿瘤相关明胶酶激活Granzyme B酶原；最终经细胞焦亡介导肿瘤消融，实现时空可控的抗肿瘤治疗。","scd":{"b":8.5,"i":4.0,"r":6.0,"d":7.0,"t":5.0},"kp":["可编程细菌系统[中性粒细胞启发抗肿瘤]: 采用非致病性大肠杆菌MG1655，执行'归巢-爆裂-杀伤'四阶段程序并具备时空可控性"]},{"i":60015,"as":"","scd":null,"kp":[]},{"i":60016,"as":"电催化氨氧化反应（AOR）因氨可作为无碳燃料和便捷氢载体而备受关注，但其高过电位和快速催化剂中毒机制尚不清楚。研究通过温度依赖循环伏安法、电化学Arrhenius分析结合红外光谱，研究多晶Pt上反应物种随过电位依赖的形成过程，并通过CO置换测量将动力学参数演化与极化程度和过剩电荷相关联。研究发现随过电位升高，一种反应物种平行形成，揭示了界面过剩电荷对反应的影响。","scd":{"b":7.0,"i":3.0,"r":6.0,"d":6.0,"t":4.0},"kp":["氨氧化反应机理[多晶Pt电极、温度依赖伏安法]: 揭示反应物种的电势依赖性形成及其对界面过剩电荷的影响"]},{"i":60017,"as":"","scd":null,"kp":[]},{"i":60018,"as":"针对糖尿病伤口血管供血不足、细菌感染和持续炎症等挑战，研究设计了三重协同纳米酶平台：将葡萄糖氧化酶（GOx）和羰基锰（MnCO）共负载于卟啉共价有机框架。近红外照射下Por-COF产生活性氧和局部热疗；GOx消耗伤口葡萄糖生成葡萄糖酸和H2O2，触发MnCO分解释放免疫调节性一氧化碳和催化活性Mn2+/3+离子，Mn2+/3+催化H2O2分解，实现抗菌、抗炎和促血管生成的协同修复效果。","scd":{"b":7.0,"i":3.0,"r":5.0,"d":6.0,"t":4.0},"kp":["三重协同纳米酶平台[糖尿病伤口修复]: 卟啉COF共载葡萄糖氧化酶(GOx)与羰基锰，兼具抗菌、抗炎和促血管生成功能"]},{"i":60019,"as":"在复杂曲面上制备导电电路是共形电子学的重大挑战。研究报道了一种GOPS辅助的保形转印策略，将喷墨打印的PEDOT:PSS图案集成到难以打印的非平面表面。导电图形先在平面聚酰亚胺供体基底上定义，再转印到目标基底。GOPS（3-缩水甘油醚氧丙基三甲氧基硅烷）的引入促进强共价键合，确保转印图案优异的界面粘附和结构完整性，兼容多种非平面基底。","scd":{"b":6.0,"i":4.0,"r":5.0,"d":6.0,"t":4.0},"kp":["转印工艺[PEDOT:PSS图案]: GOPS辅助保形转印，将喷墨打印的图案从平面聚酰亚胺供体基底转印至复杂曲面"]},{"i":60020,"as":"水凝胶吸附剂因其可调化学结构、水合网络和多功能纳米材料兼容性，成为环境修复和传感的多功能材料，但传统静态水凝胶受限于扩散控制的传质、缓慢的吸附动力学及检测与修复功能难以集成。本综述重点介绍从被动吸附向动态可驱动水凝胶的转变，作为'感知-响应-行动'自适应材料系统，实现加速污染物捕获、实时监测和自主再生，并讨论了静态水凝胶的聚合物组成、纳米材料复合和结构架构设计原则。","scd":{"b":5.0,"i":3.0,"r":6.0,"d":5.0,"t":3.0},"kp":["动态可驱动水凝胶[环境传感与修复]: 从被动吸附转向动态驱动，克服扩散限制的传质与慢吸附动力学"]},{"i":60021,"as":"胶体量子点薄膜是溶液法光电探测器件的核心，但兼顾器件性能与材料利用率的可规模沉积方法有限。研究采用双相弯月面浸涂策略，活性量子点薄层由不互溶的下层支撑，薄膜仅在活性相的液-气界面形成，大幅减少活性纳米晶溶液用量。利用该几何结构制备的PbS量子点光电探测器在1200 nm处响应度高达约1000 mA/W，与旋涂器件性能相当，同时相比旋涂显著降低活性材料消耗。","scd":{"b":6.0,"i":4.0,"r":5.0,"d":6.0,"t":4.0},"kp":["双相浸涂策略[胶体量子点薄膜]: 由互溶下层支撑薄cQD层，可控沉积并大幅减少纳米晶溶液用量"]},{"i":60022,"as":"锰基水系锌离子电池因安全性、低成本和环保性被视为大规模储能的有力候选，但锰基正极导电性差、结构不稳定，尤其是循环中活性物质溶解，限制了实际应用。本研究通过机械化学反应合成掺镧二氧化锰（La掺杂MnO2）并退火处理，镧的掺入显著提升MnO2的导电性和结构稳定性，所得正极展现出更高的比容量和增强的电化学性能。","scd":{"b":6.0,"i":4.0,"r":5.0,"d":7.0,"t":4.0},"kp":["掺镧MnO2正极[水系锌离子电池]: 机械化学法合成，改善导电性、结构稳定性并抑制循环中活性材料溶解"]},{"i":60023,"as":"NASICON型NaTi2(PO4)3因高结构稳定性和安全性成为钠离子电池备受关注的电极材料，但其本征电子导电性低限制了高倍率和低温性能。研究通过溶剂热法合成富氧空位的Na1.3Ti1.8Ni0.1Sb0.1(PO4)3@C纳米粉体。Ni2+/Sb5+共掺杂有效调控TiO6/PO4局域晶格环境，引入氧空位并优化晶格电子结构，增强电子和离子传输；连续碳包覆构建稳定导电网络，进一步改善动力学和结构完整性，实现高倍率低温钠离子存储。","scd":{"b":6.5,"i":4.0,"r":5.0,"d":8.0,"t":4.0},"kp":["富氧空位NASICON阳极[钠离子电池]: Na1.3Ti1.8Ni0.1Sb0.1(PO4)3@C通过溶剂热法合成，Ni2+/Sb5+共掺杂调制局部结构实现高倍率低温储钠"]},{"i":60024,"as":"CVD生长的范德华异质结构为光电应用提供可扩展平台，但界面无序、层间耦合差异及光谱特征重叠使激子光谱指认困难。研究采用两种不同的单步CVD工艺合成连续大面积（达600 μm）MoS2/WS2垂直异质结构，实现不同界面质量下激子行为的系统比较。结合变温光致发光和超低频拉曼光谱，解析了不同层间激子光谱特征的演化，揭示了界面质量驱动的层间激子和混合激子演变规律。","scd":{"b":7.0,"i":4.0,"r":6.0,"d":7.0,"t":4.0},"kp":["异质结构面积[CVD生长MoS2/WS2垂直异质结]: 达600 μm","制备方法[大面积连续垂直异质结]: CVD化学气相沉积","激子光谱特征[MoS2/WS2异质结]: 层间激子与混合激子界面驱动演化"]},{"i":60025,"as":"慢性糖尿病伤口因神经病变、血管病变和慢性炎症等复杂病理微环境成为重大临床挑战。受户外攀岩启发，研究开发了具有分层孔径的多功能生物活性水凝胶支架（CSP水凝胶），通过3D打印和光聚合由甲基丙烯酰化壳聚糖（CSMA）和甲基丙烯酰化丝素蛋白制成，形成宏孔（≥100 μm）、介孔（1-50 μm）和微孔的多尺度多孔结构，重塑伤口微环境并增强间充质干细胞的再生修复效果。","scd":{"b":6.0,"i":3.0,"r":5.0,"d":6.0,"t":4.0},"kp":["支架结构[3D打印水凝胶支架CSP]: 分级孔隙结构","功能[工程化分级孔隙水凝胶]: 重塑糖尿病伤口微环境、促进间充质干细胞再生修复","制备方式[多功能生物活性水凝胶支架]: 3D打印"]},{"i":60026,"as":"层数可控的有机薄膜是有机电子器件的关键组件，层转移方法虽适用于器件原型制备，但过程中裂纹形成难以控制。研究以双层分子半导体薄膜为模型研究断裂力学，发现裂纹形成强烈依赖薄膜厚度，当薄膜减至单分子双层（SMB）厚度时裂纹被抑制。厚膜中观察到的裂纹方向性与晶取向明显相关，这些断裂行为可通过宏观弹性模型与分子间相互作用计算相结合定性解释，由此发展出抑制裂纹的转移方法。","scd":{"b":6.0,"i":2.0,"r":5.0,"d":6.0,"t":4.5},"kp":["裂纹控制[双层有机半导体薄膜转移]: 裂纹形成强烈依赖薄膜厚度，特定厚度下被抑制","研究方法[裂纹抑制转移工艺]: 双层有机半导体薄膜断裂力学分析"]},{"i":60027,"as":"储备层计算是连接人工智能与物理环境的桥梁，其实现依赖能响应外部刺激模拟神经生物可塑性的人工突触，但现有人工突触运行时仅耗散能量。研究提出基于石墨烯超级电容器的储能型储备层架构，通过金属辅助微波还原制备的还原氧化石墨烯电极具有介孔结构和低缺陷密度，超级电容器在特定电流密度下比电容达352 F g-1，为神经形态计算中的储备层预处理提供高性能突触器件。","scd":{"b":6.5,"i":2.0,"r":5.0,"d":6.0,"t":4.5},"kp":["储能功能[石墨烯超级电容人工突触]: 兼具能量存储与储备池计算预处理","制备方法[石墨烯超级电容突触]: 微波合成"]},{"i":60028,"as":"光辅助锌-空气电池为太阳能转换与存储提供一体化路径，但受空气电极缓慢的双功能氧电催化限制。研究开发了金纳米颗粒修饰TiO2/NiO纳米锥阵列空气电极用于光辅助锌-尿素-空气电池。纳米锥TiO2结构增强宽带光捕获、局域电场强度和界面反应物富集，TO/NiO异质结促进光生电荷分离。365 nm光照下，光生空穴优先迁移至Ni活性位点加速尿素氧化，降低充电极化，Au纳米颗粒则作为局域等离激元功能单元提升性能。","scd":{"b":6.5,"i":2.5,"r":5.0,"d":6.5,"t":4.5},"kp":["电极结构[光辅助Zn−尿素−空气电池]: Au纳米颗粒修饰TiO2/NiO纳米锥阵列（Au/n-TO/NiO）","纳米锥结构作用[TiO2纳米锥空气电极]: 增强宽谱光捕获、局域电场强度和界面反应物富集"]},{"i":60029,"as":"传统结构有机太阳能电池（OSCs）虽然光电转换效率较高，但热稳定性差，主要归因于阴极界面降解机制不明。研究系统考察了PM6:L8-BO/PDINN/Ag结构中电子传输层PDINN的热失效机制，识别出两阶段降解路径：初期加热阶段，PDINN降解诱导阴极接触附近活性层的n型掺杂，降低短路电流密度；持续热应力下，Ag-穿透PDINN层迁移，产生深空穴陷阱并改变阴极功函数，导致器件性能进一步衰减。","scd":{"b":5.5,"i":2.0,"r":5.0,"d":6.0,"t":4.5},"kp":["器件结构[有机太阳能电池]: PM6:L8-BO/PDINN/Ag","热失效机制[PDINN/Ag阴极界面]: 两阶段降解路径"]},{"i":60030,"as":"HgSe胶体量子点因可溶液加工的带隙可调性，成为长波红外（8-14 μm）光电探测的有力候选，但裸露HgSe量子点表面缺陷密度高、易氧化，严重影响光电性能。研究提出简单的两步法生长高质量HgSe/PbS核壳量子点，协同优化PbS壳层厚度以实现表面钝化和提升HgSe核的抗氧化性，并基于金属-半导体-金属（MSM）结构探索其在室温长波红外探测中的应用。","scd":{"b":6.0,"i":2.0,"r":5.5,"d":6.0,"t":4.5},"kp":["探测波段[HgSe/PbS核壳胶体量子点光电探测]: 室温长波红外（8–14 μm）","合成方法[HgSe/PbS核壳量子点]: 简单两步法","缺陷问题[裸HgSe胶体量子点]: 高表面缺陷密度和易氧化"]},{"i":60031,"as":"室温半导体晶体需兼具高电阻率、高效电荷传输和明确的缺陷结构，是直接转换辐射探测的核心。研究首次报道层状硒磷酸盐6LiInP2Se6的直接转换X射线响应，并行推进两种晶体生长路线：化学气相输运法（CVT）优化用于高纯薄片，以及带迭代纯化的Bridgman-Stockbarger法放大至厘米级晶锭。两种方法所得单晶具有洁净(00l)表面，粉末XRD、拉曼和显微表征一致，光电子产额谱显示带边对齐匹配，并通过热刺激电流谱表征缺陷结构及α粒子光谱响应。","scd":{"b":7.0,"i":2.0,"r":6.0,"d":6.5,"t":4.5},"kp":["晶体生长路线[6LiInP2Se6单晶]: 化学气相输运（CVT，优化薄型高纯度片晶）与Bridgman–Stockbarger法（迭代纯化）","功能[层状硒磷酸盐LIPSe]: 首次实现直接转换X射线响应","关键性能[室温半导体辐射探测晶体]: 高电阻率、高效电荷传输、明确缺陷结构"]},{"i":60032,"as":"研究设计了一种UV固化聚丙烯酸酯导电复合薄膜(PAAC)，通过可逆氢键赋予增强的弹性回复能力。首先以丙烯酸单体和乙烯基封端聚氨酯预聚体为交联剂，经UV引发聚合制备聚丙烯酸酯薄膜，具有高透明度(>90%)、耐溶剂性(>72小时)、良好的机械强度和耐折叠性。随后引入可聚合深共熔溶剂(丙烯酸/氯化胆碱，AA/ChCl)，实现可逆动态键驱动的共变形导电复合薄膜，满足柔性电子对机械强度、弹性回复和可靠导电性的需求。","scd":{"b":5.0,"i":2.0,"r":4.5,"d":5.5,"t":4.0},"kp":["弹性恢复机制[UV固化聚丙烯酸酯导电复合薄膜PAAC]: 可逆氢键弹性驱动","制备方法[聚丙烯酸酯导电复合膜]: UV引发聚合（丙烯酸酯单体+乙烯基封端，含ChCl）"]},{"i":60033,"as":"研究构建了结合第一性原理计算与分析传输模型的多尺度框架，用于量化金属-TMD结中依赖应变的接触电阻。研究了n型Au/MoS2和p型Pd/WSe2接触在顶部和边缘几何构型下、实验可及应变范围(-1%至+1%)内的表现。结果表明，拉伸应变可使n型接触电阻每1%应变降低高达46%，而压缩应变则降低p型接触电阻。该框架建立了应变诱导电子结构变化与界面载流子注入之间的预测性联系，为降低二维半导体晶体管的接触电阻瓶颈提供了指导。","scd":{"b":6.0,"i":2.0,"r":5.0,"d":6.0,"t":4.5},"kp":["研究框架[应变依赖接触电阻预测]: 第一性原理计算结合解析传输模型的多尺度框架","技术作用[应变工程]: 可降低二维金属-半导体界面接触电阻"]},{"i":60034,"as":"受甲虫表皮结构启发，研究提出仿生自发界面重构策略，构建兼具双疏性(疏水疏油)和防污抗菌功能的多功能涂层。采用快速(5分钟内)、环境友好的UV固化工艺制备了生物基双疏抗菌涂层(PCGBF@GT)，通过低表面能富集与生物活性分子相互作用的协同效应，实现含氟组分的自发迁移。该涂层面向海洋装备和医疗植入体等先进系统的表面保护，应对污损和微生物沉积造成的不可逆降解问题，同时兼顾多功能性、环境相容性和耐久性。","scd":{"b":5.0,"i":2.0,"r":4.5,"d":5.5,"t":4.0},"kp":["涂层策略[仿生界面自发重构]: 仿甲虫角质层结构构建多功能双疏涂料","功能特性[生物基UV固化涂料]: 双疏性、防污、抗菌、环境友好与耐久性集成"]},{"i":60035,"as":"针对轴向硅氧烷取代硅酞菁因前线轨道能量较高而呈p型行为的问题，研究合成了两种新型氯化硅氧烷硅酞菁(Si4O)2SiPcCl8和(Si4O)2SiPcCl16，旨在降低LUMO能级实现n型传输。外围氯化有效将LUMO能级分别降至-3.8和-4.0 eV，证实了预期的电子调制效果。单晶X射线衍射表征了其结构，并将其集成到有机薄膜晶体管(OTFT)中，为开发空气稳定的n型有机半导体提供了新途径。","scd":{"b":6.0,"i":2.0,"r":5.0,"d":6.0,"t":4.5},"kp":["半导体材料[硅酞菁衍生物]: 轴向硅氧烷取代氯化硅酞菁实现p型向n型转变","性能水平[硅氧烷SiPcs]: 创纪录电荷迁移率但需解决空气稳定性n型行为"]},{"i":60036,"as":"研究采用一维纳米结构与精确Ga掺杂相结合的协同策略，制备高性能铟镓锡氧化物(IGTO)纳米纤维场效应晶体管。优化的5% Ga掺杂通过强Ga-O键有效抑制氧空位(从38.8%降至29.7%)，实现2.79 cm2 V-1 s-1的优异迁移率、4.15×10^7的高开关比、0.50 V/dec的陡峭亚阈值摆幅及出色的偏置应力稳定性，克服了氧化物半导体中迁移率-稳定性的权衡。该器件展现可调双波段光响应(340 nm紫外和430 nm可见光)，成功模拟突触行为，可用于双频带神经形态视觉和光学加密。","scd":{"b":6.5,"i":3.0,"r":5.0,"d":8.0,"t":5.0},"kp":["Ga掺杂浓度[IGTO纳米纤维优化]: 5%","氧空位抑制[5% Ga掺杂]: 从38.8%降至29.7%","迁移率[IGTO纳米纤维FET]: 2.79 cm2 V–1 s–1","开关比[IGTO纳米纤维FET]: 4.15 × 107","亚阈值摆幅[IGTO纳米纤维FET]: 0.50 V/dec"]},{"i":60037,"as":"","scd":null,"kp":[]},{"i":60038,"as":"研究从晶体学数据库自动提取单核Dy配合物条目，采用多参考从头算方法计算其磁各向异性，并生成并模拟了2.5万个通式为[Dy(H2O)5L2]n+、具有五角双锥配位几何的新分子的磁各向异性，该构型因性质优异且具合成可行性被选为目标。通过微调有机配体最大化Dy配合物的磁各向异性，系统探索了相关化学空间，为设计具有大磁各向异性和慢磁弛豫性质的分子磁性材料提供了高通量筛选框架。","scd":{"b":7.0,"i":2.0,"r":6.5,"d":7.0,"t":5.0},"kp":["高通量筛选范围[Dy配合物磁性设计]: 超过25k单核Dy配合物","计算方法[磁各向异性预测]: 多参考从头算方法"]},{"i":60039,"as":"采用新颖两步策略改进热化学水分解中太阳能还原反应的反应器设计与性能，提升制氢效率。","scd":{"b":5.5,"i":3.5,"r":5.0,"d":3.5,"t":5.0},"kp":["反应器策略[太阳能热化学水分解]: 新颖两步法改进太阳能还原反应器设计与性能"]},{"i":60040,"as":"研究报道了一种钴催化C-H键官能化的新方法，采用双定向基团策略，在温和条件下实现非活化C(sp3)-H键的官能化。第二、三行过渡金属催化C(sp3)-H官能化已成熟并用于复杂天然产物合成，而丰产的第一行金属此前主要用于C(sp2)-H键官能化，用于非活化C(sp3)-H键(非苄位、非杂原子α位)时罕见，且受限于无法官能化二级C-H键、反应温度高及需多当量银(I)氧化剂等问题。新策略克服了这些限制。","scd":{"b":6.0,"i":2.0,"r":5.0,"d":5.5,"t":5.0},"kp":["催化体系[非活化C(sp3)-H键官能化]: 钴催化、氨基喹啉定向、温和条件","技术特点[第一行过渡金属]: 实现非活化C(sp3)-H键罕见转化"]},{"i":60041,"as":"研究报道了序列定义的“数字”瓶刷聚合物库，可精确控制脂质、胆固醇和阳离子基团等化学基元沿聚磷酸二酯骨架的排布，调控理化性质。系统评估揭示了明确的结构-性质关系。传统均一骨架瓶刷聚合物只能实现不可改变的刚性生物分布，而该数字瓶刷聚合物平台可编程修饰生物分布特征，用于解决寡核苷酸疗法面临的快速肾/肝清除和器官特异性差等递送障碍，实现可编程的寡核苷酸递送。","scd":{"b":7.0,"i":2.0,"r":5.5,"d":5.5,"t":5.0},"kp":[]},{"i":60042,"as":"研究报道了完整的同构八面体系列(allLH)2MCl2(M=Mn至Zn)，由黄素衍生双齿配体allLH支持。该配体提供的外层N-H···Cl氢键网络将所有配合物锁定为单一经式异构体，实现跨第一过渡金属系的热力学直接比较。欧文-威廉姆斯系列(Mn<Fe<Co<Ni>Cu>Zn)是高自旋二价第一过渡金属配合物的成熟稳定性趋势，但完整同构系列罕见。该工作解决了外层非共价相互作用能否在不改变一级配位环境的情况下改变这一周期性趋势的问题。","scd":{"b":6.0,"i":1.5,"r":5.0,"d":5.0,"t":4.5},"kp":["研究发现[Mn-Zn等结构系列]: 外层氢键可改变欧文-威廉姆斯稳定性趋势而不改变初级配位环境"]},{"i":60043,"as":"本文作者Shwetha Prakash介绍了原位拉曼光谱如何用于实时研究电化学过程。原位拉曼光谱作为一种表征技术，能够在电化学系统运行过程中直接观测界面反应和中间物种，为电化学机理研究提供实时信息。本文属于技术解说类内容，正文仅提供了该要旨介绍，未包含具体实验数据或详细技术参数。","scd":{"b":3.5,"i":2.0,"r":4.5,"d":2.5,"t":4.0},"kp":["表征技术[电化学系统]: 原位拉曼光谱实时研究电化学过程"]},{"i":60044,"as":"本综述探讨卤化锡钙钛矿光伏电池的效率与耐用性问题。卤化锡钙钛矿是传统铅基钙钛矿光伏材料的无铅替代方案，但其效率受易于形成缺陷和易氧化问题的限制。综述考察了可能使这类材料实现商业化可行光伏的材料与器件工程策略，涵盖缺陷调控、氧化抑制等方向，为实现高效稳定的无铅钙钛矿太阳能电池提供指导。","scd":{"b":5.5,"i":4.0,"r":6.0,"d":6.0,"t":5.0},"kp":["材料特性[卤化锡钙钛矿]: 无铅替代传统钙钛矿光伏","性能限制[卤化锡钙钛矿]: 易形成缺陷和氧化限制效率","改进方向[商用化]: 材料与器件工程协同提升效率和耐用性"]},{"i":60045,"as":"研究报道了一种半夹心锇(II)配合物Os-1，可作为肿瘤化学免疫疗法的催化触发剂。Os-1通过自催化氢化物转移(从辅酶NADH到氧气)催化生成H2O2，持续的H2O2自我供给破坏肿瘤氧化还原稳态并诱导DNA损伤，进而激活cGAS-STING信号通路。Os-1在体外表现出强细胞毒性，并在体内引发强烈的抗肿瘤免疫反应，为金属基抗癌剂在化学免疫治疗中的应用提供了新范例。","scd":{"b":6.5,"i":2.0,"r":5.0,"d":5.5,"t":5.0},"kp":["催化机制[半夹心锇(II)配合物Os-1]: 催化H2O2生成触发肿瘤化学免疫治疗","药物类型[氧化异阿朴啡衍生物]: 先天性肿瘤化学免疫疗法催化触发剂"]},{"i":60046,"as":"研究开发了一种基于可靠性的混合整数非线性规划(MINLP)框架，采用随机优化方法同时优化绿色制氢系统的技术选择、子系统规模、维护规划和可用性投资决策，以绿氨作为长距离运输的下游能源载体。该框架综合考量可靠性、维护和可再生能源资源可变性，适用于不同电网连接和需求条件。加拿大东部案例研究确定了以风电为主的配置方案，应对绿色氢气大规模部署面临的高成本和运行经验有限等制约。","scd":{"b":6.0,"i":3.0,"r":6.0,"d":7.0,"t":4.0},"kp":["规划框架[绿氢系统设计]: 基于可靠性的混合整数非线性规划(MINLP)与随机优化","主要挑战[绿氢大规模部署]: 高成本、运行经验有限、缺乏集成规划框架"]},{"i":60047,"as":"针对电力灵活性市场中需求侧资源异质性强、拓扑约束与动态用户偏好交织导致静态聚类失效的问题，研究提出电网感知的状态自适应混合聚类(SAHC)方法。与刚性拓扑分区不同，SAHC采用谱方法捕捉电网物理与经济行为间的非线性交互，并集成了日前初始化机制。该方法解决了频繁重聚类带来的运行波动和近实时运行下数学难解的问题，在稳定性与效率之间取得平衡，将细粒度灵活性资源聚合为稳定的交易产品以实现高效电网拥塞管理。","scd":{"b":6.0,"i":4.0,"r":6.0,"d":6.0,"t":4.0},"kp":["聚类方法[灵活性市场资源聚合]: 自适应谱聚类","技术问题[需求侧灵活性]: 静态聚类因拓扑约束与动态用户偏好耦合而失效"]},{"i":60048,"as":"研究报道了可见光诱导、镍催化的平台技术，实现未活化烯烃的自由基1,2-二碳官能化，无需使用定向基团即可解决区域选择性难题。该平台采用多样的烷基自由基前体，以及芳基、乙烯基、酰基、炔基和烷基偶联 partner，构建富sp3的三维分子架构。机理研究支持一个由多个电子给体-受体(EDA)复合物介导的催化循环，涵盖自由基生成、原子转移自由基加成(ATRA)和交叉电亲体偶联(XEC)步骤，为药物化学的多组分交叉偶联提供了模块化平台。","scd":{"b":8.0,"i":3.0,"r":7.0,"d":7.0,"t":5.0},"kp":["催化平台[未活化烯烃1,2-二碳官能化]: 可见光诱导镍催化，无需导向基团的自由基1,2-二碳官能化"]},{"i":60049,"as":"提出SIG-LLM方法，利用语义知情门控大语言模型进行时空多能源需求预测，提升预测精度。","scd":{"b":6.0,"i":3.0,"r":5.0,"d":3.0,"t":4.0},"kp":["预测方法[时空多能源需求]: 语义知情门控大语言模型(SIG-LLM)"]},{"i":60050,"as":"研究提出分子催化剂的全新角色：作为可逆CO穿梭体增强双电层局部CO活度。使用水溶性铁卟啉作为CO穿梭体，在水系电解质中实现了从CO2生成经同位素验证的C1-C4烃类产物。即使在没有铁卟啉的CO饱和电解质中也不产生这些产物，表明穿梭体使电极表面局部CO活度超越了体相饱和所能达到的水平。电化学和光谱数据支持稳定FeII-CO物种的形成。该策略突破了均相分子催化剂电化学CO2还原通常仅限二电子还原C1产物(主要是CO)的限制。","scd":{"b":9.0,"i":3.0,"r":8.0,"d":8.0,"t":6.0},"kp":["CO穿梭催化剂[水相电化学CO2还原]: 水溶性铁卟啉作为可逆CO穿梭","产物[CO2电还原]: 同位素验证的C1–C4烃类（水系电解液）"]},{"i":60051,"as":"本展望综述了分子催化下烷烃和烷基官能化的演变，从基础有机金属化学挑战发展为升级烃类原料和修饰复杂分子的变革性技术。文章强调成熟的双电子路径与新兴自由基介导反应模式的战略分歧：对结构无偏的简单烷烃脱氢，研究仍集中于贵金属基分子催化剂，以钳形-过渡金属体系为代表，其活性和区域选择性不仅受催化剂一级配位球控制，还受配体骨架的微妙影响；而对具有电子偏向性烃类的脱氢，自由基路径展现出不同优势。","scd":{"b":6.0,"i":3.0,"r":6.0,"d":6.0,"t":4.0},"kp":["反应路径[烷烃脱氢演化]: 双电子路径与新兴自由基介导路径的战略分化"]},{"i":60052,"as":"研究通过开发配体交换方法，成功合成了迄今最大的全有机配体保护铂纳米团簇[Pt19(NapNC)27][PF6]2(简称Pt19；NapNC为异腈萘)。单晶表征确认其原子级精确结构。全有机配体可显著增强金属纳米团簇的稳定性和可调性，但由于合成难度大，全有机配体保护的铂纳米团簇此前极少报道。该Pt19纳米团簇展现出增强的稳定性和电催化活性，推动了铂纳米团簇研究及其实际应用，铂在催化和癌症治疗等领域不可或缺。","scd":{"b":7.0,"i":3.0,"r":7.0,"d":7.0,"t":5.0},"kp":["纳米团簇[全有机配体保护铂]: 原子级精确Pt19，最大全有机配体保护铂纳米团簇，稳定性与电催化活性增强"]},{"i":60053,"as":"研究受酶系统启发，提出主客体策略控制水介质中的CO2电催化还原：将[bpyMn(CO)3MeCN]+催化剂封装于阴离子笼中并固定在电极表面，该组装体选择性生成CO。机理研究表明，笼通过空间限域和非共价相互作用促进质子耦合的CO2结合，同时抑制副反应。该工作属于第二配位球工程，即通过金属中心之外的Outer-sphere环境调控催化反应活性与选择性，超越了传统配体设计调控活性和选择性的思路，实现了水中选择性和稳健的CO2电催化。","scd":{"b":7.0,"i":3.0,"r":6.0,"d":7.0,"t":5.0},"kp":["催化策略[水介质选择性CO2电催化]: 主客体（酶启发）策略，利用第二配位层空间限域与非共价相互作用"]},{"i":60054,"as":"研究提出双位点工程策略，在单一磁性纳米石墨烯中实现自旋调制与电荷态独立调控。设计合成了氮硫共工程化[3]三角烯（N,S-Tri），包含中心氮位点，将本征自旋调制与吸附及场控电荷态调谐相结合，实现此前未有的多功能控制水平。开壳层纳米石墨烯具有高度可调的关联磁性态，是构建面向分子级自旋电子学和量子信息技术的石墨烯纳米磁体的平台，但其磁性态通常受拓扑约束和强电子关联限制。该策略突破了自旋与电荷自由度难以独立控制的问题。","scd":{"b":8.0,"i":2.0,"r":7.0,"d":7.0,"t":5.0},"kp":[]},{"i":60055,"as":"研究开发了单颗粒电化学方法，在钴镍氮共掺杂石墨烯（CoNi-NG）电催化剂上研究铝硫电池中的硫还原反应（SRR）过程。发现SRR主要路径为S8→Al2S8→Al2S4→Al2S3，次要路径为Al2S8→Al2S6→Al2S4；其中Al2S4转化决定整体SRR动力学，且Al2S4因生成最快、消耗最慢而对穿梭效应贡献最大。CoNi-NG可提升Co d轨道能级。该研究对合理电催化改善动力学缓慢的SRR、释放铝硫电池超高容量的能量输出至关重要。","scd":{"b":7.0,"i":3.0,"r":7.0,"d":7.0,"t":5.0},"kp":["电催化剂[铝硫电池硫还原反应]: 钴镍氮共掺杂石墨烯","研究方法[SRR过程解读]: 单颗粒电极电化学方法"]},{"i":60056,"as":"针对多元氧化物电催化剂组分空间庞大、传统漏斗式筛选将高保真数据视为二元门槛的局限，研究提出专家指导的多尺度框架用于Pr-Sr-Co-Fe钙钛矿。该框架整合原子描述符、实验结构特征和机制导向的电子特征，并通过“最近网格插值”策略将搜索空间内高保真密度泛函理论计算成本降低近两个数量级。两轮主动学习显著提升了发现效率，在描述符可及的多元钙钛矿空间内高效探索电催化剂。","scd":{"b":7.0,"i":3.0,"r":6.0,"d":7.0,"t":5.0},"kp":["探索框架[多元钙钛矿电催化剂Pr–Sr–Co–Fe]: 专家指导的多尺度框架，整合原子描述符、实验结构特征与机制导向电子特征"]},{"i":60057,"as":"","scd":null,"kp":[]},{"i":60058,"as":"研究引入生成式AI驱动推断（GPI）统计框架，利用文本和图像等非结构化数据进行因果推断。GPI利用开源预训练生成式AI模型（如大语言模型和扩散模型）大规模生成非结构化数据，并提取保证捕获其底层结构的低维表示，再对这些表示应用机器学习估计因果效应并量化不确定性。与现有表示学习方法不同，GPI无需微调生成式AI模型，计算高效且易于广泛使用，并通过多个应用展示其通用性。","scd":{"b":7.5,"i":3.0,"r":7.0,"d":6.0,"t":5.0},"kp":["[GPI框架]: 利用开源预训练生成式AI模型（大语言模型和扩散模型）生成非结构化数据并提取保证捕获其底层结构的低维表示","[GPI应用]: 基于表示的机器学习实现因果推断估计"]},{"i":60059,"as":"","scd":null,"kp":[]},{"i":60060,"as":"","scd":null,"kp":[]},{"i":60061,"as":"","scd":null,"kp":[]},{"i":60062,"as":"","scd":null,"kp":[]},{"i":60063,"as":"","scd":null,"kp":[]},{"i":60064,"as":"研究引入增强的全势线性缀加平面波（FLAPW）方法，在锕系固体（Ac、Th、ThO2和UO2）中纳入价态的小狄拉克分量，特别是6p1/2半芯态。计算表明，考虑这些小分量后，原子核处的价电子密度增加2.4至4.3倍，纠正了忽略原子核附近显著价电子密度的标准计算近似。改进的相对论狄拉克计算为内转换、穆斯堡尔谱和电子桥效应等核现象提供更高理论精度和电子结构基础。","scd":{"b":6.0,"i":2.0,"r":7.0,"d":7.0,"t":5.0},"kp":["价电子密度增益[锕系固体含小狄拉克分量]: 增大2.4至4.3倍","计算方法[锕系固体Ac/Th/ThO2/UO2]: 纳入6p1/2半芯态小狄拉克分量的增强全势线性缀加平面波(FLAPW)方法"]},{"i":60065,"as":"","scd":null,"kp":[]},{"i":60066,"as":"Stellantis旗下循环经济业务部门SUSTAINera正在扩展其翻新零部件产品线，重点面向纯电动和插电式混动车型，目前已为Stellantis旗下大多数BEV和PHEV车型提供翻新高电压电池。该部门致力于在4R战略（再制造、维修、再利用、回收）框架下开发解决方案，延长产品寿命、避免浪费、节约资源并降低碳足迹，包括拆解和翻新车辆零部件使其作为备件在其他车辆上重新使用。其翻新零部件业务此前集中于燃油车，现正扩展至电动车领域。","scd":{"b":3.0,"i":8.0,"r":6.0,"d":4.0,"t":6.0},"kp":["翻新业务模式[Stellantis循环经济SUSTAINera]: 4R战略（再制造、维修、再利用、回收）","高压电池翻新覆盖范围[Stellantis BEV/PHEV车型]: 适用于旗下大部分纯电和插混车型"]},{"i":60067,"as":"Vulcan Energy发布了其在上莱茵河谷第二个锂和地热项目Ludwig的预可行性研究。该项目位于德国路德维希港地区，预计年产21,100吨碳酸锂，基于Landau附近更成熟的Lionheart项目经验建设。在做出投资决策前仍需完成多个开发步骤。Vulcan还在法兰克福Höchst建设一座锂加工厂。该公司为德澳合资企业，计划从富锂地热资源中提取锂。","scd":{"b":4.0,"i":5.0,"r":7.0,"d":7.0,"t":6.0},"kp":["碳酸锂年产能[Vulcan Ludwigshafen第二个锂项目]: 21,100吨/年","项目状态[上莱茵河谷第二锂与地热项目]: 预可行性研究完成，投资决策前仍需多个开发步骤","配套建设[Vulcan法兰克福-Höchst]: 正在建锂加工厂"]},{"i":60068,"as":"中国正在逐步取消电动汽车和电池的税收优惠。自9月1日起，锂离子电池须缴纳2%的消费税，2027年9月将升至4%，终结了自2015年以来的免税政策。相比之下，钠离子电池、固态电池以及燃料电池的消费税免税期将延长至2028年底。这表明中国正将税收优惠从已成熟的锂离子电池部分转向更新的电池技术，逐步淘汰相关激励措施。","scd":{"b":1.0,"i":5.0,"r":5.0,"d":5.0,"t":7.0},"kp":["锂离子电池消费税税率[中国自9月1日起]: 2%","未来税率[2027年9月起]: 升至4%"]},{"i":60069,"as":"英国公司Geothermal Engineering（GEL）宣布在本土陆上锂生产方面取得技术突破。9月2日GEL表示，独立分析显示其从深层地热卤水中生产的碳酸锂纯度超过99.3%的规格，可归类为'技术级'材料。该成果位于康沃尔郡United Downs场地，碳酸锂无需进一步精炼即可直接出售给电池制造商，提供了直接的市场路径。该场地于2026年2月开始生产，目前年产能100吨碳酸锂，预计到2029年产量达到约2000吨/年。","scd":{"b":7.0,"i":5.0,"r":8.0,"d":7.0,"t":8.0},"kp":["碳酸锂纯度[英国GEL深部地热卤水提取，康沃尔United Downs项目]: 超过99.3%，达到技术级标准"]},{"i":60070,"as":"路虎推出全电动SUV Range Rover Electric，结合豪华与先进技术。其电驱动系统输出542马力和627磅-英尺扭矩，0-60英里加速仅需4.3秒。牵引力控制系统响应速度比燃油车型快100倍，可在50毫秒内响应，在陡坡等越野环境下表现出色。该车搭载118.5千瓦时电池，充电10%至80%仅需22分钟，EPA续航里程333英里。捷豹路虎将其定位为最安静、最平顺的顶级豪华车型之一。","scd":{"b":4.0,"i":8.0,"r":4.0,"d":7.0,"t":7.0},"kp":["系统功率[揽胜纯电SUV电驱动系统]: 542马力","扭矩[揽胜纯电SUV]: 627磅-英尺","0-60英里/小时加速时间[揽胜纯电SUV]: 4.3秒","牵引力控制响应时间[揽胜纯电SUV]: 50毫秒，比燃油车型快100倍"]},{"i":60071,"as":"Supply Chain LIVE: The London Summit峰会将于9月8-9日在伦敦威斯敏斯特QEII中心举行，由BizClik和Supply Chain Digital主办，为期两天，将汇聚1000多位高级决策者及供应链等行业人士。峰会期间将举办一系列创新专题会议，探讨近年来在持续创新和新兴战略驱动下供应链的重大变革。当前市场仍不稳定，波动性威胁供应链韧性，峰会旨在帮助行业应对这些挑战。","scd":null,"kp":[]},{"i":60072,"as":"Supply Chain LIVE: The London Summit峰会将于2026年9月8-9日在伦敦威斯敏斯特QEII中心再次举办，为供应链领导者提供聚集平台。当前全球供应链正面临重大挑战，新技术不断涌现，董事会层面也不断推出增强韧性的新战略，合作与共享洞察被视为成功的关键。峰会旨在帮助领导者应对市场动荡，以创新战略驱动供应链韧性。","scd":null,"kp":[]},{"i":60073,"as":"Kaleris宣布收购Newport Systems，后者是维护修理（M&R）及场站管理软件的领先供应商。Kaleris首席执行官Kirk Knauff表示，此次收购将加速其实现维护修理供应链自动化的愿景。收购将打造业内唯一的端到端M&R平台，将海运码头、内陆场站、铁路站场、设备所有者和维修服务商的完整资产生命周期连接到单一平台上。","scd":null,"kp":["收购标的[Kaleris收购Newport Systems]: 维修保养(M&R)和场站管理软件领先供应商","战略目的[收购Newport]: 加速维修保养供应链自动化"]},{"i":60074,"as":"RXO与Enterprise Purchasing Group（epg）达成战略合作伙伴关系，成为epg官方整车（FTL）和零担（LTL）运输服务商，涉及物流采购和供应链优化领域。通过合作，epg成员可接入RXO覆盖北美的超过12.5万家承运商和170万辆卡车的运输网络。RXO货运经纪业务总裁Louis Amo表示，将RXO庞大的运力和先进技术与epg作为全球领先物流采购平台的地位相结合，帮助企业提升效率。","scd":null,"kp":["合作内容[RXO与epg战略合作]: RXO成为epg官方整车(FTL)和零担(LTL)运输服务商，覆盖物流采购与供应链优化"]},{"i":60075,"as":"Macfox X1S是一款踏板车风格的电动自行车，更接近迷你摩托车体验，踏板几乎只是合法上路的合规性设计。评测认为它不适合真正喜欢踩踏骑行的用户，但作为一款带摩托车风格设计、宽胎和右手油门的有趣城市代步工具很合适。该车可合法上路，合规时速20英里（32公里/小时），售价1399美元，搭载500W后置电机。","scd":null,"kp":["产品定位[Macfox X1S]: 接近迷你摩托车风格的踏板电动自行车，仍合法上路"]},{"i":60076,"as":"捷豹路虎（JLR）正准备推出Defender品牌首款纯电动SUV，这是一款紧凑型越野车，预计将于年底前正式亮相，可能命名为Defender Sport EV，预计2027年上市。在Range Rover Electric本周上市后（英国起售价154,070英镑、美国约14万美元），Defender电动车的定位将低于标准入门级Defender SUV。JLR多年来一直讨论推出'迷你Defender'车型。","scd":{"b":3.0,"i":4.0,"r":3.0,"d":3.0,"t":6.0},"kp":["[Defender品牌首款纯电SUV]: 预计2027年上市，或定名Defender Sport EV，年底前亮相"]},{"i":60077,"as":"特斯拉正在推出新版全自动驾驶（监督版）软件FSD Supervised v14.3.9，其AI团队在周五早间的发文中宣布了该功能。该版本包含新的主动安全功能集：当检测到即将发生碰撞且自动紧急制动（AEB）可能不足以避免事故时，即使驾驶员正在手动驾驶并未使用FSD，系统也可以代表驾驶员主动接管车辆以避免碰撞。该版本即将开始推送。","scd":{"b":6.0,"i":8.0,"r":6.0,"d":5.0,"t":9.0},"kp":["[Tesla FSD Supervised v14.3.9]: 新增主动安全功能，可在人工手动驾驶时接管车辆以避免碰撞"]},{"i":60078,"as":"美国整个汽车行业再次游说国会扼杀竞争，使美国人继续被高价格、二流、高污染的车辆所困。汽车行业向电动化转型已是大势所趋，持续超过十年。中国通过确保原材料合作伙伴关系、供应协议、生产能力和蓬勃的电动车创业文化，为这一时刻做好了准备，且与美国通常的说法相反，这种准备多为自下而上而非自上而下。结果是车企制造出了一些最好、最实惠的汽车。","scd":{"b":1.0,"i":2.0,"r":3.0,"d":2.0,"t":5.0},"kp":["[美国汽车行业电动化转型]: 行业游说国会抑制竞争；中国已通过锁定资源为电动化做好准备"]},{"i":60079,"as":"特斯拉Cybercab在商业推出当天即遭NHTSA联邦调查。该机构就在特斯拉于奥斯汀开始搭载乘客的同一天，对其车辆认证方式展开审计。调查针对的正是Cybercab的独特之处：它没有方向盘、没有踏板、没有后视镜，但特斯拉仍将其认证为合法上路车辆。特斯拉昨日（无直播、无发布会、马斯克未公开发言）在奥斯汀邀请小批股东和友好网红试乘，据称乘客被要求签署保密协议，随后向公众开放乘坐。","scd":{"b":7.0,"i":8.0,"r":8.0,"d":5.0,"t":9.0},"kp":["[Tesla Cybercab]: 无方向盘、无踏板、无后视镜，在奥斯汀商业运营首日即遭NHTSA审计认证合规性"]},{"i":60080,"as":"韩国农林食品农村部（MAFRA）公布的2027年预算提案显示，计划将工厂屋顶太阳能和农业光伏的政府资金增加一倍至1.8万亿韩元（约13亿美元）。同月12月，规范农田双重用途太阳能的新法律将生效。MAFRA副部长Kim Jong-gu在9月1日内阁会议后介绍了总额22.2215万亿韩元的2027年预算提案，较2026年增加2.0853万亿韩元，增幅10.4%。","scd":{"b":2.0,"i":4.0,"r":5.0,"d":6.0,"t":7.0},"kp":["韩国农场光伏和农业光伏预算[2027年]: 1.8万亿韩元（约13亿美元），较之前翻倍","[农地双用途光伏新法规]: 12月生效"]},{"i":60081,"as":"尽管农业光伏的发电潜力远超瑞士当前的用电量，但其在瑞士装机容量中几乎为零。苏黎世应用科学大学（ZHAW）的最新技术报告指出，地面光伏系统目前仅占装机容量的0.1%，而农业光伏系统占比为0.0%（四舍五入）。报告认定法律和行政障碍是关键壁垒，呼吁进行监管改革、提供更大的投资确定性，并借鉴邻国市场经验。同时瑞士《能源法》对此有相关规定要求。","scd":{"b":3.0,"i":3.0,"r":6.0,"d":5.0,"t":5.0},"kp":["[瑞士农业光伏现状]: 装机占比几乎为零，地面电站仅占装机容量0.1%，主要障碍为法律和行政壁垒"]},{"i":60082,"as":"氢能领域多项进展：韩国浦项制铁（Posco）与澳大利亚必和必拓（BHP）签署合作协议，推进浦项氢还原炼铁技术HyREX，此前双方于2025年10月签署谅解备忘录；西班牙瓦伦西亚政府批准7600万欧元用于英国石油公司（BP）主导的可再生氢和可持续生物燃料项目；NaTran和Creos Deutschland开始建设跨国mosaHYc氢能网络德国段；Uniper完成威廉港氢进口终端意向征集，该终端最终每年可处理260万吨氨。","scd":{"b":5.0,"i":6.0,"r":6.0,"d":7.0,"t":7.0},"kp":["Uniper威廉港氢进口终端氨处理能力[规划]: 260万吨/年","巴伦西亚政府氢能与生物燃料项目拨款: 7600万欧元","mosaHYc跨境氢管网德国段: NaTran与Creos Deutschland开工"]},{"i":60083,"as":"德国TÜV Rheinland的第三方测试证实，Aptera Motors的太阳能电动汽车在南加州连续三天的测试中，每日产生超过4千瓦时的可用太阳能电力，并转换为车辆高压电池存储。该数据展示了车辆集成光伏（VIPV）在实际野外条件下的表现。车辆太阳能历来因面板倾角低、遮阳和表面面积有限而受到质疑，但测试结果显示了电池布局和电力电子设备在实际使用中的性能。","scd":{"b":5.0,"i":5.0,"r":7.0,"d":6.0,"t":7.0},"kp":["Aptera太阳能电动汽车日发电量[TÜV Rheinland南加州三日实测]: 超过4 kWh可用太阳能电力（转换后输送至高压电池）"]},{"i":60084,"as":"国际电工委员会（IEC）正计划制定相关标准，以推动循环经济模式下延长风力涡轮机和太阳能光伏组件的生命周期。风电机组和屋顶光伏已成为常见景象，太阳能和风能对各国实现净零排放目标至关重要。但可再生能源存在环境悖论：当发电设备达到使用寿命终点时，会成为废弃物。循环经济模式旨在解决这一问题，延长设备寿命并妥善处理退役设备。","scd":{"b":3.0,"i":3.0,"r":5.0,"d":4.0,"t":4.0},"kp":["[IEC风机与光伏组件循环经济]: 正在规划生命周期延展相关标准"]},{"i":60085,"as":"南部非洲可再生能源市场正进入新阶段，随着该地区电力市场自由化，企业越来越多地将太阳能、储能和灵活性打包成针对特定客户和系统需求设计的产品，而非单纯出售可变化电力。Cresco Project Finance能源战略咨询合伙人兼Naviara Energy创始人Dominic Goncalves表示，南部非洲可再生能源领域的下一轮竞赛将围绕此类定制化产品展开。这是南部非洲能源市场系列报道的最后一篇。","scd":{"b":2.0,"i":4.0,"r":5.0,"d":4.0,"t":5.0},"kp":["[南部非洲可再生能源市场]: 电力市场自由化推动从单纯售电转向按客户和系统需求定制的产品"]},{"i":60086,"as":"意大利充电设备制造商Alpitronic推出HYC1000分布式直流快充系统，总输出功率最高达1MW。系统由中央电源柜连接多个独立充电桩组成，可同时为最多八辆电动车充电，功率在各充电点间动态分配。在柏林的演示中，该系统向新款奔驰AMG GT四门轿跑输出超过600kW的充电功率。","scd":{"b":5.0,"i":6.0,"r":5.0,"d":6.0,"t":7.0},"kp":["充电功率[HYC1000分布式直流充电系统]: 1 MW","同时服务车辆数[HYC1000]: 最多8辆","实际演示功率[柏林演示,奔驰AMG GT]: 超过600 kW"]},{"i":60087,"as":"Women in Solar+ Europe本周聚焦Kataclima法务负责人、Italia Rinnovable联合创始人Angelica Almi。她原本从未想过从事可再生能源行业，后来意识到能源是生活、生产和社区建设不可或缺的部分，真正的挑战不是是否需要能源，而是如何生产、分享能源并管理其影响。她建议以好奇心、尊重和真诚对待每段职业关系，把挑战转化为优势，勇敢热情地拥抱意外机遇，不要等到感觉完全准备好。","scd":{"b":1.0,"i":2.0,"r":2.0,"d":1.0,"t":4.0},"kp":[]},{"i":60088,"as":"YouTube频道Plasma Channel主理人Jay Bowles将一台5万伏实验装置运至1.4万公里外的纳米比亚海岸，与斯瓦科普蒙德的纳米比亚大学研究人员合作实地测试静电集水技术。该装置利用高压线电离雾中悬浮的微水滴，带电水滴被吸附至接地金属网并凝结收集。车库测试效果良好，但在纳米比亚实地试验中受盐分、强风和多变的天气影响表现不佳。","scd":{"b":4.0,"i":3.0,"r":6.0,"d":5.0,"t":6.0},"kp":["电压[纳米比亚沙漠雾取水静电装置]: 50,000伏","运输距离[车库测试至纳米比亚实测]: 14,000公里","技术原理[雾水提取]: 静电沉淀"]},{"i":60089,"as":"美国能源部下属国家核安全管理局（NNSA）选定BWX Technologies为田纳西州Y-12国家安全综合体起草工程设计方案，用模块化生产单元替换运行数十年的老旧锂制造基础设施。美国核武器储备依赖精密加工的锂部件，但现有处理系统已远超设计寿命，技术团队需不间断地提取、提纯、加工和回收该材料以维持储备功能。该项目是对国家核安全基础设施现代化的重要投资。","scd":{"b":4.0,"i":5.0,"r":6.0,"d":5.0,"t":6.0},"kp":["生产单元设计[Y-12核安保综合体锂部件制造]: 模块化","技术承研方[NNSA选定]: BWX Technologies","锂部件用途[美国核武储备]: 精密机加工件"]},{"i":60090,"as":"在核反应堆或辐射屏蔽建模中，中子和光子穿越锯齿边缘、致密金属、流体和空隙，传统计算机追踪每次材料变化的计算量极为庞大。Quantum X Labs旗下核量子部门开发出新算法，可将复杂物理形状直接转化为量子数据：不将物体切分为数十亿数字小方块，而是通过数学方法将边界和材料密度嵌入量子态，从而在量子计算机上高效求解核系统模拟问题。","scd":{"b":7.0,"i":4.0,"r":7.0,"d":6.0,"t":7.0},"kp":["求解对象[量子输运新方法]: 核反应堆中子与光子在非均匀材料中的输运模拟","开发者[新量子输运方法]: Quantum X Labs"]},{"i":60091,"as":"韩国标准科学研究院（KRISS）和光州科学技术院（GIST）的研究人员解开了拓扑绝缘体（TI）纳米线中\"拍频\"信号来源的多年谜团。这一发现有助于更准确解读拓扑量子器件的信号，并实现器件所需的电子态。拓扑量子器件是量子计算和量子传感等新兴技术的核心，量子计算机可数秒内超越最快超算，先进传感器可在纳米尺度测量电场或磁场变化。","scd":{"b":7.5,"i":3.0,"r":7.0,"d":6.0,"t":7.0},"kp":["研究对象[拍频信号起源]: 拓扑绝缘体纳米线"]},{"i":60092,"as":"总部位于得克萨斯州的Mazama Energy宣布其位于俄勒冈州Newberry的Athena地热井在15天内钻探至10,350英尺深度，相比去年同场地的里程碑式钻井，钻探时间缩短约80%。这是超热岩地热能商业化的关键一步。超热岩指温度超过750°F（399°C）的地下岩层，蕴藏的能量足以改变绿色电网经济格局，但深钻通常会导致设备损坏。","scd":{"b":6.5,"i":6.0,"r":7.0,"d":8.0,"t":8.0},"kp":["钻探深度[Athena地热井,新火山口俄勒冈]: 10,350英尺","钻探用时[Athena井]: 15天","钻探时间降幅[与传统对比]: 约80%","技术方向[Mazama Energy]: 超热岩地热能商业化"]},{"i":60093,"as":"奥地利电池诊断公司AVILOO对20款热门电动车型的电池健康状况（SoH）进行分析，数据基于2022至2026年间收集的超过50万次独立电池测试，来自其在南北美洲、欧洲、澳大利亚和亚洲超100万次测试的全球数据库。结果显示不同电池老化差异显著，奔驰EQA在15万公里后表现领先，顶级电动车行驶约9.3万英里后电池健康度仍保持在90%以上。","scd":{"b":3.0,"i":7.0,"r":8.0,"d":9.0,"t":7.0},"kp":["电池健康度[顶级电动汽车行驶93,000英里后]: 90%以上","测试样本量[AVILOO独立测试数据库]: 超过100万次,其中分析50万次以上","覆盖车型[研究范围]: 20款流行电动车,数据采集于2022-2026年"]},{"i":60094,"as":"中国机器人企业AGIBOT开源其WORLD 2026数据集，包含在14个工业场景收集的11,430条真实机器人轨迹，旨在推进强化学习和具身智能研究。该数据集帮助机器人从真实世界交互中学习，而非仅依赖成功的专家示范，记录了包括机器人通过失败和人工干预改进的完整学习过程。AGIBOT近期在第二届世界人形机器人运动会上以46枚奖牌（含18金）首次参加国际比赛即登顶。","scd":{"b":6.0,"i":6.0,"r":8.0,"d":7.0,"t":8.0},"kp":["轨迹数量[AGIBOT WORLD 2026开源数据集]: 11,430条","技术方向[WORLD 2026数据集]: 面向具身智能强化学习,包含失败与人类干预过程","赛事成绩[第二届世界人形机器人运动会]: 46枚奖牌,其中18金"]},{"i":60095,"as":"德国Mehler Protection公司将在SMM 2026上发布名为SCILT NAVAL的新型舰载反无人机系统，采用霰弹枪式拦截方式，专门打击FPV无人机、巡飞弹及其他贴近舰船飞行的无人飞行器。该系统定位于常规防空失效后的最后防线，适用于舰员反应时间极短的场景，尤其在港口附近、海洋基础设施周围和狭窄水域。廉价无人机的广泛使用已对海军防御构成重大挑战，多架无人机低空近距离同时逼近可威胁装备精良的舰艇。","scd":{"b":4.0,"i":4.0,"r":6.0,"d":5.0,"t":7.0},"kp":["系统名称[德国Mehler Protection舰载反无人机系统]: SCILT NAVAL","打击目标[近距离防御]: FPV无人机、巡飞弹及其他近舰无人飞行器","技术原理[反无人机]: 霰弹枪拦截"]},{"i":60096,"as":"高超音速飞机制造商Hermeus选定Anduril为其Quarterhorse Mk 2高马赫数飞机项目集成任务自主技术。根据协议，Anduril将把Lattice for Mission Autonomy软件集成到Quarterhorse Mk 2中，使多架飞机能在任务中协同行动，同时为人类操作员提供统一界面在全任务过程中与飞机交互。该合作将高速飞行与任务自主两大快速发展的军用航空领域相结合。","scd":{"b":5.5,"i":6.0,"r":5.0,"d":5.0,"t":7.0},"kp":["任务自主软件[Hermeus Quarterhorse Mk 2]: Anduril Lattice for Mission Autonomy，实现多机协同与人机统一接口","飞行器[高马赫项目]: Quarterhorse Mk 2自主协同飞行能力"]},{"i":60097,"as":"由威斯康星大学麦迪逊分校、落基山国家实验室及合作机构联合领导的团队通过分子重新设计，为锡基钙钛矿太阳能电池构建了抵御空气和湿气的内在防护层，如同分子\"雨衣\"，使电池效率达到16.2%。锡钙钛矿有望成为含铅有毒电池的环保替代方案，但以往材料暴露于空气和水中会迅速降解，新设计解决了这一长期瓶颈。","scd":{"b":8.0,"i":4.0,"r":7.0,"d":7.0,"t":7.0},"kp":["转换效率[锡基钙钛矿太阳能电池]: 16.2%","材料特性[锡钙钛矿]: 内置空气与湿气防护（分子雨衣），环保无铅替代"]},{"i":60098,"as":"美国核动力航空母舰\"亚伯拉罕·林肯\"号（USS Abraham Lincoln）在海上部署286天后抵达泰国林查班港，约5000名美国海军士兵和陆战队员将进行为期四天的休整。这是该舰自2025年11月离开圣地亚哥以来的首次完整靠港。该舰连续264天未进行完整港口访问，7月初已打破\"艾森豪威尔\"号在疫情期间创下的连续206天海上纪录（航母通常每30至45天进港一次）。超长部署引发了对船员健康、补给和舰况的担忧。","scd":{"b":1.0,"i":3.0,"r":4.0,"d":5.0,"t":7.0},"kp":["部署时长[核动力航母亚伯拉罕·林肯号]: 创纪录286天","舰船规格[航母]: 舰长1092英尺，载员约5000人"]},{"i":60099,"as":"L3Harris Technologies已完成首批35套Viper Shield电子战系统的生产，面向全球F-16机队。Viper Shield是全数字电子战与对抗系统，被L3Harris称为F-16的\"数字装甲\"，可安装于机内或作为外挂吊舱使用，适配不同F-16构型。该公司目前收到来自八个盟国的233套订单，正准备向全速生产过渡，并已用生产级硬件组装出首套生产型吊舱。","scd":{"b":4.0,"i":8.0,"r":5.0,"d":6.0,"t":7.0},"kp":["交付数量[L3Harris Viper Shield电子战系统首批]: 35套","系统特性[Viper Shield]: 全数字电子战与对抗系统，可机内安装或外挂吊舱，适配F-16各型"]},{"i":60100,"as":"美国陆军在加利福尼亚州欧文堡国家训练中心举行的\"融合项目顶点6\"（PCC6）年度演习中，在实战条件下测试了QuSecure的量子抗性网络安全平台QuProtect R3，达到TRL-7技术成熟度。该系统由士兵在演习中操作，为战术通信提供安全防护、密码敏捷性以及战术任务系统中密码资产的清单管理。PCC6汇集数千名士兵、军事系统和新兴技术，测试美国陆军、联合部队及多国伙伴的未来作战概念。","scd":{"b":6.5,"i":6.5,"r":7.0,"d":6.0,"t":7.0},"kp":["技术成熟度[QuSecure QuProtect R3防量子平台]: TRL-7","验证条件[美国陆军PCC6演习]: 实战战场条件下保护战术通信，具备密码敏捷性和密码资产清单"]},{"i":60101,"as":"","scd":null,"kp":[]},{"i":60102,"as":"美国机器人公司Figure与英国Nscale签署战略合作协议，以获取大规模算力用于训练下一代人形机器人AI模型。根据协议，Nscale将部署基于NVIDIA Vera Rubin平台的最多10万个GPU，支持Figure的AI开发。该合作旨在解决通用机器人模型训练对数据和算力日益增长的需求，为Figure扩展其\"物理智能\"研究、提升人形机器人能力提供所需计算基础设施。","scd":{"b":4.5,"i":6.0,"r":7.0,"d":6.0,"t":8.0},"kp":["算力规模[Figure人形机器人AI训练]: 最高100,000个GPU","GPU平台[Nscale部署]: 基于NVIDIA Vera Rubin平台"]},{"i":60103,"as":"拥有30多年经验的通用原子航空系统公司（GA-ASI）正在开发新一代无人机，以满足国防力量对更好情报、更灵活任务和更安全人员条件的需求。其Mojave短距起降（STOL）无人机系统专为远离标准空军基地的发射场景设计，可从航母、土质跑道及其他非传统场地起飞，在常规飞机无法运行的恶劣环境中执行关键监视与作战任务，且可快速规模化部署。","scd":{"b":3.5,"i":3.0,"r":3.0,"d":3.0,"t":4.0},"kp":["研发经验[GA-ASI无人飞机]: 超过30年","平台特性[下一代无人战机]: 可快速扩展规模并在恶劣环境下执行监视与作战任务"]},{"i":60104,"as":"特斯拉已在得克萨斯州奥斯汀公共道路上部署数十辆专门制造的Cybercab网络出租车。这些金色车辆没有方向盘和刹车踏板，乘客在出现问题时无法接管控制。特斯拉此举旨在测试技术本身以及乘客是否愿意信任一款无手动驾驶选项的车辆。特斯拉自2025年6月起在奥斯汀运营自动驾驶出租车服务，但此前车辆仍配备常规控制装置并配有可随时干预的安全员。","scd":{"b":6.5,"i":7.0,"r":7.0,"d":5.0,"t":9.0},"kp":["车辆设计[Tesla Cybercab]: 无方向盘和制动踏板的全自动驾驶网约车","部署规模[奥斯汀公共道路]: 数十辆专用Cybercab"]},{"i":60105,"as":"俄克拉荷马州公司Ten-Nine Technologies正扩大其专利正极添加剂TENIX的生产规模。电池充放电过程中会积累不良化学副产物，TENIX从源头阻止这一老化过程。该添加剂在制造时直接混入正极材料，仅占重量的0.5-2%（每100公斤正极约0.5-2公斤），可直接接入现有正极产线，无需新设备或重新设计电池。实验显示其可将电池热量输出减少约40%；目前100吨产能可满足5万至20万个典型电动车电池包的处理需求。","scd":{"b":6.0,"i":6.5,"r":7.0,"d":7.0,"t":6.0},"kp":["热输出减少[电池老化过程]: 约40%","添加比例[TENIX正极添加剂]: 占正极材料重量的0.5–2%（每100kg正极约0.5–2kg）"]},{"i":60106,"as":"美国无人机初创公司Elroy Air在eVTOL集成试点计划(eIPP)授权下，完成了首次自主无人驾驶飞行测试。测试在路易斯安那州进行，使用Chaparral混合电动垂直起降飞机，为期一周，聚焦运输不同类型货物，包括医疗用品、食品和工业设备。Chaparral有效载荷500磅，航程450英里，可自主飞行。FAA局长Bryan Bedford表示，这些测试展示了新型飞机如何扩展全国社区货运选择并改善物流基础设施。","scd":{"b":5.0,"i":6.5,"r":6.0,"d":7.0,"t":8.0},"kp":["有效载荷[Elroy Air Chaparral货运无人机]: 500磅","航程[Chaparral混动eVTOL]: 450英里","试飞特点[eIPP项目]: 首次获授权的完全自主无人货运飞行，验证医疗物资、食品及工业设备运输"]},{"i":60107,"as":"NANO Nuclear Energy开发的KRONOS MMR高温气冷微反应堆的关键冷却部件——氦循环器已进入详细设计阶段，这是迈向建造原型机的又一工程步骤。该循环器将驱动氦气通过堆芯带走燃料热量，维持反应堆热性能，其设计将影响反应堆传热效率和系统长期运行可靠性。NANO Nuclear与拥有氦气涡轮机械和高温气冷堆系统经验的Baker Hughes旗下Howden合作开发，Howden主导工程工作。","scd":{"b":4.0,"i":4.5,"r":6.0,"d":5.0,"t":5.0},"kp":["氦循环风机[KRONOS MMR微反应器]: 进入详细设计阶段，用于堆芯冷却与热输送","反应堆类型[KRONOS MMR能源系统]: 高温气冷堆"]},{"i":60108,"as":"2021至2023年间，南极冰盖增加约6950亿吨质量，是GRACE卫星记录到的最大增量。新研究将这一罕见增量归因于数千英里外热带西太平洋和东印度洋的持续变暖，其改变了大气环流并向东南极输送更多水汽，引发创纪录降雪。热带变暖事件促成了这一临时性冰量增加，但并未逆转南极冰的长期损失趋势，过去二十年南极整体仍持续消融。","scd":{"b":7.0,"i":2.0,"r":8.0,"d":8.0,"t":6.0},"kp":["南极冰盖质量增量[2021-2023年东南极]: 约6950亿吨，GRACE卫星观测记录最大增幅"]},{"i":60109,"as":"SpaceX Dragon飞船推进系统中的氧化剂泄漏导致NASA Crew-13国际空间站任务发射推迟。泄漏是在例行发射前处理过程中被检测到的，工程师正在努力使飞船获得飞行许可。氧化剂是推进系统用于帮助燃料燃烧产生推力的化学物质，是飞船机动和控制的关键组成部分。在飞船获批飞行前，任务将保持推迟状态。","scd":{"b":2.0,"i":4.0,"r":5.0,"d":4.0,"t":8.0},"kp":["故障部位[SpaceX Dragon飞船]: 推进系统氧化剂泄漏，导致Crew-13任务发射推迟"]},{"i":60110,"as":"","scd":null,"kp":[]},{"i":60111,"as":"曾于2023年因单块砖即可无重复铺满整个平面而引起全球关注的史密斯帽子拼块几何结构，在纳米尺度重现后产生了新惊喜。东京大学生产技术研究所及合作机构研究人员用激光照射基于史密斯帽子构建的纳米光学结构时，产生了不同于常规准晶体的光学行为，形成反映其缺乏镜像对称性的特殊光图案，且随光照方向和偏振变化而改变。这一纯数学拼块突破在纳米尺度揭示了意想不到的光学效应。","scd":{"b":8.0,"i":3.0,"r":8.0,"d":6.0,"t":6.0},"kp":["光学效应[Smith hat纳米结构]: 产生随光方向和偏振变化的非常规光图案，源于无镜像对称性","几何特性[Smith hat单瓦片]: 可非周期性铺满整个平面"]},{"i":60112,"as":"UCLA领导的研究团队以原子级三维成像方式逐原子捕捉晶体成核过程，发现成核核的结构与经典成核理论的预测不符。经典成核理论近一个世纪以来一直用于解释冻结、凝结等相变的启动机制，描述有序小区域(核)在无序物质中如何出现，其核心方程曾获数千次实验支持。然而三维原子级观测显示，实际核的形态与经典模型描绘的图景存在差异，为液体冻结成固体等相变研究提供了新见解。","scd":{"b":9.0,"i":3.0,"r":8.0,"d":6.0,"t":6.0},"kp":["观测方法[晶体成核研究]: 三维原子级成像，揭示与经典成核理论不符的核结构"]},{"i":60113,"as":"","scd":null,"kp":[]},{"i":60114,"as":"2024年5月超级地磁暴期间，尽管太阳风异常稠密，来自太阳风的离子对环电流的贡献却极小，这是首次在此量级风暴中同时观测到这两个现象。风暴由大黑子释放的快速连续强太阳爆发引发，多个磁化等离子体云在飞向地球途中合并。极光延伸至全球异常低纬度地区。Arase卫星在地球磁层内对环电流离子进行了观测，揭示了这场超级风暴的意外驱动因素。","scd":{"b":7.5,"i":2.0,"r":8.0,"d":7.0,"t":5.0},"kp":["环电流离子来源[2024年5月超级地磁暴]: 太阳风密度异常高但对环电流贡献极小，首次同时观测"]},{"i":60115,"as":"研究人员开发出分析双黑洞并合后'铃声'的新方法。当两个黑洞碰撞合并时释放引力波，可被地球上的灵敏仪器探测到，从而确定黑洞的质量和自旋。新形成的更大黑洞在稳定过程中会继续'振铃'，发出时空涟漪——引力波，而非声音。新方法能更细致地绘制并合黑洞产生的微弱引力波振动，有望实现更精确的广义相对论检验。","scd":{"b":8.0,"i":2.0,"r":7.0,"d":6.0,"t":6.0},"kp":["新方法[黑洞并合引力波]: 映射黑洞并合铃宕振动，可更精确检验广义相对论"]},{"i":60116,"as":"国际团队使用詹姆斯韦伯太空望远镜(JWST)获得观测证据，使天文学家更接近解决超大质量黑洞如何持续进食的长期谜题。数十年来天文学家困惑于大质量星系中心的一个难题：超大质量黑洞自身的强大喷流加热周围为其供气的气体，它如何保持进食?JWST新图像提供了迄今最清晰的观测——显示连接星系热大气与黑洞的气体丝状结构，为这一过程提供了照片级证据。","scd":{"b":8.0,"i":2.0,"r":6.0,"d":4.0,"t":7.0},"kp":["观测发现[JWST超大质量黑洞]: 获得黑洞如何持续吸积（进食）的影像证据"]},{"i":60117,"as":"宁夏统计局数据显示，1-7月全区规模以上工业增加值同比增长7.5%。其中采矿业增长13.4%，制造业增长10.0%；轻工业增长13.6%，重工业增长6.8%。分行业看，黑色金属冶炼和压延加工业大增47.6%，电气机械和器材制造业增长21.0%，煤炭开采和洗选业增长16.2%。分产品看，多晶硅产量增长4.6倍，单晶硅增长13.0%，化学纤维增长41.6%，金属切削机床增长17.7%，硫酸增长64.3%，显示出光伏材料和重工业产品强劲增长态势。","scd":{"b":1.5,"i":3.0,"r":5.0,"d":8.0,"t":5.0},"kp":["单晶硅产量[宁夏2026年1-7月]: 同比增长13%","多晶硅产量[宁夏2026年1-7月]: 同比增长4.6倍","工业增加值[宁夏规模以上工业2026年1-7月]: 同比增长7.5%","电气机械和器材制造业[宁夏2026年1-7月]: 增加值同比增长21.0%","黑色金属冶炼和压延加工业[宁夏2026年1-7月]: 增加值同比增长47.6%"]},{"i":60118,"as":"福建莆田仙游县连日遭遇短时强降雨，龙华镇一村庄突发山洪，湍急洪水冲垮一栋三层民房，楼顶架设的屋顶光伏电站随房屋主体一同倾覆坠落。9月3日流出的现场视频显示，暴雨持续落下，浑浊泛黄的山洪裹挟泥沙汹涌奔涌，持续冲刷下楼房地基被不断淘空，整栋建筑轰然垮塌。所幸经村民与镇政府多方核实，本次灾害未造成人员伤亡。","scd":{"b":0.5,"i":1.0,"r":4.0,"d":2.0,"t":8.0},"kp":[]},{"i":60119,"as":"山东省四部门于2026年8月27日联合印发全国首份系统规范新能源场站配建储能全流程的省级文件(鲁发改能源〔2026〕632号)。核心制度包括：配储设上限不设下限，光伏场站新增配储总功率不超过装机功率50%、风电不超过30%；2025年5月31日前投产的存量项目须履行配储承诺，2027年起未履约场站在弃电时段被优先压降；储能接入空间按光伏权重4、风电权重1分配；配建储能充电来自配套新能源的放电量视同新能源发电量，禁止从公网购电充电；源储统一调度、计量、结算并可参与现货市场；锂电池须1年内建成并网，钠离子、液流电池放宽至18个月。背景是山东风光装机突破1.3亿千瓦，2025年现货市场负电价时段超1300小时。","scd":{"b":2.0,"i":3.0,"r":8.0,"d":8.0,"t":8.0},"kp":["配储功率上限[光伏场站新增配储]: 不超过装机功率的50%","配储功率上限[风电场站]: 不超过装机功率的30%","存量项目截止时间[须履行并网配储承诺]: 2025年5月31日前投产项目","优先压降机制[未履约场站]: 2027年起在弃电时段被优先压降","储能接入空间分配权重[市域间共用]: 光伏权重4、风电权重1"]},{"i":60120,"as":"Proserv与Equinor正式签署合同，将在位于诺福克海岸附近、装机容量402 MW的Dudgeon海上风电场部署其ECG电缆监测技术。该风电场于2017年建成，由67台风机组成，可为43万户英国家庭供电。合同内容包括对风电场电气基础设施的电缆和终端健康状况进行持续监测，Proserv还将部署其分布式电传感(DES)技术。","scd":{"b":3.5,"i":6.0,"r":4.0,"d":5.0,"t":6.0},"kp":["装机容量[Dudgeon海上风电场]: 402 MW","风机数量[Dudgeon海上风电场]: 67台","供电能力[Dudgeon海上风电场]: 43万户英国家庭","电缆监控技术[Equinor合同]: Proserv ECG系统","投运时间[Dudgeon海上风电场]: 2017年"]},{"i":60121,"as":"韩国总理韩悳洙于9月2日在首尔主持海上风电委员会会议，审议批准了海上风电开发进展、规划场址引入方案及委员会详细运营规则两项主要议程。韩国计划指定25 GW海上风电预备场址，并到2040年实现45 GW海上风电装机容量。场址选定后，项目运营商将负责海上风电项目的设计、建设和运营，新制度旨在缩短开发时间线。","scd":{"b":1.5,"i":3.0,"r":3.0,"d":4.0,"t":6.0},"kp":[]},{"i":60122,"as":"ABS与JB Energy正式签署谅解备忘录，支持巴西浮式海上风电产业发展。双方将合作开展位于南里奥格兰德州Sul Wind浮式海上风电试点项目的战略研究。根据协议，ABS将支持项目多个领域，包括港口减排举措，以及为Raijin浮式平台制定初步退役战略。作为研究的一部分，两家公司还将研究拆除概念、拖航和运输方案。","scd":{"b":1.5,"i":3.0,"r":3.0,"d":4.0,"t":6.0},"kp":["合作内容[ABS与JB Energy谅解备忘录]: 支持18 Sul Wind浮动式海上风电试点项目战略研究","项目位置[18 Sul Wind项目]: 巴西南里奥格兰德州"]},{"i":60123,"as":"Windward Offshore正式接收Windward Hamburg号海上运维船(CSOV)，加入其不断扩大的海上船队。目前船队包括Windward Athens、Windward Paris和Windward Munich三艘船，旨在加强公司海上支持能力，为包括建造和调试活动在内的未来海上项目提供资源保障。该船基于VARD 4 19设计，可容纳120人，长87.5米、宽19.5米，配备直升机甲板，提升了运营灵活性和人员转移的安全性。","scd":{"b":2.0,"i":6.0,"r":3.0,"d":4.0,"t":6.0},"kp":["船型设计[Windward Hamburg CSOV]: VARD 4 19设计","载员能力[Windward Hamburg CSOV]: 最多120人"]},{"i":60124,"as":"Nexans在其正在建设中的沙勒罗瓦工厂展示了53米高的电缆绝缘塔。该塔将为主要欧洲输电项目生产525 kV高压直流陆缆，包括TenneT的BalWin 3、LanWin 2和LanWin 4项目，这些项目旨在将海上可再生能源发电接入陆上电网。绝缘塔占地4100平方米，位于总面积6000平方米的综合设施内，其高度和规模是为达到超高压电缆所需的绝缘质量而设计，确保可靠输电所需的绝缘一致性。","scd":{"b":4.0,"i":7.0,"r":4.0,"d":6.0,"t":6.0},"kp":["绝缘塔高度[Nexans沙勒罗瓦工厂]: 53米","电缆电压等级[沙勒罗瓦工厂生产]: 525 kV HVDC陆上电缆","占地面积[绝缘塔]: 4100 m²（厂区总面积6000 m²）"]},{"i":60125,"as":"乌克兰战场无人机数据正催生一个新的'狂野西部'式市场。战场上遍布无人机残骸，但其生成的数据成为国防领域的新金矿。乌克兰已开始将数万次无人机飞行收集的数百万数据点提供给军事承包商和商业公司。本期The Download还报道AI重塑语言，以及OpenAI发布其迄今最强大的模型Astra。","scd":{"b":5.0,"i":4.0,"r":5.0,"d":3.0,"t":8.0},"kp":[]},{"i":60126,"as":"乌克兰战场上的无人机残骸背后隐藏着国防领域的新金矿——数据。前线正成为AI模型的训练场，且目前基本处于无监管状态。每次飞行中，无人系统都会收集数千个数据点，包括图像、视频和控制器输入，记录机器和人员如何应对不断变化的状况。这些数据的价值将远超战争本身，日益成为塑造包括民用生活在内的AI架构的一部分，推动了一个如'狂野西部'般无序的新型数据市场。","scd":{"b":5.0,"i":4.0,"r":7.0,"d":5.0,"t":6.0},"kp":[]},{"i":60127,"as":"","scd":null,"kp":[]},{"i":60128,"as":"法国电力集团（EDF）子公司Luminus与基础设施基金I4B在比利时Lixhe正式投运一座150兆瓦/600兆瓦时电池储能系统Navagne，投资额1.6亿欧元。该设施直接接入输电系统运营商Elia的高压电网，成为该地区最大的在运电池资产。项目毗邻现有Lixhe水电站，利用既有发电枢纽和电网基础设施避开并网瓶颈。项目于2025年6月完成融资关闭，原计划2026年10月投运。Luminus子公司Newelec负责33千伏中压配电网建设并持续监管电气系统。","scd":{"b":3.0,"i":9.0,"r":7.0,"d":8.0,"t":8.0},"kp":["电池储能系统规模[Navagne BESS比利时Lixhe]: 150 MW / 600 MWh","投资额[Navagne BESS]: 1.6亿欧元","并网方式[Navagne BESS]: 直连Elia高压输电网","行业地位[Navagne BESS]: 该区域最大在运电池资产"]},{"i":60129,"as":"Furo与Luox Energy将联合提供工商业电池储能系统（BESS）的市场接入与优化综合解决方案，结合Furo的电池规划、优化与控制平台以及Luox的分时电价产品（包括'Dynamisch RLM'和'Direktvermarktung'两种电价方案）。目标是按每15分钟间隔优化电池运行。工商业储能可执行削峰、提高自发自用率、转移用电和馈电、提供可市场化灵活性等多种功能，最优运行策略取决于具体场地、负荷曲线、发电资产和电池配置。","scd":{"b":3.0,"i":6.0,"r":5.0,"d":6.0,"t":6.0},"kp":["优化时间粒度[工商业储能联合方案]: 每15分钟区间","联合方案[Furo与Luox Energy]: Furo电池规划优化控制平台+Luox动态RLM与直接营销电价产品"]},{"i":60130,"as":"西班牙可再生能源公司Norvento Enerxía（总部位于卢戈加利西亚）正拓展拉丁美洲增长中的储能市场，优先市场包括巴西、智利、阿根廷、墨西哥和危地马拉。公司计划向公用事业级储能项目供应其新型nXL功率转换技术，并依托其在微电网和工业自发自用领域的既有经验。该公司最初为工程公司，后扩展至风电和水电项目开发，2009年增设工业部门，专注制造自有技术，主要包括风力发电机和电力电子设备。","scd":{"b":2.0,"i":5.0,"r":4.0,"d":5.0,"t":5.0},"kp":["目标市场[Norvento拉丁美洲扩张]: 巴西、智利、阿根廷、墨西哥、危地马拉","技术供应[公用事业规模储能项目]: nXL功率转换技术"]},{"i":60131,"as":"瑞士卢塞恩的Horizonte Group AG正与子公司Horizonte-Group Technik（HGT，位于科隆）、与德国能源供应商EAM的合资企业Metelligent，以及科隆能源供应商Einklang NE Solutions合作，联合开发电池储能服务。目标客户为年用电量约250兆瓦时及以上的制造企业、物流运营商和零售商，帮助其在德国拟议的储能与充电点市场整合（MiSpeL）规则下优化电池储能。HGT负责安装、项目规划和计量方案注册，Metelligent负责安装注册电力计量表。","scd":{"b":2.0,"i":5.0,"r":4.0,"d":4.0,"t":5.0},"kp":["目标客户[联合电池储能服务]: 年用电量约一定规模的制造企业、物流运营商和零售商","合作方[电池储能服务]: Horizonte Group、HGT、Metelligent、Einklang Energy"]},{"i":60132,"as":"AES Andes已开始在智利安托法加斯塔大区Cristales项目测试其电池储能系统（BESS），功率340兆瓦，储能时长4小时，容量1360兆瓦时。测试阶段将验证设备、控制系统和安全装置的性能。公司还将很快启动同园区光伏电站的调试。公司最新信息显示Cristales光伏容量为287-288兆瓦，而智利能源部则将该项目的光伏测试容量列为400兆瓦。能源部7月发布的最新能源行业建设与投资项目报告已将Cristales BESS列入测试中的系统。","scd":{"b":3.0,"i":8.0,"r":6.0,"d":8.0,"t":7.0},"kp":["功率输出[AES Andes智利Cristales项目BESS]: 340 MW","储能容量[Cristales项目]: 1360 MWh","放电时长[Cristales项目BESS]: 4小时","测试内容[BESS调试阶段]: 验证设备性能、控制系统和安全装置"]},{"i":60133,"as":"中国一个研究小组针对川西高原传统民居提出了近零能耗改造策略，将屋顶光伏与空气源热泵相结合。研究人员指出，该地区海拔高、环境温度低、太阳辐射强，适合采用该方案；而当地传统民居普遍存在冬季供暖季能耗高、热舒适度不足的问题。这些建筑承载历史文化价值，是乡村建筑遗产的重要组成部分，多采用石木结构体系，墙体厚重但隔热性能不足，导致冬季室内热环境较差。","scd":{"b":5.0,"i":4.0,"r":6.0,"d":7.0,"t":5.0},"kp":["改造策略[川西高原传统民居近零能耗]: 屋顶光伏+空气源热泵结合","适用条件[近零能耗改造]: 高海拔、低环境温度、强太阳辐射地区"]},{"i":60134,"as":"法国专门从事光伏产品及系统认证的机构Certisolis更新了获得简化碳评估（ECS）认证的组件清单。该证书证明组件符合获得法国部分支持机制所需的碳足迹标准，尤其是S21上网电价和法国能源监管委员会（CRE）组织的招标。更新后的清单提供有效ECS证书信息，包括组件型号、制造商、技术类型、最大功率以及所满足的碳足迹阈值。为便利新旧认证体系过渡，Certisolis还上线了一个在线计算工具。","scd":{"b":2.0,"i":4.0,"r":4.0,"d":5.0,"t":6.0},"kp":["认证要求[法国低碳光伏支持机制]: 简化碳评估(ECS)证书符合碳足迹标准","适用机制[ECS认证]: S21上网电价及CRE招标"]},{"i":60135,"as":"垂直光伏专业公司Over Easy Solar在爱尔兰都柏林完成了其首个垂直光伏系统安装。该系统容量5.37千瓦，由21个Over Easy Solar的VPV单元组成，采用其第三代XM-3 QUATTRO-256S预制轻量化垂直双面光伏单元。安装通过与荷兰可持续城市自然解决方案公司Sempergreen的合作，直接安装在绿色屋顶上。公司国际客户解决方案顾问Keelin Currivan表示，此类安装证明客户无需在绿色屋顶和屋顶光伏之间做选择，面板可管理雨水并为屋顶提供热调节。","scd":{"b":4.0,"i":4.0,"r":5.0,"d":6.0,"t":6.0},"kp":["系统容量[爱尔兰都柏林首个垂直光伏系统]: 5.37 kW","组件数量[垂直光伏系统]: 21个VPV单元","产品型号[垂直双面光伏单元]: XM-3 QUATTRO-256S第三代预组装轻量化单元","安装方式[都柏林项目]: 直接安装于绿色屋顶"]},{"i":60136,"as":"澳大利亚可再生能源署（ARENA）投资1.056亿澳元（约7600万美元）用于超低成本太阳能研究，涵盖12个独立太阳能项目，其中新南威尔士大学（UNSW）研究人员获得了大部分资金（6480万澳元），这是该校在光伏研究领域获得的最大单笔投资。该校研究与企业事务副校长Bronwyn Fox教授表示，自50年前UNSW开创性研发高效硅太阳能电池以来，该校一直是太阳能研究领域的领导者，此次合作将继续巩固优势并推动更便宜的太阳能技术开发。12个项目中有11个……","scd":{"b":5.0,"i":4.0,"r":5.0,"d":6.0,"t":6.0},"kp":["投资总额[ARENA超低成本太阳能研究]: 1.056亿澳元(约7600万美元)","项目数量[UNSW太阳能研究]: 12个独立太阳能项目","UNSW获配资金[单笔最大光伏研究投资]: 6480万澳元"]},{"i":60137,"as":"阳光电源（Sungrow）公布2026年上半年营收309.1亿元人民币（约43.4亿美元），同比下降29.0%；归母净利润下降32.0%至52.6亿元，调整后净利润下降43.0%至42.8亿元。经营现金流增长8.8%至37.4亿元，毛利率提升1.56个百分点至35.92%。储能系统收入下降13.2%至154.6亿元，但占总销售额50%，超过光伏逆变器及其他电力转换产品（收入下降19.2%至123.9亿元）。储能毛利率下降7.49个百分点至32.43%，逆变器业务毛利率上升6.98个百分点至42.72%。海外市场占总收入73.4%。","scd":{"b":2.0,"i":7.0,"r":5.0,"d":8.0,"t":6.0},"kp":["上半年营收[2026年逆变器制造商]: 309.1亿元人民币(约43.4亿美元)，同比下降29.0%","净利润[归母]: 52.6亿元人民币，同比下降32.0%","调整后净利润[2026上半年]: 42.8亿元人民币，同比下降43.0%","经营现金流[2026上半年]: 37.4亿元人民币，同比增长8.8%","毛利率[2026上半年]: 35.92%，提升1.56个百分点"]},{"i":60138,"as":"中国教学科研实验设备制造商Micronewton Technology Development向中国某未公开研究机构交付了一套多源能源实验室系统，用于大学层面热泵、太阳能和热储能的教学与研究。系统核心为R306水-空气热交换装置，是一个可在单一试验台上在空气源、水源和模拟地源运行条件间切换的实验热泵平台。系统基于蒸气压缩制冷循环，使用R134a制冷剂，压缩机额定功率276瓦，并具有额定制冷能力。","scd":{"b":3.0,"i":3.0,"r":4.0,"d":5.0,"t":4.0},"kp":["核心设备[多源能源实验室系统]: R306水-空气热交换器实验装置","功能特点[热泵实验平台]: 可在空气源等多热源模式间切换","应用领域[实验室系统]: 高校热泵、太阳能与热储能教学科研"]},{"i":60139,"as":"研究人员评估了在秘鲁南部两个地点利用全球水平辐照度（GHI）数据估算直接和散射辐照度的模型的可靠性。研究题为《基于GHI的安第斯高海拔地区光伏发电量评估：工作流程性能与辐照度分解模型的系统性局限》，对比了气候截然不同的两个地点：海拔4240米的秘鲁高原Cota Cota和海拔1498米的秘鲁南部干旱海岸山谷Pampas de Majes。研究发现模型结果与Solargis卫星数据之间存在系统性的、与海拔相关的偏差，对安第斯地区光伏发电量估算具有潜在影响。","scd":{"b":4.0,"i":2.0,"r":6.0,"d":6.0,"t":4.0},"kp":["研究对象[秘鲁南部两处高海拔站点]: 基于GHI估算直射和散射辐照度模型的可靠性","关键发现[高海拔地区]: 模型结果与Solargis卫星数据存在系统性、随海拔变化的偏差"]},{"i":60140,"as":"巴西研究人员发现，光伏逆变器启动延迟可导致公用事业级太阳能电站年发电量损失1.88%。他们分析了圣保罗州西部某光伏电站2023年的运行数据，并开发了一套量化日出后逆变器延迟启动相关损失的方法。科学家指出，即使辐照度已足够发电，逆变器启动仍可能延迟；在所分析的电站，记录到的延迟最长达日出后4小时。该方法主要依赖日出时间和电站交流有功功率数据，POA辐照度测量仅在配置和验证阶段需要。","scd":{"b":4.0,"i":3.0,"r":6.0,"d":7.0,"t":5.0},"kp":["年发电量损失[光伏逆变器启动延迟]: 1.88%","研究数据来源[巴西圣保罗州西部公用事业级光伏电站]: 202年运行数据"]},{"i":60141,"as":"北欧太阳能开发商Alight与汽车安全供应商奥托立夫（Autoliv）为101兆瓦的Eurajoki太阳能公园举行落成典礼。该电站位于芬兰西海岸，由Alight建设、拥有和运营，年发电量约100吉瓦时，相当于约2万户家庭用电，是芬兰最大的太阳能电站之一。电力将通过2025年4月签署的长期虚拟购电协议（PPA）供应给奥托立夫，该协议当时被称为芬兰历史上最大规模的此类协议。Alight表示，长期企业购电协议正成为企业锁定可预测能源成本的日益普遍途径。","scd":{"b":2.0,"i":7.0,"r":4.0,"d":6.0,"t":7.0},"kp":["装机容量[芬兰Eurajoki太阳能园区]: 101 MW","年发电量[芬兰Eurajoki太阳能园区]: 约100 GWh","供电规模[芬兰Eurajoki太阳能园区]: 约满足2万户家庭用电","购电协议[Autoliv长期虚拟购电协议PPA]: 长期虚拟电力购买协议"]},{"i":60142,"as":"9月1日，国家电投山东莱阳核电项目一期工程主厂区场平施工全面启动，标志项目建设迈出关键一步。该项目一期工程于2026年7月31日获国务院常务会议核准，规划建设6台'国和一号'大型先进非能动压水堆核电机组，采用我国完全自主知识产权的三代核电技术，满足国际最高安全标准。单机容量154.3万千瓦，年发电量125亿千瓦时，可满足1250万居民年用电需求，每年减排温室气体900万吨。6台机组全面建成后装机约926万千瓦，将成为全国最大核电基地，年输出清洁电力740亿度，供热能力超1.7亿平方米。作为'国和一号'批量化建设首个落地项目，其依托整机100%国产化能力，为我国三代核电规模化推广积累可复制经验。","scd":{"b":3.0,"i":6.0,"r":5.0,"d":7.0,"t":8.0},"kp":["规划机组数[莱阳核电一期]: 6台“国和一号”大型先进非能动压水堆核电机组","单机容量[国和一号机组]: 154.3万千瓦","年发电量[单台国和一号机组]: 125亿千瓦时","供电人口[单台机组年发电量]: 可满足1250万居民年用电需求","减排量[单台机组年温室气体排放减少]: 900万吨"]},{"i":60143,"as":"中国台湾核安全委员会已启动台电提交的马鞍山核电站（台湾第三核能发电厂，位于屏东县恒春镇）重启计划的最终行政程序，将进入正式审查，机组最早可能于2028年恢复运行。该电站商业运行许可证已到期，过去约供应台湾5%的电力。受AI、半导体制造等产业用电需求增长影响（台积电用电约占全台9%），重启核电讨论升温。去年8月公投中赞成票约74%，但未达法定门槛。清华大学核科所所长叶宗光认为机组可能于2028年6月前重启。台湾目前天然气发电占47.2%、煤电31.1%，化石能源近八成，若核电站恢复运行将有助于减少燃煤需求并稳定电价。","scd":{"b":3.0,"i":5.0,"r":6.0,"d":6.0,"t":7.0},"kp":["重启时间[马鞍山核电站]: 最早2028年恢复运行","供电占比[马鞍山核电站历史]: 约供应台湾5%的电力","公投结果[2024年8月重启公投]: 赞成票约74%，未达法定门槛未通过","台积电用电占比[台湾总用电量]: 约9%"]},{"i":60144,"as":"儋州市9月2日召开'十五五'主题新闻发布会，表示将推进'核电入洋''核汽入洋'支撑零碳园区建设，争创国家新型电力系统示范地区。'十五五'期间海南电网计划在儋州投资50亿元，打造'主—配—微'三级协同电网；到2030年全面建成分层分区独立运行网架，实现绿电就近消纳、全链条可溯源，使全域电力碳排放因子降至0.05kgCO₂/kWh以下。核能综合利用方面，将依托昌江核电长距离供热补齐零碳工业热源短板，并打通核能多元利用与绿氢转化链条，推动绿色甲醇、可持续航空燃料等项目落地，建设双碳服务中心提供碳足迹认证等全链条服务。","scd":{"b":3.0,"i":4.0,"r":6.0,"d":7.0,"t":7.0},"kp":["电网投资[海南电网“十五五”期间儋州]: 50亿元","电网结构[儋州新型电力系统]: “主—配—微”三级协同电网","电力碳排放因子[2030年儋州全域]: 降至0.05kgCO₂/kWh以下","建成目标[儋州分层分区独立运行网架]: 2030年全面建成","核能供热[昌江核电长距离供热]: 支撑零碳工业热源及绿色甲醇、可持续航空燃料项目"]},{"i":60145,"as":"核电安全健康档案体系建设工作组近日召开2026年第五次推进会及专题小组会议。会议围绕信息化建设、算力配置、数据治理与共享、数智化应用研发等进展开展研讨，现场演示监管侧及各集团健康档案信息系统功能，阶段性总结成效、梳理问题、部署任务。会议指出当前数据治理初见成效，数据核查机制有效落地；要求坚持目标导向补齐短板，结合试点应用复盘总结，持续统筹数据对标入库、一线需求调研和场景开发落地，保障体系高质量建成，助力我国核电厂运行安全和建造质量提升。","scd":{"b":2.0,"i":3.0,"r":3.0,"d":3.0,"t":6.0},"kp":["[核电安全健康档案体系建设]: 信息化建设、数据治理与共享、数智化应用研发持续推进，数据核查机制有效落地"]},{"i":60146,"as":"劳斯莱斯SMR公司计划在北威尔士安格尔西岛建设的首批三座小型模块化反应堆，其高压汽轮机和阀壳等关键蒸汽轮机部件将由西门子能源位于纽卡斯尔的工厂生产，这是欧洲首次为SMR在本土生产此类部件。该工厂位于C.A.帕森斯工厂原址，自1889年以来参与英国能源基础设施建设，曾为世界首座商业核电站卡尔德霍尔核电站制造蒸汽轮机。西门子能源纽卡斯尔工厂还将成为服务劳斯莱斯SMR英国项目队列的关键部件服务中心。英国官员表示，此举有助于增强能源安全、降低对国际天然气市场的风险敞露，预计将为纽卡斯尔创造和支持超过550个高质量就业岗位，并推动英国SMR供应链发展。","scd":{"b":3.0,"i":6.0,"r":6.0,"d":6.0,"t":7.0},"kp":["[劳斯莱斯SMR首批三座小型模块化反应堆]: 高压汽轮机和阀壳等关键部件由西门子能源纽卡斯尔工厂本土生产，为欧洲首次"]},{"i":60147,"as":"关西电力公司9月4日宣布，将把高滨核电站产生的低放射性废物运往青森县六所村日本原燃公司的低放射性废物埋设中心。专用运输船'青榭丸'号计划9月5日靠泊高滨核电站，9月12日离港。本次运输物为200个专用集装箱，内装1600只废物桶，均为充填固化体，不包括均质固化体。充填固化体是核电站定期检查等作业中产生的金属、塑料、过滤器等固体低放射性废物，经分类后按需切割、压缩或熔融处理，装入废物桶并用水泥基充填材料固化形成。均质固化体通常由浓缩废液等与水泥、沥青均匀混合装桶固化，本次运输未安排此类废物。若受气象等因素影响，运输安排可能调整。","scd":{"b":1.0,"i":4.0,"r":5.0,"d":6.0,"t":8.0},"kp":["运输规模[高滨核电站低放射性废物]: 200个专用集装箱，1600只废物桶","废物形态[本次运输物]: 均为充填固化体（金属、塑料、过滤器等经切割、压缩或熔融后水泥基充填固化），不含均质固化体","运输时间[“青荣丸”号专用运输船]: 9月5日靠泊，9月12日离港"]},{"i":60148,"as":"世界核电运营者协会莫斯科中心（WANO-MC）调试前同行评审的计划阶段已在土耳其阿库尤核电站现场启动，重点面向1号机组。该电站由俄罗斯国家原子能公司承建，是土耳其首座在建核电站。评审团队由王廷奎率队，采用机组人员绩效观察（CPO）方法，在全范围模拟机上设置三类接近真实工况的受控场景，评估主控室操纵员在机组管理、状态监测和模拟设备故障处置中的表现，并分析运行流程、文件质量和应急程序。现场观察显示，运行团队已开展预设场景演练，能识别偏差并采取措施，切换备用控制系统时保持稳定操作。阿库尤核电站规划4台机组，采用第三代+VVER反应堆，单机容量1200兆瓦。","scd":{"b":2.0,"i":5.0,"r":5.0,"d":5.0,"t":7.0},"kp":["评审对象[阿库尤核电站1号机组]: WANO-MC调试前同行评估","评审方式[机组人员绩效观察CPO]: 在全范围模拟机FSS上开展三类接近真实工况的受控场景演练"]},{"i":60149,"as":"班加罗尔初创企业普拉诺斯聚变公司已在其实验装置PRAGYA中产生等离子体，这是印度首个由私营企业开发的紧凑型托卡马克装置，标志着印度私营核聚变研发从设计制造进入实验运行阶段。PRAGYA采用紧凑型低纵横比托卡马克设计，定位为试验平台，不用于商业聚变发电，也不等同于净能量增益，建设周期约八个月。公司计划让其运行近二十年，每天开展10至12次放电，年放电约3000次，积累等离子体行为、设计和控制数据。公司此前开发了计算平台JENGA并推进高温超导磁体项目MAGGA，目标2027年前推动高温超导磁体技术投入运行，2030年建设名为PraniQ的净增益聚变装置。公司由绍里亚·考沙尔和罗山·乔治于2024年创立。","scd":{"b":6.0,"i":3.0,"r":8.0,"d":6.0,"t":7.0},"kp":["设计类型[PRAGYA托卡马克]: 紧凑型、低纵横比托卡马克，印度首个私营企业开发的紧凑型托卡马克","运行计划[PRAGYA]: 运行近二十年，每天10至12次实验性放电，年放电约3000次","建设周期[PRAGYA]: 约8个月","装置定位[PRAGYA]: 试验平台，验证硬件、控制系统与运行经验，非商业聚变发电，未实现净能量增益"]},{"i":60150,"as":"美国能源部橡树岭国家实验室（ORNL）研究人员已完成对辐照后高丰度低浓铀（HALEU）TRISO燃料颗粒的力学性能测量，为下一代核燃料开发与鉴定提供实验数据。TRISO燃料颗粒外包覆热解碳层和碳化硅层等多层保护涂层，具备较强裂变产物滞留能力，是高温气冷堆等重要燃料方案。研究延续ORNL此前对含HALEU的TRISO颗粒开展的中子散射测量，团队利用专用压痕测试系统，对AGRFP计划中TRISO颗粒的内外热解碳层及碳化硅层进行了测量。结果显示辐照后颗粒硬度和刚度出现变化，碳化硅层模量和硬度有所降低。相关数据将用于改进核燃料性能模型，支撑气冷堆技术进一步应用。","scd":{"b":6.0,"i":4.0,"r":7.0,"d":7.0,"t":6.0},"kp":["力学性能测量[辐照后HALEU TRISO燃料颗粒]: ORNL利用专用压痕测试系统完成内外热解碳层及碳化硅层测量","研究对象[AGR-2/AGRFP计划]: TRISO燃料颗粒（含HALEU）","燃料结构[TRISO颗粒]: 外包覆热解碳层和碳化硅层多层保护涂层，具备较强裂变产物滞留能力"]},{"i":60151,"as":"俄罗斯国家原子能公司总裁利哈乔夫9月3日在东方经济论坛期间表示，越南首座核电站宁顺1号核电站的建设和运营合同工作正在推进，相关合同文件正在加紧制定，目标是就项目时间表和配置方案达成具有法律约束力的协议。宁顺1号核电站已选定VVER-1200三代+反应堆作为技术方案，双方还在围绕研究堆开展前期研究工作。越南国会于2024年12月决定重启该项目，该项目曾于2016年暂停。根据越南总理今年3月访俄期间签署的政府间协议，宁顺1号核电站将采用俄罗斯先进技术建设，并使用俄罗斯联邦提供的专项贷款。","scd":{"b":2.0,"i":3.0,"r":4.0,"d":4.0,"t":7.0},"kp":["反应堆技术[越南宁顺1号核电站]: 选定VVER-1200三代+反应堆","项目状态[宁顺1号合同]: 建设和运营合同文件正在制定，目标达成具有法律约束力的协议","资金来源[宁顺1号项目]: 俄罗斯联邦提供的专项贷款","重启决定[宁顺1号项目]: 越南国会2024年12月决定重启（2016年曾暂停）"]},{"i":60152,"as":"劳氏船级社、马士基集团、美国查尔斯顿港和英国费利克斯托港正合作推进'粉红走廊'项目，研究核动力集装箱船在跨大西洋航线部署的安全与安保要求。项目以一艘概念性核动力集装箱船为研究对象，重点分析其在查尔斯顿港与费利克斯托港之间商业航线运行时的港口准入条件和监管要求，研究内容包括船舶安全、安保措施、网络安全、应急响应、保险制度及海事与核能监管要求的衔接。项目第一阶段成果将为潜在第二阶段研究提供依据，后续可能覆盖工程设计、监管安排、立法需求等。劳氏船级社表示，该项目旨在为港口、航运企业和监管机构提供结构化合作框架，明确设立核动力海上运输走廊的实际要求、能力缺口和后续方向。","scd":{"b":4.0,"i":3.0,"r":6.0,"d":4.0,"t":6.0},"kp":["研究项目[核动力集装箱船跨大西洋部署]: '粉红走廊'项目，参与方包括劳氏船级社、马士基、查尔斯顿港、费利克斯托港","研究范围[粉红走廊项目]: 港口准入条件、船舶安全、安保、网络安全、应急响应、保险及海事与核能监管衔接"]},{"i":60153,"as":"瑞典能源和工业部长埃巴·布施9月3日在公开听证中表示，瑞典首座新建核反应堆可能在2030年代中期投入使用，新建核电项目不会依靠国家直接出资建设。瑞典政府已为新核电建设准备支持框架，可能涉及数千亿瑞典克朗规模资金支持，包括贷款及总额约4000亿瑞典克朗的电价担保。布施称这是贷款和价格对冲安排，针对重要基础设施。围绕Vattenfall在林哈尔斯核电站区域推进的新核电项目，瑞典国家将成为维德贝里电力公司的重要所有方。对于政府是否会在瓦罗半岛建设新核电站，布施作出肯定回应，表示新核电有助于增强瑞典在不稳定时期的能源保障能力。","scd":{"b":2.0,"i":3.0,"r":5.0,"d":5.0,"t":7.0},"kp":["投运时间[瑞典首座新建核反应堆]: 2030年代中期","资金支持[瑞典新核电建设框架]: 数千亿瑞典克朗规模，含贷款及总额约4000亿瑞典克朗的电价担保","出资方式[瑞典新建核电]: 不依靠国家直接出资建设"]},{"i":60154,"as":"俄罗斯国家原子能公司计划在2031年前将滨海边疆区核电站接入电网。公司首席执行官利哈乔夫9月3日在东方经济论坛期间表示，项目正按既定目标推进，Rosatom正努力确保首台机组在2027年底前实现'第一罐混凝土'浇筑，按照当前设想，项目目标是在2031年实现并网发电，并在2032年全面投入运行。利哈乔夫同时表示，远东地区特别是滨海边疆区在核能利用方面尚缺乏足够经验，仍需逐步建立相关专业能力和工程支撑体系，Rosatom将继续推进项目建设，以服务当地电力系统需求。","scd":{"b":2.0,"i":3.0,"r":4.0,"d":4.0,"t":7.0},"kp":["并网时间[滨海边疆区核电站]: 2031年并网发电，2032年全面投入运行","工程节点[滨海边疆区核电站首台机组]: 2027年底前实现第一罐混凝土浇筑"]},{"i":60155,"as":"俄罗斯国家原子能公司正考虑在摩尔曼斯克附近建设自有生产设施用于完成浮动核电站建造，原因是相关订单增加后现有合作伙伴产能可能难以满足需求。波罗的海造船厂是Rosatom重要合作方，曾建造'罗蒙诺索夫院士'号浮动核电站及4艘22220型'北极'级核动力破冰船。公司首席执行官利哈乔夫表示，自有生产设施投资预计达数百亿卢布，22220型破冰船批量建造是重要任务，浮动核电站计划涉及数十座。摩尔曼斯克附近选址靠近核动力破冰船船队、港口基础设施和大型城市，具备通向海洋条件。此前Rosatom曾讨论将波罗的海造船厂并入公司，但该厂决定留在联合造船集团体系内，Rosatom接受了这一决定。","scd":{"b":3.0,"i":3.0,"r":6.0,"d":4.0,"t":6.0},"kp":["投资规模[摩尔曼斯克浮动核电站生产设施]: 预计达数百亿卢布","建造方[浮动核电站及核动力破冰船]: 波罗的海造船厂建造'罗蒙诺索夫院士'号及4艘22220型'北极'级破冰船","建设计划[浮动核电站]: 相关计划涉及数十座浮动核电站"]},{"i":60156,"as":"首尔科技大学与斗山能源公司近日签署合作备忘录，将围绕下一代核电站、小型模块化反应堆及核心核设备技术等领域开展产学研合作，提升核设计技术竞争力并培养专业人才。该协议为后续识别、论证和推进联合研究、技术开发及人才培养项目提供机制支撑。双方计划重点评估在核心核设备技术、创新设计和可靠性评估等方向的合作可行性，推动技术和人员交流，共同利用研究设施，合作建设研究基础设施和研究中心，并通过研讨会等形式开展学术交流。首尔科技大学表示将依托自身工程研究基础，结合斗山能源在大型核电站设计领域的产业经验，搭建支持各类反应堆设计与评估技术发展的产学研平台，培养具备实践能力的研究人员。","scd":{"b":2.0,"i":3.0,"r":4.0,"d":3.0,"t":6.0},"kp":["合作领域[首尔科技大学与斗山能源]: 下一代核电站、小型模块化反应堆(SMR)及核心核设备技术产学研合作"]},{"i":60157,"as":"亚美尼亚总理帕希尼扬9月3日表示，俄罗斯国家原子能公司总裁利哈乔夫将于9月访问亚美尼亚，双方将在亚美尼亚境内讨论新建核电站的可能方案。帕希尼扬称，预计利哈乔夫此访将提出俄方关于在亚美尼亚新建核电站的具体设想。亚美尼亚在选择核电项目时将重点考虑经济性和方案报价，目标是获得性价比最高的建设方案。今年5月，俄方曾表示已向亚美尼亚提交一份可满足其长期能源需求的核电站设计方案。帕希尼扬同时指出，亚美尼亚政府更倾向于建设一座模块化核电站，现阶段仍在比较不同技术路线和建设方案。","scd":{"b":2.0,"i":3.0,"r":5.0,"d":4.0,"t":7.0},"kp":["技术倾向[亚美尼亚新建核电站]: 政府更倾向于建设模块化核电站","方案现状[亚美尼亚核电项目]: 已收到Rosatom大型核电站设计方案，正比较不同技术路线"]},{"i":60158,"as":"Rosatom核能第一副总经理彼得罗夫在东方经济论坛期间表示，俄罗斯能源部已支持在萨哈共和国（雅库特）推进浮动式小型核电站方案。按照总体规划，雅库特小型核电站需在2031年前建成，新方案将原先的陆上核电站调整为浮动式核电站，其造价更低、建设周期更短，可满足雅库特当前约106兆瓦的电力需求。该项目原计划采用最新的RITM-200N反应堆装置，Rosatom与萨哈共和国政府于2019年签署相关协议，原方案拟建在亚纳河沿岸乌斯季扬斯基区，靠近乌斯季库伊加镇，建成后有望成为俄罗斯首座采用新型设计的陆上小型核电站，此次调整意味着建设形式可能发生变化。","scd":{"b":4.0,"i":4.0,"r":7.0,"d":6.0,"t":8.0},"kp":["建成时间[雅库特小型核电站]: 2031年前建成","电力需求[雅库特]: 约106兆瓦","方案调整[雅库特小型核电站]: 由陆上核电站调整为浮动式核电站，造价更低、建设周期更短","原设计反应堆[雅库特小型核电站]: RITM-200N反应堆装置，原选址乌斯季扬斯基区乌斯季库伊加镇"]},{"i":60159,"as":"韩国水力原子能公司韩光核电站总部确认，韩光核电站1号和2号机组在设备冷却水换热器维护中曾使用未进行冲击试验的焊接工艺规程。自2007年更换相关换热器以来的14项维修作业中有6项存在同类不合规情况，问题是在韩光1号机组第28次计划性预防性维护期间发现。原因是相关人员解读ASME规范时误判该焊接工艺规程可免除冲击试验，但经冲击试验与未经冲击试验的规程在实际维护变量上并无差异。总部计划对可确认位置的既往维修区域实施返工，难以确定位置的区域通过更换部件处理，措施计划于明年4月前完成。涉事换热器功能是降低冷却水温度，与反应堆安全或放射性物质泄漏无直接关联。韩光1、2号机组原计划明年上半年接受继续运行审查。","scd":{"b":2.0,"i":4.0,"r":7.0,"d":6.0,"t":7.0},"kp":["不合规数量[韩光核电站换热器维修]: 2007年以来14项维修作业中6项使用未做冲击试验的焊接工艺规程","涉及机组[韩光核电站]: 1号和2号机组设备冷却水换热器水室维修","违规原因[焊接规程误用]: 人员解读ASME规范时误判可免除冲击试验","整改计划[韩光核电站]: 可定位区域返工、难定位区域更换部件，明年4月前完成"]},{"i":60160,"as":"俄罗斯总统普京在东方经济论坛全体会议上表示，俄罗斯在小型核电站建设方面具有独特地位，相关项目并非停留在规划和讨论阶段，而是已经进入实际建设。普京称，俄罗斯是全球唯一一个不仅讨论发展小型核电必要性和可能性、而且正在采取行动建设的国家，目前除俄罗斯外其他国家尚未开展同类建设。","scd":{"b":2.0,"i":3.0,"r":3.0,"d":2.0,"t":7.0},"kp":["小型核电站建设[俄罗斯]: 已进入实际建设阶段，全球唯一采取行动建设的国家"]},{"i":60161,"as":"据知情人士透露，匈牙利新政府认为基于Rosatom设计的保克什二期核电项目，只有进行重大调整后才有可能继续推进。受伦理、技术、制裁限制、许可程序及现有合同条款影响，项目难以按原安排实施，但直接放弃并不合适，若引入更多西方企业共同解决替代零部件供应、欧盟协调和许可问题，项目仍有继续空间。匈牙利政府正审查相关协议和合同，未完全排除放弃VVER-1200反应堆、转向SMR的选项，同时认识到终止协议可能面临数十亿欧元赔偿风险。该项目依据2014年俄匈政府间协议推进，预计投资125亿欧元，约80%资金来自俄罗斯贷款，两台机组计划于2030年代上半叶投运，5号机组已于今年2月浇筑首罐混凝土。","scd":{"b":3.0,"i":4.0,"r":8.0,"d":5.0,"t":7.0},"kp":["反应堆类型[保克什二期项目原设计]: 俄罗斯VVER-1200","项目前景[保克什二期]: 需重大调整方可推进，或转向小型模块化反应堆(SMR)"]},{"i":60162,"as":"韩国水力原子能公司韩蔚核电站9月3日对6号机组开展全面辐射灾害预防演练，检验辐射紧急情况下的应急响应体系和现场处置能力。演练按照韩国核安全研究院制定的评估指南，依据《国家辐射应急预案》组织实施，演练方案未提前公开，评估方式作出调整。演练中全体应急人员参与处置，现场模拟控制区内发生人员伤亡事故并组织医疗救援，同时使用一台3.2兆瓦移动发电机对应急设施运行能力进行检查。此次演练对人员应急技能、跨部门协同响应机制及应急设施运行状态进行了综合检验。韩蔚核电站厂长李勇熙表示，将根据演练中发现的问题进行整改，并通过持续培训提升应急响应能力。","scd":{"b":2.0,"i":3.0,"r":4.0,"d":4.0,"t":7.0},"kp":["移动发电机[应急演练设备]: 3.2兆瓦","演练评估依据[韩蔚核电站6号机组]: 韩国核安全研究院(KINS)评估指南及国家辐射应急预案"]},{"i":60163,"as":"美国纳米核能公司9月3日宣布，其KRONOS MMR能源系统主氦气循环器开发取得新进展，与贝克休斯旗下豪顿公司的工程合作已从初步工程设计推进至详细设计阶段。主氦气循环器是KRONOS MMR能源系统的关键机械子系统，用于驱动氦冷却剂在反应堆内循环，将堆芯热量传递至后续系统，其性能直接关系反应堆热工表现、整体效率和长期运行可靠性。豪顿公司已完成关键工程评估、详细三维设计模型、相关工程分析，并与纳米核能公司进行了正式设计评审。下一阶段工作包括部件鉴定、材料与性能测试、设计优化和制造计划制定。此前纳米核能公司还宣布与富迪公司推进KRONOS MMR燃料处理与存储系统设计合作。KRONOS MMR是固定式高温气冷微型模块化反应堆，目前正与美国核管理委员会进行施工许可预申请沟通。","scd":{"b":5.0,"i":5.0,"r":6.0,"d":6.0,"t":8.0},"kp":["主氦气循环器[KRONOS MMR能源系统]: 由豪顿公司负责设计，已从初步工程设计推进至详细设计阶段","主氦气循环器功能[KRONOS MMR]: 驱动氦冷却剂循环，传递堆芯热量至后续系统"]},{"i":60164,"as":"立陶宛国际能源码头运营商KN能源公司9月3日宣布加入由波兰奥伦集团发起的波罗的海能源倡议。该倡议汇集北欧和中欧9个国家的14家能源企业和机构，计划通过区域合作提升波罗的海地区能源安全、基础设施韧性和产业竞争力。合作重点包括海上风电、液化天然气市场融合、区域氢能市场建设、碳运输与封存以及小型模块化反应堆开发，参与方还将共同争取欧盟项目资金及国际融资支持。签署方来自波兰、芬兰、瑞典、丹麦、德国、立陶宛、拉脱维亚、爱沙尼亚和挪威，包括富腾、西门子能源、挪威船级社等多家机构。倡议还将推动成员在监管事务和投资安排上形成共同意见，并围绕关键基础设施保护、网络安全、应急准备等领域交流经验。","scd":{"b":2.0,"i":3.0,"r":5.0,"d":4.0,"t":6.0},"kp":["波罗的海能源倡议[区域合作]: 涵盖9国14家能源企业机构，重点包括海上风电、LNG、氢能、碳运输封存及SMR开发"]},{"i":60165,"as":"9月3日，日本泊核电站3号机组重启计划审查会议召开。日本原子能规制委员会指出，北海道电力公司就消防安全措施提交的说明仍存在需进一步确认的问题，要求补充更详细的评估材料。设备设计和施工计划自去年以来处于审查阶段，当前重点之一是厂内发生火灾时作业人员是否具备充分可行的疏散措施。北海道电力说明了修订后的消防安全措施，称已对照《消防法》标准确认灭火剂及疏散方法的安全性，但规制委员会认为仅说明'已经确认'不足以支撑审查结论，要求提交说明具体评估方法和审查过程的细化文件，相关内容需追加审查。北海道电力此前提出3号机组'最快于明年'恢复运行，最终修订文件提交时间可能推迟，对重启进度的影响有待观察。","scd":{"b":2.0,"i":4.0,"r":5.0,"d":4.0,"t":7.0},"kp":["泊核电站3号机组[重启审查]: 消防安全文件需补充细化评估材料，文件提交或推迟","重启计划[泊核电站3号机组]: 最快明年恢复运行"]},{"i":60166,"as":"具身智能产业发展催生数据采集员新职业，从业者佩戴采集头环，在炒菜、擦桌、叠衣等日常场景中采集真人行为数据，作为训练机器人的数据燃料。该职业时间灵活、无需坐班，有宝妈月收入四千多元，为普通群体打开灵活就业通道。2026年被视作具身智能数据规模化元年，各地布局数据采集中心，招聘平台出现大量兼职岗位。但行业尚处起步阶段，存在设备体验参差不齐、薪资待遇分化、行业标准缺失等问题。","scd":{"b":3.0,"i":3.0,"r":6.0,"d":4.0,"t":5.0},"kp":["数据采集方式[具身智能数据采集员]: 佩戴采集头环采集居家家务动作，数据自动回传并后台质检","行业发展阶段[具身智能数据采集]: 起步阶段，存在设备体验参差、薪资分化、标准缺失问题"]},{"i":60167,"as":"一篇题为《数据资产出资的风险类型及制度因应》的论文因注释中判决书序号呈1234、3456等连号引发质疑。作者所在高校通报称问题系作者误信AI检索结果、对AI生成内容缺乏严谨性所致，并对责任人作出处理。文章指出大模型存在AI幻觉问题，用AI拼凑文献考据危害学术诚信，呼吁高校建立更严格的审核机制，并提醒AI幻觉在识菇、问路等日常场景同样带来风险，工具无法代替人的求证与判断。","scd":{"b":2.0,"i":2.0,"r":5.0,"d":3.0,"t":6.0},"kp":["AI幻觉[大模型学术应用]: AI生成虚假引用案例致论文出错，问题尚未有效解决"]},{"i":60168,"as":"在合肥举行的2026年深空探测（天都）国际会议上，深空探测实验室执行主任史平彦表示，深空探测正从一次性消耗品模式转向可循环、可生长、可盈利的新范式，依靠原位资源利用实现从靠地球到靠原位的转变，商业模式由烧钱转向造血，实施主体从政府转向政府指导、商业助力。关于地外生命探寻，行星科学研究中心主任秦礼萍强调其核心是寻找支撑生命的物质条件和生命痕迹而非找外星人，即便未发现生命，宜居环境研究也有助于理解地球生命起源。","scd":{"b":4.0,"i":3.0,"r":5.0,"d":3.0,"t":7.0},"kp":["深空探测范式转变[技术路线]: 从一次性消耗品转向可循环、可生长、可盈利，依靠原位资源利用"]},{"i":60169,"as":"黑客松（Hackathon）由Hack与Marathon组合而成，指参赛者围绕主题临时组队，在限定时间内完成需求分析、方案设计、技术开发和成果展示的编程马拉松，重视快速试错与协作创造而非成熟产品。该模式1999年诞生于加拿大，2012年由SegmentFault引入中国。AI显著降低创意实现门槛，推动黑客松爆发：据Dr.Job报告，全球AI黑客松赛事从2024年约2800场增至2026年预计4200场；2026年以来仅粤港澳大湾区已举办28场，北上深等城市赛事几乎月月不断。","scd":{"b":2.0,"i":3.0,"r":4.0,"d":3.0,"t":4.0},"kp":["黑客松[创新模式]: 限定时间内完成需求分析到成果展示，重视快速试错与从0到1验证"]},{"i":60170,"as":"工信部数据显示，今年1—7月我国规模以上电子信息制造业增加值同比增长15.4%，集成电路产量3342亿块增长23.1%，电子元件产量5.3万亿只增长15%。出口交货值增长8%，锂电池出口31.5亿个增长22.9%，家电出口27.4亿台增长5.9%。行业实现营收11.1万亿元增长19.4%，利润总额7057亿元同比大增105%。固定资产投资增长7.8%。分区域看，中部地区营收22095亿元增速最快达45.9%，东部76436亿元增长14.1%。","scd":{"b":1.5,"i":7.0,"r":6.0,"d":9.0,"t":7.0},"kp":["集成电路产量[1-7月中国]: 3342亿块，同比增长23.1%","电子元件产量[1-7月中国]: 5.3万亿只，同比增长15%","利润总额[规模以上电子信息制造业前7个月]: 7057亿元，同比增长105%","营业收入[规模以上电子信息制造业前7个月]: 11.1万亿元，同比增长19.4%","锂离子蓄电池出口[前7个月中国]: 31.5亿个，同比增长22.9%"]},{"i":60171,"as":"工信部会同国家发改委、科技部等十部门联合印发《促进中小企业发展十五五规划》。规划提出到2030年中小企业整体发展量质齐升：规模以上工业中小企业研发费用内部支出年均增长8%以上；专精特新中小企业数智化水平二级占比达95%以上、三级占比80%以上；全国中小企业服务一张网效能显著提高，防范化解拖欠账款长效机制基本建立。规划从稳企业稳就业、强化专精特新培育、数智化绿色化转型、协同融通发展、要素供给、服务体系、法律政策保障七方面部署任务。","scd":{"b":1.5,"i":3.0,"r":5.0,"d":6.0,"t":7.0},"kp":[]},{"i":60172,"as":"2026年柏林消费电子展（IFA）迎来超900家中国参展商，接近总数一半。行业认为AI竞争重心正从上半场大模型能力比拼转向下半场物理AI落地，北京智源研究院《2026十大AI技术趋势》称2026年是AI从数字世界迈向物理世界的分水岭。物理AI指人工智能在现实环境完成感知、决策、执行闭环，竞争核心从参数算力转向真实场景、终端入口和生态协同，用户体验成为评判标准。小米携人车家全生态完成迄今最大规模海外亮相，成为消费级物理AI落地的重要观察样本。","scd":{"b":4.5,"i":5.0,"r":5.0,"d":4.0,"t":6.0},"kp":["AI技术趋势[智源研究院2026预测]: 2026年是AI从数字世界迈向物理世界的分水岭","中国参展商数量[2026年IFA展会]: 超过900家，占全部参展商近半数"]},{"i":60173,"as":"法国公用事业公司Engie旗下Engie Zielona Energia宣布收购位于波兰中部的一个438兆瓦/876兆瓦时大型电池储能项目，该项目此前由Mithra Energy和Futureal Group旗下成员开发。项目计划于今年第四季度达到可开工状态，2029年第一季度投运。储能设施位于罗兹省Trebaczew，将直接与Trebaczew发电站连接，便于电力送出，减轻当地输电基础设施负担并提升区域供电可靠性。","scd":{"b":1.0,"i":6.5,"r":6.0,"d":7.0,"t":8.0},"kp":["储能项目规模[波兰中部电池储能]: 438 MW/876 MWh","投运时间[该项目]: 2029年第一季度"]},{"i":60174,"as":"波兰开发商R.Power Renewables宣布其电池储能设施在最新容量市场拍卖中获得2027年交付的年度合同，总容量75.994兆瓦。拍卖于9月3日结束，成交价在每千瓦每年325.56至372.04兹罗提之间。履约储能设施的并网容量为159.5兆瓦，独立装置合同容量按95%的KWD系数调整，BESS+PV混合装置按53.86%调整。合同期内总收入至少可达2474万兹罗提。","scd":{"b":1.0,"i":6.0,"r":6.0,"d":7.0,"t":8.0},"kp":["中标容量[波兰容量市场拍卖2027交付]: 75.994 MW","容量市场成交价格区间[波兰补充拍卖]: PLN 325.56-372.04/kW/年（约USD 87-99/EUR 75-85）"]},{"i":60175,"as":"太平洋煤气电力公司（PG&E）公布一项名为SHARE（智能家庭资产助力可靠性与效率）的虚拟电厂（VPP）计划，将在加州湾区聚合家用电池、智能设备和带电池热泵，被描述为同类首创的VPP概念验证项目。PG&E与Rewiring America、谷歌、Carrier、特斯拉、Sunrun、Renew Home、Demand Side Analytics、encoord等多家伙伴合作，项目由谷歌全额资助，计划接入近2.1万台现有柔性用能设备，新部署将与Carrier合作进行。","scd":{"b":3.0,"i":6.0,"r":7.0,"d":5.0,"t":8.0},"kp":["VPP技术方案[加州湾区SHARE计划]: 聚合家用电池、智能设备和电池驱动热泵的虚拟电厂示范"]},{"i":60176,"as":"Flex同意以44亿美元（约37.8亿欧元）收购美国电力转换技术公司EPC Power，获得服务于数据中心、公用事业级储能和微电网的技术与制造能力。EPC Power开发制造高性能软件定义的电力转换解决方案，其平台将纳入Flex面向关键基础设施的电力与热管理技术组合。EPC Power目前控股股东为高盛另类投资和Cleanhill Partners，后者于2021年首次投资该公司。","scd":{"b":4.0,"i":8.0,"r":6.0,"d":6.0,"t":8.0},"kp":["收购金额[Flex收购EPC Power]: 44亿美元","技术属性[EPC Power]: 高性能软件定义电源转换解决方案"]},{"i":60177,"as":"韩国计划在新的政府主导选址体系下，到2031年指定25吉瓦海上风电预备区域，以加速项目开发，支撑2040年45吉瓦海上风电部署目标。政府在本周海上风电委员会首次会议上正式启动该规划框架，将提前识别合适场址，评估风况、环境、渔业活动、海上交通和军事行动等因素，并与地方政府合作争取社区接受后再选择开发商。首个预备区域计划于2026年底前指定，其中约20吉瓦容量可能通过竞争性招标推出。","scd":{"b":2.0,"i":3.0,"r":5.0,"d":6.0,"t":7.0},"kp":["海上风电规划[韩国2031年]: 指定25 GW预备海上风区","海上风电目标[韩国2040年]: 部署45 GW"]},{"i":60178,"as":"电网运营商TenneT在荷兰完成了2吉瓦海上风电平台的第一个主要结构段吊装，实现项目关键里程碑。该平台将用于输送荷兰北海IJmuiden Ver Beta海上风电场（2吉瓦）的电力。重约1700吨的结构段在弗利辛根的Heerema Fabrication Group船厂完成吊装，为导管架两座塔架之一的一半，其余主要结构段将陆续吊装。完整基础结构长约100米、宽55米、高46米，最终总重约1万吨。","scd":{"b":4.0,"i":7.0,"r":5.0,"d":7.0,"t":7.0},"kp":["海上风电平台容量[荷兰TenneT]: 2 GW","结构段重量[首个大型结构段]: 约1700吨"]},{"i":60179,"as":"丹麦陆上风电公司Dansk Vindenergi向欧盟法院提起诉讼，请求撤销欧盟委员会对丹麦Hesselo和North Sea I Mid海上风电项目国家援助的批准。两个项目合计容量至少1.8吉瓦，此前由瑞典Vattenfall中标，获得20年期双向差价合约（CfD）形式的国家支持。丹麦政府是在2024年12月海上风电拍卖无人投标后推出该支持计划，欧委会已于今年3月批准。Dansk Vindenergi同时申请临时措施，要求在案件解决前暂停该批准。","scd":{"b":1.5,"i":3.0,"r":5.0,"d":6.0,"t":7.0},"kp":["合计装机容量[Hesselo与North Sea I Mid项目]: 至少1.8 GW","国家援助形式[两项目]: 20年期双向差价合约(CfD)，由Vattenfall中标"]},{"i":60180,"as":"一台3兆瓦单机浮动式风机已从挪威Gulen的Wergeland Base拖航至英国中北海Culzean气田现场，将为该天然气平台供电。这是2023年苏格兰皇家财产局INTOG创新及油气定向租赁轮次中13个获得海床使用权项目里首个安装的项目。项目现由NEO NEXT+ Energy运营，系今年NEO Energy、Repsol UK与道达英国上游业务合并后成立。风机在挪威西部Wergeland Base组装，Archer旗下浮式风电单元Archer Wind担任EPC承包商。","scd":{"b":5.0,"i":6.0,"r":7.0,"d":6.0,"t":8.0},"kp":["单机容量[英国北海浮动风机]: 3 MW","项目属性[Culzean气田平台供电]: INTOG租赁轮次13个项目中首个安装的浮动风电项目"]},{"i":60181,"as":"西班牙电网运营商REE数据显示，8月份可再生能源占全国发电量的53.6%，计入自发自用装置估计出力后占比升至55.1%。不含自用的可再生能源发电量总计13640吉瓦时，同比增长11%；自用系统发电约1600吉瓦时。7月份该比例分别为54.1%和55.7%。太阳能光伏连续第五个月保持西班牙最大发电来源地位，占全国电力结构29.2%，发电量同比增长27.5%至7445吉瓦时，并创下最大日发电量新纪录。","scd":{"b":1.0,"i":6.0,"r":4.0,"d":8.0,"t":7.0},"kp":["可再生能源发电占比[西班牙8月]: 53.6%","可再生能源发电占比[含自用电估计]: 55.1%","可再生能源发电量[不含自用电,8月]: 13,640 GWh","可再生能源发电量同比增速[西班牙8月]: 11%","自用电系统发电量[西班牙8月估算]: 约1,600 GWh"]},{"i":60182,"as":"丹麦风机制造商维斯塔斯获得德国两个风电项目共108兆瓦订单。其一来自European Energy德国公司，为Wulfshagen风电场改造项目订购8台V162-6.2兆瓦风机，共50兆瓦，2027年一季度开始交付，四季度启动调试，并签订20年期AOM 4000（2台）和AOM 5000（6台）服务协议。另一订单为Ueberhaesiges Viertel风电项目采购8台V172-7.2兆瓦风机，共58兆瓦。","scd":{"b":2.0,"i":6.0,"r":3.0,"d":6.0,"t":6.0},"kp":["订单总容量[维斯塔斯德国项目]: 108 MW","风机型号[Wulfshagen项目]: V162-6.2 MW","风机数量[European Energy订单]: 8台","订单容量[Wulfshagen技改项目]: 50 MW","交付时间[维斯塔斯]: 2027年第一季度"]},{"i":60183,"as":"德国公用事业公司EnBW已完成向丹麦Eurowind Energy出售其瑞典可再生能源平台的交易，剥离约120兆瓦在运陆上风电场及开发项目组合，该交易需通过瑞典外国直接投资审查。除发电资产和开发项目外，平台还包含运维（O&M）业务，交易金额未披露。Eurowind表示此次收购为其在瑞典的长期增长奠定坚实基础，凭借专业团队、在运资产和新开发机会，将助力瑞典未来能源发展。","scd":{"b":1.0,"i":7.0,"r":4.0,"d":5.0,"t":7.0},"kp":["剥离运营风电容量[EnBW瑞典平台]: 约120 MW"]},{"i":60184,"as":"日本工业机械制造商Amada披露，正建设光伏电站组合，将其本土制造业务部署的太阳能发电能力提升至6.4兆瓦。新组合包括4个现场购电协议（PPA）模式下的太阳能阵列，其中3个已在公司自有工厂屋顶投入运营。四个系统合计年发电量估计约6000兆瓦时，运营合同期20年，这是Amada首次以PPA模式使用太阳能发电。","scd":{"b":1.5,"i":5.0,"r":3.0,"d":5.0,"t":5.0},"kp":["光伏发电容量[Amada日本国内制造业务]: 6.4 MW","光伏电站数量[现场PPA模式]: 4个"]},{"i":60185,"as":"芬兰绿色能源服务商Enersense International获得合同，负责运营和维护Alight公司近期投运的101兆瓦峰值太阳能园区。该电站位于芬兰西海岸Eurajoki市，年发电量约100吉瓦时，可满足约2万户家庭用电需求。Enersense签署了覆盖该光伏园区及其配套变电站的协议，将负责光伏电站的全面运维，以及变电站的运营管理、故障响应、检查和维护服务。","scd":{"b":1.0,"i":6.0,"r":3.0,"d":6.0,"t":6.0},"kp":["太阳能园区容量[Alight芬兰Eurajoki]: 101 MWp","年发电量[该太阳能园区]: 约100 GWh","供电能力[该太阳能园区]: 约20,000户家庭"]},{"i":60186,"as":"德国汉堡可再生能源公司LichtBlick SE在德国米尔豪森市并网投运一座太阳能园区，年发电量约45 GWh。该电站由71000块光伏组件组成，占地约37公顷，规模约44 MWp，是该公司最大的太阳能园区，可满足超1.3万户家庭用电需求。项目由LichtBlick子公司Solargruen开发，德国EPC公司Goldbeck Solar担任总承包商。LichtBlick计划在其自有发电和储能容量方面投资约6亿欧元。","scd":{"b":1.5,"i":8.0,"r":4.0,"d":7.0,"t":6.0},"kp":["太阳能园区容量[LichtBlick德国Muehlhausen]: 约44 MWp","年发电量[该园区]: 45 GWh","组件数量[该园区]: 71,000块","占地面积[该园区]: 约37公顷","供电能力[该园区]: 超13,000户家庭"]},{"i":60187,"as":"爱尔兰将开展都柏林地震勘探调查项目，采集都柏林市深层地下地热信息，评估可再生地热供暖潜力。该项目由气候、能源与环境部在欧洲地热区域供热供冷日2026会议上宣布，将采用无损地球物理技术对地下最深3公里进行成像。数据将降低都柏林深部地热项目的不确定性，支持GEMINI示范项目框架下在Grangegorman开展深部地热钻探，调查结果还可推广至爱尔兰其他地区，助力评估全国地热潜力。","scd":{"b":3.0,"i":3.0,"r":5.0,"d":4.0,"t":5.0},"kp":["探测深度[都柏林地震勘探项目]: 地下3 km","技术特点[勘探方式]: 非侵入式地球物理技术成像地下结构"]},{"i":60188,"as":"官方报告显示，2025年7月至2026年6月的12个月内，北爱尔兰可再生能源发电量达4431 GWh，占最终电力消费总量的50%，占总发电量的53%。自2026年1月起，可再生能源发电量在滚动12个月基础上已超过非可再生能源。风能占可再生能源发电的74%，生物质能占18%，太阳能占6%，垃圾填埋气和水电/潮汐各占1%。过去一年北爱尔兰净进口电力578 GWh，高于上年同期的172 GWh。","scd":{"b":1.0,"i":6.0,"r":6.0,"d":7.0,"t":6.0},"kp":["可再生能源发电量[北爱尔兰2025年7月至2026年6月]: 4,431 GWh","可再生能源占最终电力消费比[北爱尔兰滚动12个月]: 50%","可再生能源占总发电量比[北爱尔兰滚动12个月]: 53%","关键状态[北爱尔兰]: 2026年1月起可再生能源发电量超过非可再生能源"]},{"i":60189,"as":"合成航空燃料开发商Arcadia eFuels与综合能源公司MB Energy签署谅解备忘录，共同探索在欧洲建立电力合成可持续航空燃料(eSAF)的端到端供应链。双方将评估MB Energy作为Arcadia eFuels项目组合所产eSAF的承购和分销合作伙伴的潜在角色，并制定涵盖合成燃料运输、储存、掺混及交付至主要航空市场的物流方案。MB Energy旗下储罐子公司enport也参与合作，其在德国、丹麦和匈牙利运营13个终端，提供能源产品储存和物流基础设施。","scd":{"b":2.0,"i":3.5,"r":4.0,"d":3.0,"t":5.0},"kp":["合作内容[欧洲eSAF供应链]: 端到端合成航空燃料供应链开发及承购分销与物流概念设计"]},{"i":60190,"as":"德国能源公司Uniper SE已获得潜在承购方足够的容量预留，将推进其计划在德国威廉港建设的氢进口码头项目。该公司完成了5月启动的开放季节程序第一阶段，与市场参与者签署了意向书。这些容量预留使Uniper能够继续开展进一步开发、许可和商业化活动。下一阶段将包括发布意向条款和制定码头使用协议。该模块化码头计划以氨作为氢载体进行进口，最终年吞吐量可达260万吨。","scd":{"b":2.0,"i":5.5,"r":5.0,"d":4.0,"t":6.0},"kp":["项目状态[Uniper威廉港氢进口码头]: 获得足够能力预订量，进入开发、许可和商业化推进阶段"]},{"i":60191,"as":"欧洲投资银行(EIB)将芬兰绿色氢气和电子甲烷项目开发商Ren-Gas的融资框架从2.3亿欧元提高至6.8亿欧元。该框架旨在为Ren-Gas在芬兰的电子甲烷项目组合提供项目级债务融资。该公司准备于2026年第四季度将其首个项目——位于芬兰南部坦佩雷的工厂——推进至建设阶段。Ren-Gas开发符合RFNBO标准的电子甲烷项目，将可再生氢与捕获的生物源CO2转化为可再生气体，用于重型运输、海运等难减排领域，其项目组合包含六个国内项目。","scd":{"b":2.5,"i":6.0,"r":5.0,"d":6.0,"t":7.0},"kp":["融资框架[Ren-Gas绿氢及e-甲烷项目]: 6.8亿欧元（由2.3亿欧元上调）","首项目建设时间[坦佩雷e-甲烷工厂]: 2026年第四季度开工"]},{"i":60192,"as":"美国能源基础设施开发商Pacifico Energy计划向韩国海域的Manho和Jindo Baram海上风电项目投资超10亿美元。该公司已向韩国产业通商资源部提交投资承诺声明。Manho(990 MW)和Jindo Baram(1.8 GW)是3.2 GW Jindo海上风电集群的组成部分，将安装在全罗南道珍岛郡海岸，并将与去年获发电事业许可证、目前处于积极开发阶段的420 MW Myeong Ryang项目形成互补。上个月，Manho和Jindo Baram被选为Jindo海上风电的独家开发商。","scd":{"b":1.5,"i":6.0,"r":4.5,"d":6.0,"t":6.0},"kp":["投资承诺[Pacifico韩国海上风电项目]: 超10亿美元（约8.56亿欧元）","装机容量[Manho海上风电]: 990 MW","装机容量[Jindo Baram海上风电]: 1.8 GW","总规模[珍岛海上风电集群]: 3.2 GW"]},{"i":60193,"as":"江苏省发展改革委印发《江苏省重点行业节能降碳改造攻坚三年行动方案(2026-2028年)》，聚焦钢铁、水泥、平板玻璃、炼油、乙烯、合成氨、甲醇、煤电8个重点行业。方案提出稳妥关停一批30万千瓦级及以下煤电机组，对30万千瓦级及以上现役煤电机组实施'一机一策'节能降碳改造，采用汽轮机通流提效、锅炉低氮高效燃烧、烟气余热梯级利用等技术压降供电煤耗，并实施灵活性改造和煤电耦合生物质发电(掺烧10%以上生物质燃料)，配套建设分布式光伏、储能储热等设施。到2028年底，7个工业重点行业达到能效标杆水平的产能比例提高20个百分点，煤电行业标杆机组力争提高15个百分点，能效基准水平以下产能基本清零。","scd":{"b":1.5,"i":4.0,"r":4.0,"d":6.0,"t":6.0},"kp":["关停范围[江苏省煤电机组]: 30万千瓦级及以下具备条件的机组","生物质掺烧能力[煤电耦合生物质改造后]: ≥10%（入炉燃料热值）","改造技术[30万千瓦级及以上煤电机组]: 汽轮机通流提效、锅炉低氮高效燃烧、冷端优化、烟气余热梯级利用、全域智慧集控、快调/深调/宽负荷灵活性改造","配套建设[煤电改造]: 分布式光伏、储能储热等设施"]},{"i":60194,"as":"华中区域(东四省)电力互济交易自7月1日启动连续结算试运行以来成效显著。7月正值迎峰度夏，区域及湖北、湖南用电负荷创历史新高，交易每日组织，累计653家主体完成交易，交易电量超5亿千瓦时，跨省最大互济电力达353.3万千瓦。购电方以燃煤火电为主，售电方主要为燃煤火电和新能源。29家储能电站、1家虚拟电厂实现出清，跨省调节电力分别达45.8万千瓦、0.5万千瓦；抽蓄跨省调节最大电力90万千瓦。市场累计帮助327家新能源企业通过外送交易减弃增发近1亿千瓦时。下一步将持续深化区域电力市场建设，推动省间省内市场有序衔接。","scd":{"b":2.0,"i":6.0,"r":6.5,"d":8.5,"t":7.0},"kp":["交易电量[华中区域东四省电力互济首月]: 超5亿千瓦时","最大互济电力[跨省]: 353.3万千瓦","交易主体[首月参与]: 653家","储能跨省调节电力[29家储能电站]: 45.8万千瓦","虚拟电厂跨省调节电力[1家虚拟电厂]: 0.5万千瓦"]},{"i":60195,"as":"阳光电源'连接的力量'暨PhD Talk活动在山东蓬莱举行，多位博士专家围绕'共赴深蓝'主题探讨清洁能源技术创新与海洋生态保护的连接。阳光电源通过公益基金会携手世界自然基金会(WWF)、一个地球自然基金会等伙伴，在山东砣矶岛启动'海洋阳光林'生态修复实践，通过修复海草床和海藻场改善海洋生物栖息环境。活动还向砣矶岛村委会捐赠一套10.35kW/10kWh光储系统，预计年发电量约12000度，为海岛社区提供应急用电与用能稳定支持。","scd":{"b":1.0,"i":2.5,"r":3.0,"d":2.0,"t":5.0},"kp":[]},{"i":60196,"as":"2026中国(太原)国际能源博览会于9月3日在山西潇河国际会展中心开幕，由山西省人民政府主办，展期4天，展览总面积6万平方米，吸引国内外467家企业参展，规模创历届新高。山西是全国首个全省域能源革命综合改革试点，2025年全省新能源和清洁能源装机达9048.4万千瓦，占比55.1%，首次超过煤电。展会设十大专题展区，覆盖能源全链条，其中三大首设特色展区包括算电协同展区、重卡及充换电展区和新型能源与新型电力展区，集中展示风光储氢一体化、智能电网、虚拟电厂等创新成果。","scd":{"b":3.0,"i":4.0,"r":3.5,"d":6.0,"t":7.0},"kp":["新能源和清洁能源装机[山西2025年]: 9048.4万千瓦","装机占比[山西新能源及清洁能源]: 55.1%，首次超过煤电","展览规模[太原能源博览会]: 6万平方米，467家企业参展"]},{"i":60197,"as":"天合光能发布分布式市场指导价。截至2026年6月底，天合光能210组件累计出货量突破260GW，位居全球第一。基于i-TOPCon Ultra平台技术的N型至尊3代系列组件实现功率与效率双重突破，双面率稳定在85±5%，年均衰减低至0.35%。210系列组件凭借低电压、高功率特点，可提高单串组件功率，降低线缆、压块用量及安装成本。N型TOPCon组件低辐照发电优势突出，在清晨、傍晚及阴雨天气保持良好发电表现，可在峰谷价差拉大的市场环境下提升工商业电站整体收益。","scd":{"b":3.0,"i":8.0,"r":3.0,"d":5.5,"t":6.0},"kp":["累计出货量[天合光能210组件截至2026年6月]: 突破260GW，全球第一","双面率[至尊3代组件]: 85±5%","年均衰减[至尊3代N型组件]: 低至0.35%","技术平台[至尊3代组件]: i-TOPCon Ultra平台N型TOPCon"]},{"i":60198,"as":"西藏林芝多雄河谷为雪崩高发区，2023年1月多雄拉隧道出口特大型雪崩造成17辆车被毁、80余人受困，建立雪崩监测预警体系需求迫切，但高原极端环境下供电是难题。2024年10月，素水科技的直接甲醇燃料电池(DMFC)系统在多雄河谷公路沿线雪崩监测站完成安装投运，该项目与中国科学院崔鹏院士团队合作实施。系统搭配专用低温防护箱，最低可在-40℃极端环境下正常运行。甲醇冰点极低使DMFC具备天然防冻特性，且电堆氧气消耗远低于传统燃油发电机，适应高原缺氧环境，国际上亦有文献记录DMFC在海拔5570米、-38℃环境下完成连续供电测试。","scd":{"b":6.0,"i":6.0,"r":7.0,"d":5.5,"t":3.0},"kp":["最低工作温度[DMFC系统配低温防护箱]: -40℃","投运时间[多雄河谷雪崩监测站DMFC供电]: 2024年10月","供电方式[高原雪崩监测站]: 直接甲醇燃料电池离网独立供电"]},{"i":60199,"as":"9月3日，南网能源发布《关于孙公司破产重整事项的进展公告》。南网能源前期向广西防城港市中级人民法院申请孙公司广西南能昌菱清洁能源有限公司破产重整，防城港中院已裁定受理该申请并指定破产重整管理人。公开资料显示，广西南能昌菱清洁能源有限公司成立于2024年6月6日，注册资本11330万元，主要经营范围为新能源、可再生能源项目投资。","scd":{"b":1.0,"i":3.0,"r":4.0,"d":4.0,"t":8.0},"kp":[]},{"i":60200,"as":"东方日升伏曦高效异质结防眩光组件通过TÜV莱茵防眩光专项测试，按国际标准2PfG 3146/01.26完成评估，获防眩光领域最高等级AAA级认证。测试数据显示：日光眩光概率DGP最大值0.30，优于AAA等级≤0.35阈值；最大眩光亮度3463.94 cd/m²，远低于20000 cd/m²安全限值；10°-80°全入射角度镜面反射率最高仅0.85%。该组件适用于机场周边、高速路域、城市人居密集区及地标公共建筑等光敏感场景，满足民航、交通等领域对防眩光的准入要求。","scd":{"b":5.0,"i":8.0,"r":6.0,"d":7.5,"t":7.0},"kp":["日光眩光概率DGP[伏曦防眩光组件]: 最大0.30，优于AAA级≤0.35阈值","最大眩光亮度[伏曦防眩光组件]: 3463.94 cd/m²（限值20000 cd/m²）","镜面反射率[10°-80°全入射角度]: 最高仅0.85%","认证等级[TÜV莱茵防眩光测试标准2PfG 3146/01.26]: AAA级"]},{"i":60201,"as":"9月1日，天合储能在Middle East Energy 2026上展示面向中东非市场的新一代交直流一体化解决方案Elementa + Electra。直流侧采用最新一代Elementa 3电池系统，单箱容量6.25MWh；交流侧配备13.8MVA的Electra平台，支持2至8小时灵活时长配置。系统全链路效率96%，全功率响应仅需10毫秒，支持构网型和黑启动功能，可在沙特、阿联酋等高温沙漠环境下实现高能量吞吐。中东和非洲地区正加速可再生能源建设，以沙特和阿联酋为代表的国家正以国家战略驱动大规模储能部署。","scd":{"b":5.0,"i":7.0,"r":5.0,"d":6.5,"t":7.0},"kp":["单箱容量[Elementa 3直流电池系统]: 6.25MWh","交流侧容量[Electra交流平台]: 13.8MVA","储能时长配置[Elementa+Electra方案]: 支持2至8小时灵活配置","系统设计[天合储能]: 直流电池系统与交流平台一体化融合"]},{"i":60202,"as":"光伏组件采购风险提示指出，当前市场存在报价明显脱离合理行情、无资质主体从事撮合销售、支付后履约无法兑现等风险。高发风险包括：异常低于市场行情的报价货源，可能存在货源不明、规格不符、无法按期交货问题；无原厂授权的撮合主体货源难溯源、履约保证不足；全额预付货款易在供货方违约时难以追回；假冒贴牌组件工艺性能不达标且无法享有原厂质保。建议做好渠道资质审核、规范交易流程，优先选择原厂官方授权经销商采购，以保障原厂质保与技术配套服务权益。","scd":{"b":1.0,"i":3.0,"r":3.0,"d":2.0,"t":4.0},"kp":["采购风险防控[光伏组件]: 渠道资质审核与规范交易流程是关键，警惕异常低价及无原厂授权撮合主体"]},{"i":60203,"as":"当地时间2026年9月1日，中国华电所属华电海投罗马尼亚科托菲尼154.7兆瓦光伏电站项目正式开工。项目位于罗马尼亚多尔日县，距布加勒斯特约200公里，占地约198.1公顷，是中国华电在欧洲投资建设的首个绿地光伏电站，也是罗马尼亚在建容量最大的集中式地面光伏电站之一。项目采用双面高效组件、箱逆变一体机方案及平单轴跟踪支架，配套建设升压站和输电线路，预计2028年一季度投产。建成后每年可提供约2.4亿千瓦时清洁能源，减少约5.2万吨二氧化碳当量排放。","scd":{"b":2.0,"i":7.0,"r":6.0,"d":7.0,"t":8.0},"kp":["装机容量[华电罗马尼亚科托菲尼光伏电站]: 154.7兆瓦","占地面积[科托菲尼光伏电站]: 约198.1公顷","年发电量[科托菲尼光伏电站]: 约2.4亿千瓦时","年减排量[科托菲尼光伏电站]: 约5.2万吨二氧化碳当量","投产时间[科托菲尼光伏电站]: 预计2028年一季度"]},{"i":60204,"as":"9月3日，固德威在TÜV莱茵'2026质胜中国光储盛典'上斩获储能系统静音性能优胜奖和户用储能系统SOC性能优胜奖两项荣誉。固德威董事长黄敏在领袖论坛分享了基于'源网荷储智'的系统性战略布局，公司已从单一产品制造向全链条能源解决方案服务商升维，构建覆盖户用、工商业、大型电站的完整储能产品矩阵。为满足全场景高效用能与静谧运行双重需求，固德威组建二十余人专项研发团队，联合科研机构突破储能低噪运行行业痛点。","scd":{"b":4.0,"i":7.0,"r":4.0,"d":3.5,"t":7.0},"kp":["储能系统[固德威]: 获TÜV莱茵储能系统静音性能及户用储能SOC性能优胜奖","战略布局[固德威]: 基于源网荷储智的系统性能源解决方案服务商"]},{"i":60205,"as":"美国柔性光伏制造商SolarWindow Technologies推出ElectroFlex柔性光伏组件，厚度仅0.85mm，适用于平面、曲面和不规则表面。组件采用BC电池，电池效率24.4%，功率重量比约73W/kg，初期仅向美国Tier-1 OEM制造商供应。组件背面配有粘接层，可实现'撕贴式'安装，无需传统支架，可集成于卡车、船舶、列车、飞机和建筑等场景。五层结构包括0.10mm正面封装层、0.16mm电池层、0.04mm铜质背衬层、0.30mm复合层和0.25mm背面基材。在输出功率相近情况下，厚度最多比传统组件薄47倍、重量轻5.5倍，多层结构可防止弯曲时电池隐裂。","scd":{"b":6.5,"i":4.0,"r":7.5,"d":8.0,"t":7.0},"kp":["厚度[ElectroFlex柔性光伏组件]: 0.85mm","电池效率[BC电池]: 24.4%","功率重量比[ElectroFlex组件]: 约73W/kg","结构[ElectroFlex组件]: 五层结构，正面封装层0.10mm、电池层0.16mm、铜背衬层0.04mm、复合层0.30mm、背面基材0.25mm","安装方式[ElectroFlex组件]: 背胶撕贴式安装，无需传统支架，适用于平面、曲面及不规则表面"]},{"i":60206,"as":"韩国政府宣布对国有能源和交通企业进行重大重组，作为公共机构改革的一部分，旨在降低成本并提升竞争力。具体措施包括：韩国国家石油公司与韩国天然气公司合并；五家韩国电力公司下属单位合并；韩国煤炭公司清算；四个区域性港口管理局合并。","scd":{"b":1.5,"i":3.0,"r":5.0,"d":5.0,"t":7.5},"kp":["企业重组[韩国国有能源企业]: 韩国国家石油公司与韩国天然气公司合并，五家电力下属单位合并，韩国煤炭公司清算"]},{"i":60207,"as":"9月1日，中国华电所属华电海投罗马尼亚科托菲尼154.7MW光伏电站项目正式开工，这是中国华电在欧洲投资的首个绿地光伏电站。项目位于罗马尼亚多尔日省，由四个45MW子项目组成，合计39个地块，占地约198.1公顷。项目拟采用双面高效电池组件、箱逆变一体机方案及平单轴跟踪支架，配套建设升压站和输电线路，预计2028年一季度投产。此前2026年1月，中国电力工程顾问集团华东院以约7998.65万欧元（约6.55亿元人民币）、4.23元/W的单价中标该项目。","scd":{"b":2.5,"i":6.0,"r":4.0,"d":7.5,"t":6.5},"kp":["装机容量[华电罗马尼亚科托菲尼光伏项目]: 154.7MWac","项目构成[科托菲尼项目]: 四个45MW光伏子项目，合计39个地块","占地面积[科托菲尼项目]: 约198.1公顷","中标价格[华东电力设计院]: 约7998.65万欧元（约合人民币6.55亿元），单价4.23元/W","投产时间[科托菲尼项目]: 预计2028年一季度"]},{"i":60208,"as":"8月31日，山东昌邑市政府发布中核昌邑570MW光伏发电项目（重新报批）环评拟审批公示。项目位于昌邑市下营镇，总投资29.69亿元，施工工期12个月。因部分地块未能按计划征用，用地面积由14000亩调整为11025亩，减少21.3%。设计总容量不变，仍为交流侧570MW（直流侧684MWp），拟安装330kW逆变器1728台，及540Wp、595Wp、7300Wp三种单晶硅双面组件合计约95.5万块。项目尚未开工。","scd":{"b":2.0,"i":4.0,"r":4.0,"d":7.5,"t":6.5},"kp":["交流侧容量[中核昌邑光伏项目]: 570MW","直流侧容量[中核昌邑光伏项目]: 684MWp","总投资[中核昌邑光伏项目]: 29.69亿元","施工工期[中核昌邑光伏项目]: 12个月","逆变器配置[中核昌邑光伏项目]: 拟安装330kW逆变器1728台"]},{"i":60209,"as":"8月30日，吉林油田45万千瓦风光发电项目全容量并网投产。项目盘活油田闲置土地、低效井场等空间，采用'光伏+风电'复合布局，含10万千瓦光伏和35万千瓦风电。风电于2025年12月16日开工，光伏今年2月投产，累计发电8762.5万千瓦时。项目部通过日调度、周复盘、月总结机制及'百日会战'，在6个半月内完成从桩基施工到全容量并网的全部建设任务，并建立精细化安全管控体系，实时监控风速保障吊装安全。","scd":{"b":2.5,"i":7.0,"r":4.0,"d":6.5,"t":7.0},"kp":["总装机[吉林油田风光发电项目]: 45万千瓦（10万千瓦光伏+35万千瓦风电）","累计发电量[吉林油田风光项目截至目前]: 8762.5万千瓦时","布局模式[吉林油田风光项目]: 光伏+风电复合布局，盘活油田闲置土地、低效井场、排涝区"]},{"i":60210,"as":"9月3日，芯联集成与理想汽车签署新一轮战略合作协议，双方共同见证8英寸碳化硅晶圆成功下线。合作场景从整车电驱动延伸至车载热管理系统等领域。芯联集成是国内首家实现8英寸碳化硅晶圆量产的企业，2025年2月已实现6英寸碳化硅晶圆量产并配套理想i系列高压纯电车型。本次下线的8英寸碳化硅芯片即将进入SOP量产阶段，未来双方将加速推进8英寸碳化硅芯片规模化量产。","scd":{"b":6.5,"i":8.0,"r":6.5,"d":6.5,"t":8.0},"kp":["碳化硅晶圆[芯联集成]: 8英寸碳化硅晶圆下线，国内首家实现8英寸量产","量产进程[芯联集成6英寸碳化硅]: 2025年2月量产，配套理想i系列高压纯电车型","应用场景[芯联集成与理想合作]: 从整车电驱动延伸至车载热管理系统"]},{"i":60211,"as":"上海垣信卫星科技有限公司完成工商变更，杭州阿里创业投资有限公司正式登记为新股东，阿里巴巴入局低轨卫星星座独角兽。垣信卫星是'千帆星座'建设运营主体，于2018年3月设立。千帆星座2024年8月发射首批18颗卫星，目前已增至238颗，计划2026年底完成一阶段324星全球组网并启动商业化运营。此前垣信卫星完成69.76亿元增资，引入18家投资方，取得13.94%股权，投后估值约500亿元。","scd":{"b":4.0,"i":6.5,"r":7.0,"d":8.0,"t":8.0},"kp":["千帆星座在轨卫星数[截至2025年9月]: 238颗","千帆星座一阶段全球组网[2026年底]: 324星完成组网并启动商业化运营","千帆星座首批发射[2024年8月]: 18颗卫星","垣信卫星增资金额[本轮18家投资方]: 69.76亿元","联合体出资[国调二期协同发展基金等24家机构]: 约57.6亿元，占比82.6%"]},{"i":60212,"as":"全新奔驰长轴距GLE SUV将于9月16日上市，9月1日在顺义工厂下线。新车轴距提升至3115mm，采用三联屏设计，内置豆包AI大模型虚拟助手，后续将搭载Momenta R7世界模型。配备AR平视显示系统，可实现'车位到车位'智能辅助驾驶与辅助泊车。动力搭载3.0升直列六缸发动机，配备电动辅助增压器，峰值扭矩提升12%至560牛·米，配合17千瓦ISG电机及48伏轻混系统。标配4MATIC四驱，越野模式下空气悬挂可升高30mm，最小离地间隙271mm。","scd":{"b":3.5,"i":6.0,"r":4.0,"d":6.5,"t":7.5},"kp":["轴距[全新奔驰长轴距GLE SUV]: 3115mm","发动机[全新奔驰长轴距GLE SUV]: 3.0升直列六缸，标配电动辅助增压器","峰值扭矩[3.0T+48V轻混系统]: 560牛·米，提升12%","ISG智能电机功率[全新奔驰长轴距GLE SUV]: 17千瓦","车载AI助手[全新奔驰长轴距GLE SUV]: 豆包AI大模型虚拟助手，后续搭载Momenta R7世界模型"]},{"i":60213,"as":"彭博社记者古尔曼称，苹果将以史上最大新品阵容开启新CEO特努斯时代的硬件发布周期。9月9日发布会将发布新一代iPhone和Apple Watch，后续2026年至2027年及更远未来将推出全新产品形态并进入新设备领域。核心新品为折叠屏iPhone（内部称iPhone Ultra），采用大内屏小外屏，折叠后约护照大小，配备A20 Pro芯片、苹果自研C2调制解调器，支持Touch ID和分屏多任务，采用先进铰链并降低折痕，售价预计超2000美元。该产品路线图筹备约5年，大部分项目由特努斯团队负责。","scd":{"b":2.5,"i":4.0,"r":5.5,"d":4.0,"t":8.0},"kp":["新品发布周期[苹果2026-2027年及以后]: 公司历史上规模最大的一轮硬件发布，进入多个此前未涉足的设备领域","产品路线图筹备时间[苹果]: 约5年"]},{"i":60214,"as":"据《商业内幕》报道，英伟达仅用两年时间从零建立起近千亿美元股权投资组合。截至7月26日，公司持有990亿美元股权投资，其中约480亿美元为上市公司股票及可交易证券，约480亿美元为非上市公司股份，另有约30亿美元权益法投资，一年内增长14倍，两年增长45倍。持仓包括价值300亿美元的英特尔股份和210亿美元的SpaceX股份，并投资CoreWeave、Coherent、Synopsys和诺基亚等。英伟达还披露250亿美元投资承诺，投资规模仍低于Alphabet的2320亿美元。","scd":{"b":2.0,"i":5.0,"r":6.0,"d":8.5,"t":8.0},"kp":["股权投资组合规模[英伟达截至7月26日]: 990亿美元","上市可交易证券[英伟达]: 约480亿美元","非上市不可交易证券[英伟达]: 约480亿美元","权益法投资[英伟达]: 约30亿美元","投资组合年增长[一年内]: 增长14倍（去年约70亿美元）"]},{"i":60215,"as":"","scd":null,"kp":[]},{"i":60216,"as":"修订后的《电力安全事故应急处置和调查处理条例》正式公布，将于2027年1月1日起施行。现行条例自2011年施行，已不能适应新型电力系统构建后电源多元化、电网规模扩大、新型并网主体出现的新形势。此次修订将'保障电力系统安全稳定运行和电力可靠供应'补充为立法目的，明确电力企业和用户应服从统一调度、落实事故预防措施。事故等级划分标准方面，调整了'电网减供负荷比例'和'供电用户停电比例'判定指标，增加县级市以外县级行政区域的判定指标。","scd":{"b":2.0,"i":3.0,"r":5.0,"d":4.0,"t":8.0},"kp":["条例施行时间[电力安全事故应急处置和调查处理条例修订版]: 2027年1月1日","立法目的[条例修订]: 新增'保障电力系统安全稳定运行和电力可靠供应'"]},{"i":60217,"as":"日本电机巨头尼得科公布产品质量问题调查委员会报告，确认存在844起擅自变更制造工序等不当行为，可追溯至2012年，其中九成属于未经客户同意变更部件及工序，存在篡改、捏造测试及检查结果情况，60起被认定为重大不当行为，涉及集团高层参与及涉嫌违反法令。报告指出原因是并购扩张后经营体制完善滞后、业绩目标和降成本压力强烈、品质保证人才不足。社长岸田光哉鞠躬致歉，强调产品安全性不受影响，现阶段没有召回计划。","scd":{"b":1.0,"i":3.0,"r":6.0,"d":6.0,"t":8.0},"kp":["不当行为数量[尼得科制造工序变更等]: 844起","重大不当行为[尼得科调查报告]: 60起","不当行为追溯[尼得科]: 至2012年，九成属未经客户同意变更部件及工序","测试数据[尼得科]: 存在篡改、捏造测试及检查结果","产品安全与召回[尼得科]: 确认安全性不受影响，现阶段无召回计划"]},{"i":60218,"as":"长城魏牌公布全新豪华方盒子车型官图。新车配备复古圆形大灯、魏牌发光logo、传统外拉式门把手，车顶配备激光雷达，有望带来高级辅助驾驶功能。长城汽车董事长魏建军透露，该车采用承载式车身，比越野车更舒适、更适合城市场景；搭载2.0T插混系统、后桥机械差速锁和智能中锁，是同价位方盒子里独有的配置。新车定位兼顾城市豪华舒适与山野远行能力。","scd":{"b":2.0,"i":5.0,"r":4.0,"d":5.0,"t":7.0},"kp":["动力系统[长城魏牌豪华方盒子]: 2.0T插混","车身结构[长城魏牌豪华方盒子]: 承载式车身","越野配置[同价位方盒子独一份]: 后桥机械差速锁+智能中锁","感知硬件[长城魏牌豪华方盒子]: 车顶配备激光雷达，支持高级辅助驾驶"]},{"i":60219,"as":"微软宣布推出Project Zenith，为Windows 11开发人员提供开箱即用的开发环境，通过预配置系统和工具减少设置干扰。该环境面向至少64GB统一内存、内存带宽250GB/s以上的设备，首批产品采用AMD Ryzen AI Halo。系统默认固定Windows Terminal和VS Code，文件资源管理器显示文件扩展名、隐藏文件及完整路径，启用长路径支持。支持本地运行超300亿参数AI模型，纳入Windows智能体战略，并通过WSL容器整合Windows与Linux开发环境。","scd":{"b":5.0,"i":5.0,"r":6.0,"d":7.0,"t":8.0},"kp":["最低统一内存[Project Zenith开发环境]: 至少64GB","最低内存带宽[Project Zenith设备要求]: 250GB/s以上","首批芯片平台[Project Zenith]: AMD Ryzen AI Halo","本地AI模型运行能力[Project Zenith]: 参数规模超过300亿，不受云端Token计费限制","预配置特性[Project Zenith]: 显示文件扩展名、隐藏文件、完整路径，启用长路径支持"]},{"i":60220,"as":"9月2日，国家广播电视总局召开AI微短剧'融像''融声'知识产权与人格权益保护座谈会，围绕生成式AI在微短剧创作中涉及的肖像、声音权益使用问题听取行业意见。会议明确三项共识：一是严守授权底线，任何'融像''融声'行为均须取得权利人明确授权；二是科学合理认定侵权，综合生成内容特征、使用场景、主观意图及平台审核义务判断；三是健全全流程风控机制，强化事前授权、事中筛查复核、事后可追溯存证。爱奇艺、红果、快手、腾讯、优酷等17家平台和制作机构代表参会。","scd":{"b":2.0,"i":3.0,"r":5.0,"d":4.0,"t":6.0},"kp":["授权底线[AI微短剧'融像''融声']: 任何使用均须取得权利人明确授权","权益属性[肖像、声音]: 属于自然人的基本人格权益，应充分尊重","风控机制[平台和制作机构]: 事前授权管理、事中技术筛查与人工复核、事后可追溯存证"]},{"i":60221,"as":"","scd":null,"kp":[]},{"i":60222,"as":"百度集团公告，其A类普通股已获纳入沪港通下港股通标的证券，2026年9月7日生效。百度于9月1日完成港交所与纳斯达克双重主要上市，符合港股通纳入条件。纳入预期将多元化投资者基础并提升股份流动性。受此影响，9月4日百度港股盘中一度涨超5.68%。摩根士丹利预计纳入后6至12个月内南向资金持股比例达7%至15%，第三方预测未来2到4个月净新增南向资金或达60亿美元。百度表示不会通过增发或发债融资，现金及投资总额超400亿美元，AI业务收入占一般性业务收入比例已连续两季超一半。","scd":{"b":1.0,"i":4.0,"r":4.0,"d":5.0,"t":8.0},"kp":["港股通纳入生效[百度A类普通股]: 2026年9月7日","双重主要上市完成[百度]: 2026年9月1日港交所与纳斯达克双重主要上市","2021年港股二次上市[百度]: 招股价252港元，集资约237亿港元"]},{"i":60223,"as":"长安启源Q06新能源SUV开启预售，抢订价14.79万元起，提供纯电和增程动力，共602越享型、602智享型、700智享型、700智尊型等多个版本，预售价14.99万至19.19万元。车身尺寸4837/1970/1670mm，轴距2940mm。座舱配备全车零压电动座椅（通风、加热、按摩）、15.6英寸2.5K后排娱乐屏、9.5L冷暖冰箱、2200L拓展空间。辅助驾驶配备560TOPS芯片和256线激光雷达，支持端到端全场景领航及400+场景智能泊车辅助。","scd":{"b":2.0,"i":6.0,"r":3.0,"d":7.0,"t":8.0},"kp":["动力形式[长安启源Q06]: 纯电/增程两种动力","预售价[长安启源Q06起售]: 14.79万元起","车身尺寸[长安启源Q06]: 长4837mm×宽1970mm×高1670mm，轴距2940mm","配置梯度[Q06智享型]: 天枢领航Pro版与Ultra版两种智驾配置"]},{"i":60224,"as":"","scd":null,"kp":[]},{"i":60225,"as":"小米举行龙甲电池战略合作发布会，该产品由小米联合中创新航和欣旺达打造，小米对全链路负责，包括产品定义、电池包设计开发、电芯设计参与及全流程质量管控。小米汽车副总裁黄振宇解释选择两家电池企业合作的原因：一是技术协同，两家均为全球顶级电池供应商，技术积淀各有侧重，与小米整车定义能力形成互补；二是产能保障，有利于保障规模化稳定交付；三是产品精准交互，最重要的是保证用户提车周期的稳定性。","scd":{"b":4.0,"i":7.0,"r":6.0,"d":5.0,"t":8.0},"kp":["电池开发模式[小米龙甲电池]: 小米全链路负责，主导电池包设计开发，联合中创新航和欣旺达","合作决策维度[小米龙甲电池]: 技术协同、产能保障、产品精准交互三维度","产能策略[小米龙甲电池]: 双供应商保障规模化稳定交付与用户提车周期稳定性"]},{"i":60226,"as":"据意大利媒体报道，Stellantis旗下玛莎拉蒂正与华为、江淮汽车洽谈战略合作，作为品牌重振计划的一部分，目标2027年前全面落地。联合开发的首款电动车原型车已进入前期工业造型设计阶段，若协议签署，整车最快2027年底量产下线。项目将采用'双标策略'：同一车型在中国挂'尊界'标销售，海外挂玛莎拉蒂三叉戟标，制造产线落户意大利还是中国尚未确定。Stellantis未正面回应，称不会对市场传闻发表评论。玛莎拉蒂完整战略蓝图将于年底投资者日公布。","scd":{"b":3.0,"i":4.0,"r":7.0,"d":5.0,"t":7.5},"kp":["合作方[玛莎拉蒂电动化]: 与华为、江淮汽车建立战略联盟","合作时间表[玛莎拉蒂-华为-江淮]: 目标2027年前全面落地运营，整车最快2027年底量产下线","开发阶段[首款电动车型]: 已进入前期工业造型设计阶段","销售策略[联合开发车型]: 双标策略，中国挂牌尊界，海外挂玛莎拉蒂三叉戟车标"]},{"i":60227,"as":"","scd":null,"kp":[]},{"i":60228,"as":"据易车报道，比亚迪腾势N8L纯电版将于9月14日正式上市，定位大六座安全豪华SUV，搭载208L超大智能电动前备箱，官方暂未公布更多配置信息。作为参考，腾势N8L于2025年10月28日上市，指导价29.98万元起，车身长宽高为5200x1999x1820mm，轴距3075mm。今年6月23日，腾势N8L闪充版上市，配备第二代刀片电池，其中尊荣型闪充版定价31.98万元，旗舰型闪充版34.98万元。","scd":{"b":2.0,"i":6.0,"r":3.0,"d":4.0,"t":6.0},"kp":["上市时间[腾势N8L纯电版]: 9月14日","前备箱容量[腾势N8L纯电版]: 208L智能电动前备箱","车身尺寸[腾势N8L]: 5200×1999×1820mm，轴距3075mm","指导价[腾势N8L]: 29.98万元起","电池[腾势N8L闪充版]: 第二代刀片电池，31.98万元起"]},{"i":60229,"as":"据《日经亚洲》援引消息人士报道，因苹果对质量控制要求极为严格，折叠屏iPhone（暂称iPhone Ultra）初期日产量截至8月底仅几百部。苹果计划今年生产800万至1000万部折叠屏iPhone，要完成年度生产计划通常每天需生产数万部。苹果在8月增加了一轮试生产和一道验证流程，确认产品能按既定设计量产，导致商业化生产推迟数周。苹果对屏幕平整度、铰链性能和耐用性标准更严，要求设备经受更多次折叠并在更极端条件下测试。若产能爬坡不能加快，可能无法完成既定目标，上市初期或面临渠道库存不足。","scd":{"b":3.0,"i":4.0,"r":7.0,"d":6.0,"t":8.0},"kp":[]},{"i":60230,"as":"小米集团总裁卢伟冰在IFA柏林国际消费电子展期间披露，小米汽车将于2027年进入欧洲市场，并与8家德国首批头部经销商完成签约，雷军转发确认。卢伟冰称德国经销商对小米认知显著变化，调研显示在小米汽车尚未进入的德国市场用户认知度已超过40%。即将出海的车型将奔赴瑞典、德国、西班牙、意大利4国，在Arjeplog冬季测试基地、纽博格林等7大权威测试场进行高速验证与功能测试。8月小米汽车交付量再次超过3万辆，公司正为第二款产品系列SkyNomad澎程（定位智能可变大空间SUV，首推N90 Max和N70 Max，预售价29.99万元和25.99万元）上市交付做准备。","scd":{"b":2.0,"i":5.0,"r":5.0,"d":6.0,"t":7.0},"kp":["出海时间[小米汽车]: 2027年进入欧洲市场","德国经销商[小米汽车]: 已完成8家首批头部经销商签约","用户认知度[小米汽车-德国市场]: 超过40%","8月交付量[小米汽车]: 超过3万辆","测试规划[小米出海车型]: 瑞典、德国、西班牙、意大利4国7大权威测试场验证"]},{"i":60231,"as":"9月2日，中科海钠与韩国VOLTA株式会社签署战略合作协议，将在此前15MWh储能项目基础上，推动5年10GWh长期供货协议落地。根据分工，中科海钠发挥电芯技术与制造优势，VOLTA主导系统集成及韩国本土市场推广，韩国光云大学作为技术验证伙伴提供研发与测试支持。三方将围绕大储、工商储、户储等场景，打通从电芯到系统的全链条商业化闭环。此前中科海钠自主研发的钠离子电池储能系统1.1MWh电池簇已交付德国大型能源企业，满足IEC62619、UN38.3、ROHS及REACH等国际标准。","scd":{"b":5.0,"i":7.0,"r":7.0,"d":6.0,"t":7.0},"kp":["供货规模[中科海钠-韩国VOLTA]: 5年10GWh长期供货协议","既有项目[中科海钠-韩国VOLTA]: 此前15MWh储能项目覆盖大储、户储、工商储","分工模式[钠电池合作]: 中科海钠负责电芯技术与制造，VOLTA主导系统集成及韩国市场推广，韩国光云大学提供研发测试支持"]},{"i":60232,"as":"9月3日，鹏程无限四川宜宾制造基地迎来里程碑，核心生产设备车辆驶入厂区，标志基地告别基建阶段，进入设备安装和产线调试阶段。该基地总投资约48亿元，规划年产54GWh储能电芯，核心主打500+Ah新一代大容量储能电芯产品，具备高能量密度、长循环寿命、高安全性能等优势，可适配大型储能场景，一期预计今年年底实现试生产。同日，鹏程无限与远信储能、象屿能源签署三方战略合作协议，将加速储能技术、创新产品与定制化方案的场景验证和迭代升级，共同推动储能产业规模化发展。","scd":{"b":4.0,"i":6.5,"r":5.0,"d":7.0,"t":7.0},"kp":["投资额[鹏程无限宜宾基地]: 约48亿元","规划产能[鹏程无限宜宾基地]: 年产54GWh储能电芯","核心产品[鹏程无限宜宾基地]: 500+Ah新一代大容量储能电芯，高能量密度、长循环寿命、高安全性能","投产时间[鹏程无限宜宾一期]: 今年年底试生产"]},{"i":60233,"as":"韩国忠清南道唐津市一家锂电池工厂仓库于8月31日上午起火，持续约22小时后于9月1日凌晨5点49分被扑灭，约15吨锂电池被烧毁。消防部门出动165名救援人员和60台装备，并使用无人破拆水炮车和消防机器人。起火仓库建筑约700多平方米，234平方米受损，未造成人员伤亡。一周内电池相关起火事故达三起：8月31日远东股份旗下江西远东电池老化检测车间火灾，8月26日罗马尼亚布泽乌县储能园区电池机房火灾。业内人士表示电池行业须从'事后灭火'转向'事前预防'，加强全生命周期风险管控。","scd":{"b":1.0,"i":3.0,"r":5.0,"d":6.0,"t":7.0},"kp":["火灾事故[韩国唐津锂电池工厂]: 持续约22小时，约15吨锂电池被烧毁","救援规模[韩国锂电池火灾]: 165名救援人员、60台消防装备，动用无人破拆水炮车和消防机器人","受损面积[韩国起火仓库]: 仓库约700多平方米，234平方米受损，无人员伤亡"]},{"i":60234,"as":"近日国轩高科（安徽）销售有限公司成立，法定代表人陈炜，注册资本10亿元，位于合肥市包河区，经营范围含电池销售、电池零配件销售、新能源汽车生产测试设备销售等，由合肥国轩高科动力能源有限公司全资持股。业绩方面，上半年国轩高科营收277.76亿元，同比增长43.22%，创6年同期新高；归母净利润13.86亿元，同比增长278.05%。其中动力电池系统收入225.97亿元，同比增61.01%，占比提升至81.36%，毛利率14.02%；储能电池系统收入36.89亿元，同比下降19.14%，占比降至13.28%，毛利率19.50%。","scd":{"b":1.5,"i":6.0,"r":3.0,"d":6.0,"t":6.0},"kp":["注册资本[国轩高科安徽销售公司]: 10亿元人民币","上半年营收[国轩高科]: 277.76亿元，同比增长43.22%","归母净利润[国轩高科上半年]: 13.86亿元，同比增长278.05%","动力电池收入[国轩高科上半年]: 225.97亿元，同比增长61.01%，占比81.36%，毛利率14.02%","储能电池收入[国轩高科上半年]: 36.89亿元，同比下降19.14%，占比13.28%，毛利率19.50%"]},{"i":60235,"as":"内蒙古巴彦淖尔市乌拉特前旗两个储能项目开工，总投资15.84亿元，均以电网侧独立储能模式运行，以220kV线路送出至乌拉山500kV变电站220kV侧，年底前建成并网。其中汇锦储能20万kW/80万kWh独立储能电站示范项目总投资6.36亿元，占地约75亩，配套160个5MWh储能集装箱；乌拉特前旗500kV变电站300MW/1200MWh储能项目总投资约9.48亿元，占地约135亩，新建220kV升压站一座，每年充放电约320次。两个项目投资方均由多家能源企业共同组建成立。","scd":{"b":2.0,"i":6.0,"r":4.0,"d":7.0,"t":6.0},"kp":["项目一[内蒙古储能开工]: 汇锦储能20万kW/80万kWh独立新型储能电站，总投资6.36亿元，占地约75亩，配套160个5MWh储能集装箱","项目二[内蒙古储能开工]: 乌拉特前旗500kV变电站300MW/1200MWh储能项目","并网时间[内蒙古两储能项目]: 年底前建成并网，以220kV线路送出，电网侧独立储能模式运行","总投资[内蒙古两储能项目]: 15.84亿元"]},{"i":60236,"as":"海四达钠星年产6GWh钠离子电池生产基地项目位于四川内江经开区，总投资20亿元，聚焦大圆柱、超大方形钠电池电芯智能化产线建设，产品瞄准燃油和新能源汽车启停、大工业储能两大领域。根据最新建设进度，项目预计10月下旬投产。资料显示，海四达钠星是国内最早聚焦钠电池研发制造的公司之一，2025年钠电池出货量排名全球第2，坚守NFPP聚阴离子技术路线，持续攻坚高能量密度、长循环寿命等核心技术，产品已获部分头部客户认可。","scd":{"b":4.0,"i":8.0,"r":6.0,"d":7.0,"t":7.0},"kp":["项目总投资[钠离子电池生产基地]: 20亿元","产能[海四达钠星钠电池基地]: 6GWh/年","投产时间[内江钠电池基地]: 预计10月下旬","出货量排名[2025年钠电池全球]: 第2名","技术路线[海四达钠星]: NFPP聚阴离子路线"]},{"i":60237,"as":"美国主要汽车行业游说团体'汽车创新联盟'致信国会，敦促在年底前立法禁止中国汽车进入美国市场。尽管目前美国市场上没有一款中国品牌汽车在售，但该组织希望将这一现状通过法律形式永久化。联盟在信中声称中国汽车制造商在全球各地倾销受补贴的车辆。中国品牌汽车在全球其他市场销量持续增长，唯独在美国市场缺席，而该游说团体希望立法者尽快将中国联网汽车永久排除在美国市场之外。","scd":{"b":1.0,"i":2.0,"r":3.0,"d":3.0,"t":6.0},"kp":[]},{"i":60238,"as":"一辆量产版斯柯达Peaq 90七座电动SUV在一次充电后行驶了582英里（936公里），比其WLTP标称续航402英里（647公里）高出45%，即多出179英里（289公里）。此次成绩由两名厂家员工驾驶实现，采用二级公路行驶、干燥天气和精心计算的高效驾驶（hypermiling）策略完成。该车平均能耗为9.2千瓦时/100公里。这一成绩表明官方续航评级与实际可实现续航之间存在较大差异。","scd":{"b":2.0,"i":4.0,"r":3.0,"d":6.0,"t":5.0},"kp":["续航[Skoda Peaq一次充电/hypermiling]: 582英里","能耗[Škoda Peaq平均]: 9.2 kWh/100km","WLTP续航提升幅度[Skoda Peaq实测]: 超出45%"]},{"i":60239,"as":"比亚迪电动Kei车Racco在日本上市，售价约1.3万美元，早期试驾评价显示其空间宽敞、舒适，且非常适合日本道路。这是首款由海外车企从零开发的主流Kei乘用车。由于日本Kei车法规严格限制尺寸和功率输出，比亚迪无法凭借功率、科技和续航的传统打法取胜，转而通过空间布局和实用性竞争。Racco功率与日产Sakura相当但扭矩较小，续航最高可达199英里，而日产Sakura为112英里。","scd":{"b":3.0,"i":5.0,"r":4.0,"d":5.0,"t":5.0},"kp":["价格[BYD Racco kei EV]: 约13,000美元","续航[BYD Racco]: 最高199英里","对标续航[Nissan Sakura]: 112英里","开发属性[BYD kei车]: 首款海外车企从零开发的量产kei乘用车"]},{"i":60240,"as":"特斯拉无方向盘的Cybercab已在奥斯汀公共道路上开始载客运营。一段14分钟的车内视频显示行驶平稳安静，仅车载AI语音助手出现一次失误。这辆没有物理控制装置的车型提供了一次看似平常的乘车体验。不过，此次运营仅限于地理围栏范围内的奥斯汀区域，单次顺利载客证明不了该车辆在更复杂城市和恶劣条件下的表现能力。","scd":{"b":6.0,"i":6.0,"r":6.0,"d":4.0,"t":7.0},"kp":["配置[特斯拉Cybercab]: 无方向盘、无踏板","运行状态[奥斯汀公共道路]: 载客无人干预行驶","行程时长[演示视频]: 14分钟"]},{"i":60241,"as":"特斯拉已发布Cybercab双座EV的量产版本，首批生产车型在奥斯汀投入Robotaxi车队运营。这款两座车没有方向盘和踏板，同时也缺少传统制动系统——没有制动液，也没有连接车轮的制动管路。由于缺少方向盘和踏板等物理控制装置，其制动和转向控制方式需要重新设计。Cybercab是特斯拉产品组合中最小的乘用EV，在一场私下闭门活动中正式发布。","scd":{"b":6.0,"i":5.0,"r":6.0,"d":5.0,"t":7.0},"kp":["制动系统[特斯拉Cybercab]: 无制动管路和制动液","操控配置[Cybercab双座EV]: 无方向盘和踏板"]},{"i":60242,"as":"特斯拉Cybercab在德克萨斯州奥斯汀正式开始提供付费Robotaxi服务。这款金色双座EV没有踏板和方向盘，此前经历了一场未邀请传统媒体的闭门发布活动，主要参会者为特斯拉爱好者和内容创作者。值得注意的是，特斯拉CEO、纯视觉自动驾驶方案的坚定支持者埃隆·马斯克并未出席此次发布活动。整体发布活动被描述为造势充分但略显平淡。","scd":{"b":6.0,"i":7.0,"r":6.0,"d":5.0,"t":8.0},"kp":["运营状态[特斯拉Cybercab奥斯汀]: 提供付费机器人出租车服务","车辆配置[Cybercab]: 双座、无踏板无方向盘"]},{"i":60243,"as":"据研究机构New Automotive数据，8月英国纯电动汽车销量同比增长30%，占整个英国市场的30%，超过燃油、插混和混动车型，成为最畅销的动力系统类型。特斯拉是销量最高的EV品牌，今年迄今占英国市场8.8%份额，起亚和比亚迪分列第二、第三位。政府政策推动和油价上涨是销量增长的主要驱动因素。与美国因关税和补贴取消导致电动车市场受挫形成对比，全球其他地区EV销量持续强劲增长。","scd":{"b":1.0,"i":3.0,"r":3.0,"d":5.0,"t":6.0},"kp":["市场份额[英国EV月度销量]: 占整体市场30%","品牌份额[特斯拉英国EV]: 8.8%（今年至今）","品牌排名[英国EV]: 特斯拉第一，起亚第二，比亚迪第三"]},{"i":60244,"as":"据《商业内幕》报道，Slate电动皮卡的客户交付最早可能于12月开始，公司此前表示销售将于2026年底前启动。部分预购客户收到邮件通知，可提前获得交付。Slate起售价为2.64万美元（含目的地费）。新创车企将首发交付日期提前而非推迟较为罕见，因为汽车公司起步和大规模制造爬坡通常面临物流难题，近年多家车企都出现过新EV发布时间推迟的情况。","scd":{"b":2.0,"i":4.0,"r":4.0,"d":4.0,"t":6.0},"kp":["交付时间[Slate电动皮卡]: 最早12月开始","起售价[Slate]: 26,400美元（含目的地费）"]},{"i":60245,"as":"一项测试了50万辆电动汽车电池寿命的大型研究显示，现代电动车电池整体衰减程度低于人们此前的担忧，即使经过多年使用和多次充电仍保持良好状态，但不同车型的结果差异较大。特斯拉Model 3在该电池老化大型研究中表现位列较弱的一批，而Model Y的表现则更好。特斯拉在涵盖数十万英里真实行驶数据的研究中整体排名接近垫底位置。","scd":{"b":3.0,"i":3.0,"r":7.0,"d":6.0,"t":5.0},"kp":["研究样本[EV电池老化研究]: 约50万辆电动车","电池衰减表现[Tesla Model 3/近10万英里]: 排名靠后","电池衰减表现[Tesla Model Y]: 优于Model 3"]},{"i":60246,"as":"沃尔玛凭借数千家门店、庞大停车场和海量客流的天然优势，快速布局电动汽车快充网络。第二季度新增368个公共快充端口，数量仅次于特斯拉，位居全美第二；已开设第100座自营快充站，覆盖20个州。然而作者的首次新泽西州体验并不理想，在该公司公共快充站暴晒等待了40分钟，整体体验被形容为一场灾难。","scd":{"b":1.5,"i":3.0,"r":4.0,"d":3.0,"t":6.0},"kp":[]},{"i":60247,"as":"小米正式宣布2027年进入欧洲市场，包括德国，已有8家经销商集团签约加盟。小米过去两年证明了手机厂商造车的实力，其电动车速度快、有吸引力、科技配置丰富，在中国本土市场已累计销售超70万辆。随着中国品牌崛起，德国豪华品牌在华承压，如今竞争将延伸至其本土市场。","scd":{"b":3.0,"i":6.5,"r":5.0,"d":4.0,"t":7.5},"kp":["进入欧洲市场时间[小米汽车]: 2027年正式进入欧洲包括德国","经销商网络[小米欧洲入市]: 8家经销商集团已签约"]},{"i":60248,"as":"瑞浦兰钧在第二十六届中国专利奖评选中荣获国家级专利奖。获奖专利聚焦储能与动力电池领域，实现一体化结构电芯的可靠制造，显著降低电芯内阻、自放电率和短路风险，经行业协会鉴定整体技术达国际领先水平。该技术有效提升电芯安全性和能量密度，产品通过UL1973/IEC62619/UL9540A等国际标准认证，在国内外市场广泛推广应用。","scd":{"b":5.0,"i":7.0,"r":4.0,"d":5.0,"t":5.0},"kp":["获奖专利技术[瑞浦兰钧储能与动力电池]: 一体化结构电芯，显著降低内阻、自放电率和短路风险","技术水平[瑞浦兰钧一体化电芯专利]: 经行业协会鉴定达国际领先水平","认证标准[瑞浦兰钧电芯产品]: 通过UL1973/IEC62619/UL9540A国际标准认证"]},{"i":60249,"as":"8月27日盐城市大丰生态环境局受理天合储能年产12GWh储能电池项目重新报批的环评文件。此次并非新建项目，而是因建设实施阶段废气治理工艺、原辅料消耗变动重新报批，主体建设进度不变。项目位于大丰港经济开发区，占地约330亩，新增建筑面积约12万平方米，产品为磷酸铁锂储能电芯，一期规划4GWh，总产能12GWh，其中6GWh对外销售、6GWh内部自用。大丰基地已于2025年9月投产，叠加滁州基地后天合储能电芯规划总产能达25GWh。","scd":{"b":2.0,"i":7.0,"r":6.0,"d":7.0,"t":7.0},"kp":["总产能[天合储能盐城大丰储能电池项目]: 12GWh磷酸铁锂储能电芯","一期产能[天合储能大丰项目]: 4GWh电芯产线","产能分配[天合储能大丰项目]: 6GWh对外销售、6GWh内部自用","项目用地[天合储能大丰项目]: 约330亩","新增建筑面积[天合储能大丰项目]: 约12万平方米"]},{"i":60250,"as":"多家企业加快储能及钠电项目布局：鹏程无限宜宾48亿元储能电芯项目（总产能54GWh）进入设备安装调试阶段，一期预计2026年底投产，批量生产587Ah储能电芯；贵州焕文科技与永仁县签署1.5亿元储能集装箱项目协议；希倍动力2.5亿元高性能钠离子电池基地落户自贡，达产后年产0.5GWh，远期规划10GWh；超钠新能源在绵竹签约年产6GWh钠离子电池产线项目，此前已计划投资30亿元建设8万吨级正极材料基地。","scd":{"b":2.0,"i":6.0,"r":5.0,"d":6.0,"t":7.0},"kp":["总投资[鹏程无限宜宾储能电芯项目]: 48亿元","总产能[鹏程无限宜宾项目]: 54GWh分期建设","一期投产时间[鹏程无限宜宾项目]: 2026年底","产品规格[鹏程无限宜宾项目]: 587Ah储能电芯","投资额[焕文科技储能集装箱项目永仁]: 1.5亿元"]},{"i":60251,"as":"多家能源企业加大新能源布局：国家能源集团旗下两家公司相继成立——国能准源新能源开发（奇台）注册资本3.5亿元，海南龙源海控新能源注册资本2亿元（龙源电力持股95%）；国轩高科全资孙公司国轩高科（安徽）销售有限公司成立，注册资本10亿元；华电与隆基合资在内蒙古鄂尔多斯成立华电（鄂托克前旗）新能源公司，注册资本1000万元；中国中煤在江苏新设新能源企业。业务覆盖新能源开发、技术服务、储能及设备销售。","scd":{"b":1.0,"i":4.0,"r":4.0,"d":5.0,"t":6.0},"kp":["注册资本[国能准源新能源开发奇台公司]: 3.5亿元","注册资本[海南龙源海控新能源公司]: 2亿元","注册资本上限[新设新能源公司]: 最高达10亿元","龙源电力出资额[海南龙源海控合资公司]: 1.9亿元"]},{"i":60252,"as":"全球储能海外项目加速落地：富储科能AIO 261液冷储能柜在泰国工厂投运，高温下运行稳定；三晶电气罗马尼亚5.22MWh VPP项目投运，部署20台CM2一体化储能系统，为欧洲同级最大工商业储能项目之一；三一锂能为罗马尼亚175MWh储能项目提供交直流整体设备方案，实现从示范到百兆瓦级批量供货跨越；中国能建联营体签署摩洛哥米德尔特一期光储项目EPC合同，含约630MW光伏电站及1300MWh电化学储能，建成后为非洲单体规模最大光储项目。","scd":{"b":2.0,"i":7.0,"r":5.0,"d":6.0,"t":7.0},"kp":["储能容量[三晶电气罗马尼亚VPP项目]: 5.22MWh，部署20台CM2一体化储能系统","光伏规模[罗马尼亚光储项目]: 2.5MW光伏+储能","供货规模[三一锂能欧洲罗马尼亚项目]: 175MWh储能系统","产品[富储科能泰国项目]: AIO 261液冷储能柜投运"]},{"i":60253,"as":"OpenAI确认将开发人形机器人。CEO Sam Altman在播客中明确表示会做人形机器人及其他形态机器人。截至9月3日，OpenAI官网机器人团队列出21条招聘岗位，涉及执行器设计、固件、传感器、原型制造等，计划本体与模型一起做，并寻找制造伙伴。Altman认为近期重点是帮助熟练工人建设基础设施，与芯片、供应链共同降低数据中心建设成本。选择人形因多数环境和工具围绕人的身体设计，数据中心机器人可采用其他形态。他强调形态不是关键，更重要的是研发出让机器人工作的'大脑'。","scd":{"b":7.0,"i":3.0,"r":7.0,"d":4.0,"t":8.0},"kp":["开发方向[OpenAI机器人]: 人形机器人本体与模型一体开发","招聘岗位数[OpenAI Robotics团队]: 21条，涉及执行器设计、固件、传感器等","应用定位[OpenAI机器人近期]: 帮助熟练工人建设基础设施、降低数据中心建设成本"]},{"i":60254,"as":"麦格纳与小米就创新技术方案进行深度交流，重点涉及OptiForm™冲压一体式电池壳体技术。电池壳体需兼顾热管理、物理防护、耐腐蚀、轻量化和内部空间利用率，以提升PACK能量密度。同期报道还包括：小米发布首款智驾芯片玄戒D100及3nm工艺玄戒O3（240亿晶体管，十核全大核，多核跑分首破15000）；麦格纳2026年Q2销售额110亿美元，同比增长3%，调整后EBIT利润率升至6.2%，同比提升70个基点。","scd":{"b":4.0,"i":5.0,"r":5.0,"d":5.0,"t":7.0},"kp":["工艺制程[小米玄戒O3芯片]: 3nm","晶体管数[小米玄戒O3]: 240亿","芯片面积[小米玄戒O3]: 133mm²，较O1增加26%","CPU架构[小米玄戒O3]: 十核全大核（6超大核+4大核），超大核主频4.35GHz","多核跑分[小米玄戒O3]: 首破15000"]},{"i":60255,"as":"2026年7月中国新能源乘用车插混DHT系统装机量25万套，同比下降16.12%；双电控装机量24万，同比下降16.23%。DHT方面，采埃孚首次上榜，其eRE Plus四合一增程驱动系统搭载零跑D19，系统成本降低30%以上；赛克科技同比增长超500%。双电控方面，弗迪动力以39.5%份额领先，星驱科技12.1%第二，臻驱科技10.2%第三，前三家合计61.8%；伊控动力增长94.4%，联合电子增幅超500%。","scd":{"b":3.0,"i":6.5,"r":7.0,"d":8.0,"t":6.0},"kp":["DHT装机量[2026年7月中国插混乘用车]: 25万套，同比下降16.12%","双电控装机量[2026年7月中国新能源乘用车]: 24万，同比下降16.23%","成本降低[采埃孚eRE Plus四合一增程驱动系统]: 系统成本降低30%以上","市场份额[弗迪动力双电控]: 39.5%","市场份额[星驱科技双电控]: 12.1%"]},{"i":60256,"as":"NE时代与蓝星锂电联合走访测试仪器专业提供商善思创兴。公司核心团队拥有20年行业经验，整合人工智能、信息化、大数据、机器人、精密检测、高通量六大技术，产品覆盖智慧科研软件、科研机器人、智能硬件等五大类别。围绕电池研发制造，公司构建了覆盖'粉体—极片—电芯'的测试装备矩阵，在极片力学表征、电池膨胀监测、电解液浸润分析等方向布局测试仪器，方案已应用于锂电池、钠电池、固态电池体系的研发与质检，并展示了薄膜力学断层分析技术解决极片粘结剂分布检测难题。","scd":{"b":3.5,"i":6.0,"r":4.0,"d":4.0,"t":5.0},"kp":["核心技术[善思创兴]: 整合人工智能、信息化、大数据、机器人、精密检测、高通量六大技术","测试装备矩阵[电池研发制造]: 覆盖粉体—极片—电芯全环节","测试仪器应用[极片制造]: 覆盖锂电池、钠电池、固态电池等体系","团队经验[善思创兴核心团队]: 20年行业经验"]},{"i":60257,"as":"地平线征程智驾芯片量产突破1500万，累计赋能800万车主，与超40个品牌合作，中国前十大车企全部在列；从1000万到1500万仅用时12个月，年增速39%，累计获500款量产车型定点，在手定点超2000万套。重庆青山新一代大功率同轴电驱实现规模化量产，已搭载阿维塔、岚图等车型，获赛力斯新项目定点，单月需求突破2万台；产品采用行星排拓扑深度集成，源自GI-Drive 2.0平台（含293件发明专利及119项关键技术）。此外，兴瑞科技与臻驱科技签署战略合作协议。","scd":{"b":4.0,"i":8.5,"r":4.0,"d":6.5,"t":7.0},"kp":["累计量产[地平线征程智驾芯片]: 突破1500万套","量产增速[地平线征程芯片]: 从1000万到1500万仅用时12个月，年增速39%","量产车型定点[地平线累计]: 500款车型，中高阶智驾定点接近130款","在手定点总量[地平线]: 超2000万套","合作规模[地平线]: 累计赋能800万车主，与超40个品牌合作"]},{"i":60258,"as":"9月2日，欧阳明高院士工作站先进电池安全创新成果发布会在宜宾举行，赛科动力董事长朱高龙发布下一代高安全电池及全固态电池产业化成果。高安全电池围绕材料、界面、配方、电芯四位一体革新，已实现400Wh/kg超高比能电池量产交付，360Wh/kg产品循环寿命超1000次，-20℃~60℃全温域稳定运行并通过针刺测试；GWh自动化产线已持续生产，2027年完成3.5GWh二期扩建，产品应用于低空经济、机器人、高端电摩等领域。同时前瞻布局硫化物全固态电池。","scd":{"b":7.0,"i":6.5,"r":6.0,"d":5.0,"t":7.0},"kp":["技术路线[赛科动力]: 分层迭代，以高安全电池夯实当下，前瞻攻坚硫化物全固态电池","产业化进展[赛科动力固态电池]: 实现从实验室走向规模化量产的工程化突破"]},{"i":60259,"as":"9月1日工信部公示第一批国家新兴产业发展示范基地创建对象初步名单，亿航智能入选'低空装备'示范企业创建对象。低空装备领域共9家企业进入名单，亿航智能是唯一以载人eVTOL为核心产品的企业，也是唯一来自广东的企业。8月28日其发明专利获第二十六届中国专利优秀奖，同时入选2026年广东省制造业单项冠军企业名单。国家示范企业遴选围绕产品落地、技术攻坚、业态创新、运营管理效能等维度考评，旨在培育新兴产业标杆主体。","scd":{"b":3.0,"i":6.5,"r":4.5,"d":3.0,"t":7.0},"kp":["入选状态[亿航智能]: 首批国家新兴产业低空装备示范企业，为广东该领域唯一入选企业","核心产品[亿航智能]: 载人eVTOL，为低空装备公示名单中唯一载人eVTOL企业"]},{"i":60260,"as":"追梦空天科技完成数亿元A+轮融资，创成立以来最大单笔融资，也是国内混动eVTOL领域最大单笔融资，累计融资近8亿元。本轮由杭实集团及杭州低空公司领投，多家机构跟投，老股东航投基金连续第四轮跟投。资金将用于货运机型适航取证、量产能力建设、载人机型工程研制等。公司采取'先载货后载人'策略：DF600完成全流程试飞且型号合格证申请获受理；载人机型DF3000已完成混动模式首飞。2026年进入整机小批量交付阶段。","scd":{"b":3.0,"i":5.0,"r":4.0,"d":4.0,"t":6.5},"kp":["累计融资额[追梦空天科技]: 近8亿元","A+轮融资[追梦空天科技]: 数亿元，为国内混动eVTOL领域最大单笔融资","载货机型[DF600]: 已完成全流程试飞，型号合格证申请获民航局受理","技术路线[追梦空天科技]: 混动倾转构型，先载货后载人产品策略"]},{"i":60261,"as":"Flex宣布以44亿美元收购EPC Power，为其数据中心基础设施业务引入800V DC、构网型及其他功率变换技术，交易预计2026年第四季度完成。EPC Power开发面向数据中心、公用事业级储能和微电网的功率变换系统，产品包括构网型技术、数字整流器和DC-DC变换器，并有固态变压器路线图。EPC Power将并入Flex的云与电力基础设施部门，该部门计划于2027年第一季度分拆为独立上市公司。EPC Power平台旨在将800V DC负载更直接接入电网电压。","scd":{"b":3.0,"i":7.5,"r":6.5,"d":6.0,"t":8.0},"kp":["收购金额[Flex收购EPC Power]: 44亿美元","收购技术方向[EPC Power]: 800V DC、构网型等电力转换技术用于数据中心","交易时间[Flex收购EPC Power]: 预计2026年第四季度完成，EPC并入云与电力基础设施部门并于2027年第一季度分拆上市"]},{"i":60262,"as":"递归自我改进（RSI）指AI系统能以最少人工参与设计、编写和部署其后继系统。若实现，改进将随更聪明模型孕育更聪明世代而快速复合，加速程度可能超出人类理解和控制范围。对数据中心运营商而言，RSI将在电力、冷却、编排调度、治理和认证等层面产生深远影响。目前RSI尚无严格定义，但正接近现实，其实现依赖AI辅助编码的快速进步，如Anthropic在报告《When AI Builds Itself》中所述，其Claude模型已取得相关进展。","scd":{"b":5.0,"i":2.5,"r":5.5,"d":4.0,"t":5.0},"kp":["技术定义[RSI递归自我改进]: AI系统以最少人工介入设计、编码并部署后继模型"]},{"i":60263,"as":"全球AI基础设施建设竞赛是现代史上最大规模资本投资周期之一，科技公司在AI基础设施和新数据中心投入空前资金，超大规模园区涉及计算硬件、电力基础设施、冷却系统等巨额投资。然而在项目规划中，资产可靠性的一个重要方面——腐蚀问题却很少受到关注。行业注意力集中于电力供应、液冷、机架密度和部署速度等关键挑战，但这些焦点使腐蚀问题被忽视。","scd":{"b":4.5,"i":2.5,"r":6.0,"d":3.5,"t":4.5},"kp":[]},{"i":60264,"as":"","scd":null,"kp":[]},{"i":60265,"as":"","scd":null,"kp":[]},{"i":60266,"as":"","scd":null,"kp":[]},{"i":60267,"as":"","scd":null,"kp":[]},{"i":60268,"as":"呼吁保护青藏高原第三极地区免受矿产开采破坏，涉及生态保护政策。","scd":{"b":2.0,"i":2.0,"r":4.0,"d":3.0,"t":5.0},"kp":[]},{"i":60269,"as":"","scd":null,"kp":[]},{"i":60270,"as":"","scd":null,"kp":[]},{"i":60271,"as":"","scd":null,"kp":[]},{"i":60272,"as":"","scd":null,"kp":[]},{"i":60273,"as":"太阳能电池的光电转换效率存在固有损失，主要来源于三种机制：热化损失、透射损失和玻尔兹曼损失。针对腔结构有机太阳能电池中的玻尔兹曼损失问题，该研究提出通过抑制光子发射的策略来克服这一损失机制，从而提升太阳能电池的性能表现。","scd":{"b":8.0,"i":3.0,"r":7.0,"d":6.0,"t":5.0},"kp":["能量转换损失机制[太阳能电池]: 热化、透射、玻尔兹曼三大损失","技术策略[腔结构有机太阳能电池]: 抑制光子发射以克服玻尔兹曼损失"]},{"i":60274,"as":"该研究提出一套综合电压理论并结合参数敏感性调控方法，实现摩擦纳米发电机（TENG）持久的超高压输出。通过抑制V-Q曲线扁平化现象，显著提高了电荷利用效率，使器件在输出高电压的同时保持高效的电荷传输性能，为高性能摩擦纳米发电机设计提供了理论指导。","scd":{"b":7.5,"i":4.0,"r":6.0,"d":6.0,"t":5.0},"kp":["输出特性[摩擦纳米发电机]: 耐久超高压输出","电荷利用效率[抑制V-Q曲线扁平化]: 提升","技术方法[超高压摩擦纳米发电机]: 综合电压理论结合参数敏感性调控"]},{"i":60275,"as":"钙钛矿光伏器件的性能提升关键在于精确控制晶体取向，特别是(100)择优晶面的定向结晶。该研究引入一种基于π堆积的新型零维（0D）钙钛矿，诱导钙钛矿薄膜的定向结晶，实现高性能钙钛矿太阳能电池及组件的制备。","scd":{"b":7.0,"i":4.0,"r":6.0,"d":6.0,"t":5.0},"kp":["结晶取向控制[钙钛矿光伏]: 优选(100)晶面","技术手段[钙钛矿太阳能电池及组件]: 引入基于π堆积的零维(0D)钙钛矿诱导定向结晶"]},{"i":60276,"as":"该研究提出表面引发的RbF处理方法，在宽禁带（WBG）钙钛矿中形成体相Rb+梯度掺杂，可纯化钙钛矿并抑制卤化物相分离。基于该策略制备的钙钛矿/硅叠层太阳能电池效率达32.66%，并在1000小时测试后仍保持91%的性能，兼具高效率与高稳定性。","scd":{"b":7.5,"i":5.0,"r":6.5,"d":8.0,"t":6.0},"kp":["转换效率[钙钛矿/硅叠层电池]: 32.66%","效率保持率[1000小时后]: 91%","掺杂工艺[表面引发RbF处理]: 形成体相Rb+梯度，纯化宽带隙钙钛矿并抑制卤化物偏析"]},{"i":60277,"as":"二氧化钌（RuO2）是质子交换膜水电解（PEMWE）中常用的阳极材料，但由于过强的键合作用，其催化活性与稳定性之间存在权衡问题。该研究通过调控Ru-O共价性引发机制转变，实现兼具快速响应性能的质子交换膜水电解。","scd":{"b":7.5,"i":4.0,"r":6.0,"d":6.0,"t":5.0},"kp":["催化剂[PEM水电解阳极]: RuO2","关键问题[RuO2阳极]: 活性与稳定性之间存在权衡"]},{"i":60278,"as":"电化学氧化还原活性卤化物（eREAL）材料是一类新兴功能材料，同时具备高锂离子导电性和过渡金属氧化还原活性，因此被视为正极或正极电解质（catholyte）应用的有力候选材料，为新一代锂电池正极设计提供了新方向。","scd":{"b":7.5,"i":3.0,"r":6.5,"d":6.0,"t":5.0},"kp":["正极材料[eREAL卤化物]: 兼具高锂离子电导率与过渡金属氧化还原活性"]},{"i":60279,"as":"该研究报道了Pd掺杂晶界工程化RuO2（Pd–GB–RuO2）电催化剂，通过pH自适应的中间体溢流机制实现高效析氢反应（HER）。中间体在活性位点的竞争吸附使中间体传输可随环境自适应，使催化剂在酸性和碱性电解液中均能维持高效的氢气析出性能，揭示了pH对析氢反应的影响机制。","scd":{"b":7.5,"i":3.5,"r":6.0,"d":6.0,"t":5.0},"kp":["催化剂[析氢反应]: Pd掺杂晶界工程化RuO2 (Pd–GB–RuO2)","性能特点[Pd–GB–RuO2]: pH自适应中间体溢流，在酸性和碱性电解液中均保持高效HER"]},{"i":60280,"as":"","scd":null,"kp":[]},{"i":60281,"as":"该研究将阴离子捕获型层状双氢氧化物（LDH）引入聚环氧乙烷基复合固态聚合物电解质（CSPE），调控Li+传输并稳定锂/电解质界面。增强型电解质与锂电极配对实现超950小时的循环稳定性，LiFePO4||Li全电池250次循环后容量保持率达90.1%。研究还利用原位纳米聚焦广角X射线散射（WAXS）首次 mapping 了固态界面上SEI及锂枝晶的空间分布演化。","scd":{"b":7.0,"i":4.0,"r":7.0,"d":7.0,"t":5.0},"kp":["电解质[复合固态聚合物电解质]: PEO基引入阴离子捕获层状双氢氧化物(LDH)，调控Li+传输并稳定锂/电解质界面","表征技术[固态界面SEI演化与锂沉积]: 操作纳米聚焦广角X射线散射(Operando Nano-focus WAXS)"]},{"i":60282,"as":"重新审视电池安全问题，指出可燃性仅是电池安全考量的一个方面，需更全面评估。","scd":{"b":4.0,"i":3.0,"r":5.0,"d":3.0,"t":4.0},"kp":["安全性结论[电池安全评估]: 可燃性仅是安全考量之一，需更全面评估"]},{"i":60283,"as":"研究人员演示了一种揭示单次核衰变留下的电学'指纹'的新方法。当植入材料表面附近的放射性原子衰变时，其产物会从周围材料中激发出大量次级电子，这些电子常被常规仪器漏检，却会对精确电子计数实验造成显著背景。研究利用激光悬浮的玻璃微球作为具有亚电子电荷灵敏度的孤立电荷探测器，并与闪烁体探测器配合，通过时间匹配分析衰变引起的电荷变化。","scd":{"b":8.0,"i":2.0,"r":7.0,"d":6.0,"t":5.0},"kp":["放射性衰变电荷变化检测[悬浮微粒中单次核衰变]: 衰变产物从周围材料喷射出二次电子簇，可对精密电子计数实验形成显著本底"]},{"i":60284,"as":"该研究展示了应变梯度工程为微加工金刚石提供了一条无掺杂的光学发射调控途径。通过在金刚石纳米带中构建应变梯度，结合声子辅助过程实现宽带光发射的调制，为金刚石光电器件的设计提供了新方法。成果发表于《物理评论快报》。","scd":{"b":8.0,"i":2.0,"r":6.0,"d":5.0,"t":7.0},"kp":["宽带光发射调制[应变梯度工程化金刚石纳米带]: 无需掺杂即可实现宽带光发射调制"]},{"i":60285,"as":"激光尾场加速器是明亮的紧凑型类同步辐射X射线源。研究团队使用110 TW激光在长度可调的气体池中驱动尾场，绘制电子束演化及相应X射线发射的完整图像。研究发现，利用初始聚焦使激光脉冲在超过其耗尽长度的位置注入，可获得高通量X射线发射。成果发表于《物理评论快报》。","scd":{"b":6.5,"i":4.0,"r":6.0,"d":7.0,"t":7.0},"kp":["激光功率[激光尾场加速器驱动]: 110 TW","X射线发射[超越耗尽长度注入的高通量]: 类同步辐射X射线高通量发射"]},{"i":60286,"as":"该研究基于囚禁离子系统实现完全相位控制的双光子纠缠态制备。囚禁离子内部态的高度可控性使其成为产生单光子和双光子态的理想系统，将单离子与光学腔耦合，可实现单光子高效发射到单一空间模式，并对光子的时间形状、相位和频率进行精确控制。成果发表于《物理评论快报》。","scd":{"b":7.5,"i":3.0,"r":6.5,"d":5.0,"t":7.0},"kp":["双光子纠缠态[单离子耦合光学腔]: 可实现完全相位控制，并可控光子的时间形状、相位和频率"]},{"i":60287,"as":"","scd":null,"kp":[]},{"i":60288,"as":"","scd":null,"kp":[]},{"i":60289,"as":"","scd":null,"kp":[]},{"i":60290,"as":"","scd":null,"kp":[]},{"i":60291,"as":"该研究通过直接光谱学探测手段研究了EuO在压力诱导相变过程中4f电子态的行为，结果显示相变前后光谱未发生变化，证实了Eu价态在高压相变中保持稳定，该结论与DFT计算结果相符。成果发表于《物理评论快报》。","scd":{"b":6.0,"i":2.0,"r":6.0,"d":5.0,"t":7.0},"kp":["Eu价态[加压EuO跨压致相变]: 直接光谱探测显示4f态无光谱变化，Eu价态保持稳定，与DFT计算一致"]},{"i":60292,"as":"通过氢氧化物表面工程加速层状双钙钛矿析氧动力学，应用于阴离子交换膜水电解制氢。","scd":{"b":6.5,"i":3.0,"r":4.0,"d":3.5,"t":6.0},"kp":["析氧动力学加速[层状双钙钛矿经氢氧化物表面工程]: 应用于阴离子交换膜水电解制氢"]},{"i":60293,"as":"该研究报道了稀土元素钆工程化的Gd-Cu2O催化剂，可构建富自由水的界面环境，促进质子转移并稳定电化学CO2还原过程中的关键C-C耦合中间体。界面水与催化剂结构的协同效应驱动反应路径向高选择性乙醇生成方向进行，实现了高速率、高选择性的CO2到乙醇转化。","scd":{"b":7.0,"i":3.5,"r":6.0,"d":6.0,"t":6.5},"kp":["催化剂[掺钆Cu2O]: 形成富自由水界面环境，促进质子转移并稳定C-C耦合中间体","CO2还原产物选择性[界面水动力学调控]: 高选择性生成乙醇"]},{"i":60294,"as":"研究托卡马克等离子体中低Z杂质共存对高Z杂质钨新经典粒子输运的影响。低Z杂质可减弱或增强钨的新经典输运，当低Z杂质含量足够大时，钨的输运特性会发生改变，现有杂质新经典输运理论所预测的钨输运对主体离子径向梯度的依赖关系将被打破。当主体离子径向梯度小于临界值时，现有理论会高估钨的新经典粒子输运；大于临界值时则会低估。低Z杂质通过（正文截断）机制影响高Z杂质的新经典输运。","scd":{"b":6.0,"i":2.0,"r":4.0,"d":5.0,"t":4.0},"kp":["钨新经典粒子输运[托卡马克等离子体中低Z杂质共存]: 低Z杂质可减弱或增强钨输运；含量足够大时改变钨输运特性"]},{"i":60295,"as":"针对无人机叶片升力实时监测中传统电调估算方法精度有限、硬件成本高、易受信号漂移影响的问题，提出基于非接触摩擦纳米发电机（BL-TENG）的自供电实时旋翼升力监测传感器。结合计算流体动力学仿真与结构优化设计，实现了升力的原位监测。引入天然兔毛作为主动电荷泵，使电输出提升2.6倍，同时通过非接触方式最大限度减少了材料磨损和机械阻力，为无人机飞行稳定性与安全监测提供低成本自供电方案。","scd":{"b":5.0,"i":4.0,"r":4.0,"d":6.0,"t":4.0},"kp":["传感器[基于非接触摩擦电纳米发电机BL-TENG]: 自供电、实时无人机旋翼升力监测，克服传统电调估算精度有限、硬件成本高、信号漂移问题"]},{"i":60296,"as":"研究以不同比例奥曲肽（生长抑素受体SSTRs强效激动剂）和乱序肽共价功能化的介孔二氧化硅纳米粒子，在总肽负载恒定条件下与SSTR2的相互作用随受体表达水平的变化。奥曲肽表面浓度升高和受体表达水平升高均导致配体-受体总相互作用增强。在中等奥曲肽表面浓度下，低表达与高表达细胞间的传感器响应差异（选择性）最高。但随受体水平升高，粒子内吞动力学下降，导致（正文截断）时选择性降低。","scd":{"b":5.0,"i":3.0,"r":4.0,"d":6.0,"t":4.0},"kp":["配体-受体相互作用[介孔硅纳米粒子上奥曲肽功能化密度与SSTR2表达水平]: 配体表面浓度和受体表达水平增加均提高总相互作用"]},{"i":60297,"as":"基于2000至2024年33个国家的平衡面板数据、多维专利价值指标及基于恐怖主义冲击的工具变量策略，研究国家特定地缘政治风险（GPR）对绿色氢创新的影响。结果显示：国家特定GPR与更高的绿氢专利价值显著相关，且对专利价值的市场维度影响最强；该响应覆盖全部四种氢生产路径，但在碳市场采用条件下分析发现，无碳定价时任何路径均无响应，而有碳定价时响应几乎完全集中于绿色氢。","scd":{"b":4.0,"i":2.0,"r":5.0,"d":6.0,"t":4.0},"kp":["研究样本[绿色氢创新与地缘政治风险]: 33国2000-2024平衡面板数据","核心结论[国家特定GPR对绿色氢专利价值]: 地缘政治风险显著提升绿色氢专利价值"]},{"i":60298,"as":"关于风能和太阳能光伏边际削减高效投资研究论文的勘误声明。","scd":{"b":1.0,"i":1.0,"r":2.0,"d":2.0,"t":2.0},"kp":[]},{"i":60299,"as":"研究分布式太阳能光伏在巴西的发展，探讨去中心化能源技术创新与模仿的驱动因素。","scd":{"b":3.0,"i":2.0,"r":3.0,"d":3.0,"t":3.0},"kp":[]},{"i":60300,"as":"随着传统硅基DRAM接近物理和电学微缩极限，氧化物半导体因低关态电流和工艺兼容性成为下一代存储器件的候选沟道材料。其中氧化铟镓（IGO）薄膜晶体管在DRAM相关应用中备受关注，但器件叠层须承受后道工艺（BEOL）的高热预算，包括600°C氮气气氛退火，该条件会加剧氧化物层的缺氧状态。该工作系统研究了钝化层选择对IGO TFT电学性能和热稳定性的影响（正文截断），评估其器件级热鲁棒性。","scd":{"b":5.0,"i":3.0,"r":4.0,"d":6.0,"t":4.0},"kp":["退火温度[氧化铟镓薄膜晶体管DRAM应用]: 600 °C氮气退火","通道材料[下一代DRAM存储器件]: 铟镓氧化物(IGO)薄膜晶体管","器件优势[氧化物半导体DRAM应用]: 低关态电流与工艺兼容性"]},{"i":60301,"as":"分析全球天然气市场主导权及美国与欧洲之间的地缘政治与价格传导关系。","scd":{"b":2.0,"i":2.0,"r":4.0,"d":3.0,"t":3.0},"kp":[]},{"i":60302,"as":"电沉积宽禁带钙钛矿太阳能电池适合低成本制备，但此前多限于全无机组成，效率通常低于8%，受限于结晶质量不足和严重界面复合。该工作将电沉积扩展至有机-无机杂化宽禁带钙钛矿，并提出简单的乙酸铯（CsAc）界面钝化策略。冠军器件效率达14.57%，较对照的12.04%显著提升，填充因子、开路电压和短路电流密度同步改善。CsAc钝化器件保持初始效率的83%（后续数据截断），展现了良好的稳定性。","scd":{"b":6.0,"i":4.0,"r":5.0,"d":7.0,"t":5.0},"kp":["转换效率[电沉积全无机宽带钙钛矿太阳能电池]: 通常低于8%","钝化策略[电沉积有机-无机杂化宽带钙钛矿]: 乙酸铯(CsAc)界面钝化","制备方式[宽带钙钛矿太阳能电池]: 低成本电沉积"]},{"i":60303,"as":"层状钙钛矿氧化物具有出色的结构可调性，是设计精细调控电子和磁性材料的理想平台。该研究采用简单、高度可控的蒸汽调制策略，在Ruddlesden-Popper层状钙钛矿氧化物中直接探测并触发深刻的结构与磁性转变。对La0.25Sr2.75Fe0.8Co1.2O7-δ在100°C下进行短暂蒸汽处理，即可诱导磁敏感性提升1257%，并实现可逆的（后续内容截断）磁性调控，建立了晶格束缚水物种与实空间结构重构及可逆磁调控的直接关联。","scd":{"b":7.0,"i":2.0,"r":6.0,"d":6.0,"t":4.0},"kp":["调控手段[层状钙钛矿氧化物磁性调控]: 蒸汽调制实现可逆磁性调控"]},{"i":60304,"as":"","scd":null,"kp":[]},{"i":60305,"as":"","scd":null,"kp":[]},{"i":60306,"as":"对比研究土耳其与韩国自1958年以来的原子能计划，分析产业政策、技术学习与本土化策略。","scd":{"b":3.0,"i":4.0,"r":6.0,"d":4.0,"t":4.0},"kp":[]},{"i":60307,"as":"研究教育对中国高海拔地区家庭能源扶贫的影响机制与政策启示。","scd":{"b":2.0,"i":2.0,"r":5.0,"d":3.0,"t":4.0},"kp":[]},{"i":60308,"as":"","scd":null,"kp":[]},{"i":60309,"as":"","scd":null,"kp":[]},{"i":60310,"as":"假设海马体中解决记忆竞争的计算机制也塑造感觉表征的精度以引导选择性注意。利用基于fMRI的模式相似性、感受野建模和眼动追踪，在执行记忆依赖视觉搜索任务的人类被试中检验该假设。结果显示：海马中竞争记忆的表征越分化，记忆引导的眼动准确性越高；视觉皮层中，搜索成功前出现对 remembered 目标位置的预备性编码，而搜索失败前出现对竞争位置的预备性编码，导致干扰（正文截断）。揭示了记忆与知觉中竞争解决的共同海马机制。","scd":{"b":6.5,"i":2.0,"r":5.0,"d":5.0,"t":4.0},"kp":[]},{"i":60311,"as":"碳酸盐与硅酸盐的相互作用在工业和行星过程中发挥核心作用，但现有认识主要限于硅酸盐-碳酸盐交换机制，同时含碳酸盐和硅酸盐单元的高压化合物长期被预期存在。该研究在122(2) GPa和2800(200) K条件下合成了高压硅酸盐-二正碳酸盐CaSiC2O7。其结构基于共顶点连接的SiO6八面体和CO4四面体框架。第一性原理计算与实验结果一致，表明该相在宽压力范围内具有动力学和力学稳定性。这一发现揭示了富碳酸盐深部地幔环境中碳酸盐-硅酸盐相互作用的额外途径。","scd":{"b":9.0,"i":2.0,"r":8.0,"d":8.0,"t":7.0},"kp":["合成压强[高压硅酸盐-焦碳酸钙合成]: 122(2) GPa","合成温度[高压硅酸盐-焦碳酸钙合成]: 2800(200) K","新化合物[深地幔硅酸盐-碳酸盐化学]: CaSiC2O7，由共顶SiO6八面体与CO4四面体构成骨架"]},{"i":60312,"as":"气候变化下陆地碳吸收受氮可用性显著限制，植物可通过灵活的叶片氮分配缓解这一限制，但其全球格局尚不清楚。通过分析涵盖98科520种种子植物的全球数据集，发现植物平均将38.7%的叶片氮分配给光合组分（包括Rubisco、生物能量学和光捕获机制），13.1%分配给细胞壁。叶片氮分配呈现明显的进化转变：早期分化植物优先将氮投入细胞壁，而近期演化物种将更多氮分配给光合作用。该格局受进化历史根本性约束，并进一步受近期（正文截断）环境塑造。","scd":{"b":6.0,"i":2.0,"r":7.0,"d":8.0,"t":5.0},"kp":[]},{"i":60313,"as":"泥炭地是最大的陆地有机碳储存库，但排水已使其成为CO2的重要排放源。虽然水位被广泛认为是泥炭地CO2排放的首要控制因子，但未来有效管理需理解其与气候变暖下温度升高的交互作用。利用温带和北方泥炭地276个站点年的年度CO2通量观测，采用可解释机器学习解析年尺度上地下水位深度与温度对生态系统CO2交换的联合效应。在涵盖自然沼泽、农田、草地和开采地等多样土地覆盖的泥炭地中，CO2排放对地下水位深度呈非线性响应，当水位（正文截断）时排放下降。","scd":{"b":6.0,"i":3.0,"r":7.0,"d":8.0,"t":5.0},"kp":[]},{"i":60314,"as":"北方森林的物候变化改变陆-气能量交换，但年均值掩盖了这一反馈在幅度和途径上的显著季节差异。研究表明，气候驱动的物候波动产生系统性变暖不对称：叶面积损失引起的地表变暖超过等量叶面积增加带来的冷却。生长季内，随着蒸腾接近生理极限，额外叶片产生的冷却效益递减，限制了潜热通量；休眠季内，冠层-积雪反照率差异使短波辐射占主导，由于该辐射扰动向地表温度的转化高度非线性，叶片损失产生的净变暖仍超过等量叶片增加（正文截断）的冷却效应。","scd":{"b":6.0,"i":2.0,"r":6.0,"d":7.0,"t":5.0},"kp":[]},{"i":60315,"as":"1-20公里尺度的海洋亚中尺度锋面在表层混合层内已被广泛记录，但对其在混合层以下的存在知之甚少。分析2014至2020年南大洋印度洋扇区装备仪器的南象海豹133598次潜水记录（亚公里分辨率），发现亚中尺度运动在混合层以下增强，从表层到至少500米深度全年存在。其呈季节性循环：南半球春季（9-11月）增强，秋季（3-5月）减弱。这些深层亚中尺度遵循高度计得出的表层涡动能季节性，表明其由中尺度涡产生。","scd":{"b":6.5,"i":2.0,"r":7.0,"d":8.0,"t":5.0},"kp":[]},{"i":60316,"as":"集约农业通过有害藻华、缺氧和代价高昂的状态转变驱动湖泊富营养化，损害水质和生物多样性，但农业是通过扩张触发突变还是长期土地覆盖下累积脆弱性尚不清楚。该研究结合全球859个湖泊的营养状态和近岸土地覆盖数据，检测出2003至2022年间125次突变的持续性倾倒事件，并利用可解释模型区分长期农业暴露与快速扩张的影响。近期倾倒风险主要由湖泊基线营养状态及其周边长期农田决定，基线之上的小幅升高即会提高12个月的倾倒（正文截断）风险。","scd":{"b":6.0,"i":2.0,"r":7.0,"d":8.0,"t":5.0},"kp":[]},{"i":60317,"as":"电催化脱卤可通过断裂C-Cl键有效解毒废水中的氯化有机污染物（COPs），但常难以实现完全矿化，尤其释放的Cl-去向常被忽视，其能否被循环再利用促进污染物降解尚不明确。该研究构建了还原-氧化级联系统：电催化还原过程中释放的Cl-在后续氧化步骤中直接转化为活性氯物种（RCS），实现有机污染物的完全矿化。淬灭实验和电子顺磁共振（EPR）证实了脱离Cl-的原位再利用，激光扫描共聚焦（正文截断）提供了进一步证据。","scd":{"b":7.0,"i":3.0,"r":6.0,"d":7.0,"t":5.0},"kp":[]},{"i":60318,"as":"双环[1.1.0]丁烷（BCBs）的张力释放反应是构建复杂碳环骨架的强大合成策略。该研究报道通过可见光介导的双张力释放模式实现BCBs与瞬态环己炔的直接反应。利用光化学过氧化物前体，该无催化剂方法避免了环己炔生成中通常需要的有害副产物和超化学计量的氟源。该方法可 streamlined 合成含全碳季碳中心的跳过的二烯（传统方法难以获得），并以其优异的官能团容忍性、可扩展性及成功扩展（正文截断）体现了反应的多功能性。","scd":{"b":7.0,"i":2.0,"r":6.0,"d":6.0,"t":5.0},"kp":[]},{"i":60319,"as":"研究团队利用新开发的脉冲焦耳加热平台结合第一性原理模拟，探索膨胀型温稠密铝物质。采用基本不依赖模型的方法和 时间分辨诊断，测量了从常密度降至0.6 g/cm³、温度超过37 kK条件下的热力学和输运性质，为电导率和状态方程模型提供了基准数据。结果揭示了与金属-非金属转变起始相关的电子态局域化现象，为这一缺乏实验约束的中间态物质（介于凝聚态物质与低密度高能量密度等离子体之间）的输运性质研究提供了关键数据。","scd":{"b":8.0,"i":3.0,"r":7.0,"d":7.0,"t":5.0},"kp":["实验平台[膨胀热致密铝电子传输研究]: 脉冲焦耳加热平台结合第一性原理模拟","研究状态[膨胀热致密物质]: 金属-非金属转变区传输性质实验约束不足"]},{"i":60320,"as":"烷烃氢膦酰化是合成烷基膦酸酯的重要工具，其产物广泛应用于医药、农药和材料科学，但实现未活化烯烃的马尔可夫尼科夫选择性仍具挑战。研究团队开发了一类具有独特N-O-P键联结构的亚磷酸邻苯二甲酰亚胺酯（二烷基邻苯二甲酰亚胺基亚磷酸酯）作为高效自由基捕获试剂。以二苯基硅烷为氢供体，钴催化未活化烯烃在室温下顺利进行反应，专一性地生成马尔可夫尼科夫氢膦酰化产物。","scd":{"b":6.5,"i":2.0,"r":6.0,"d":6.0,"t":5.0},"kp":[]},{"i":60321,"as":"镁金属热力学性质优良，是可充电镁金属电池负极的理想材料，但不稳定电极/电解质界面处的寄生副反应和不可控沉积严重阻碍可逆电沉积。研究通过循环多向变形在高密度下引入孪晶缺陷，显著提高扩散速率并同时抑制界面反应。形貌表征结合理论计算表明，孪生镁负极动力学显著增强，无量纲电化学达姆科勒数降低，表明镁沉积受扩散限制的程度减小。","scd":{"b":7.5,"i":4.0,"r":7.0,"d":7.0,"t":6.0},"kp":["镁金属负极[可逆镁电沉积]: 通过循环多向变形引入高密度孪生缺陷，显著提高扩散速率并抑制界面反应"]},{"i":60322,"as":"研究展示了一种双轴FMCW激光雷达系统，在分立光路上单片集成光学相控阵（OPA）发射器和相干焦平面阵列（FPA）接收器，集成超过4500个功能组件，无需环形器。线状光束实现敏捷转向，透镜辅助FPA提供大接收孔径和并行单波长读出。该设计克服了现有集成激光雷达在光功率、孔径和采集速度之间的权衡，可用于自主系统、机器人和工业监测的三维感知，光学测量距离与速度。","scd":{"b":7.5,"i":4.0,"r":7.0,"d":7.0,"t":6.0},"kp":[]},{"i":60323,"as":"绿色甲醇有助于交通和工业脱碳，但其生产路线因生物质转化、可再生氢供应及电力排放与成本紧密耦合而不确定。研究基于中试规模气化数据和工业过程参数，比较了四种基于生物质和可再生电力的甲醇路线在技术性能、生命周期温室气体排放和生产成本上的差异，并识别了部署相关的边界条件。气化耦合可再生氢路线实现92%碳利用率和54%能源效率；直接燃烧后二氧化碳加氢将碳利用率提升至96%，但需更多电解氢。","scd":{"b":5.0,"i":5.0,"r":6.5,"d":8.0,"t":5.0},"kp":["绿色甲醇合成路线[生物质与可再生电力耦合]: 基于中试气化数据与工业过程参数比较四条技术路线的性能、生命周期温室气体排放与生产成本"]},{"i":60324,"as":"在纳米尺度实现最大圆二色性是手性光子学的终极目标，但常规手性材料和各向异性晶体难以实现。研究证明扭曲双曲范德华同质结构中的巨型圆二色性源于微观的线性二色性-线性双折射（LD-LB）干涉，而非本征几何手性。通过建立严格的层间LD-LB耦合框架，预测扭曲MoOCl2同质结构仅在220层（扭曲角度下）即可实现最大圆二色性，为原子级手性光-物质相互作用调控提供了新策略。","scd":{"b":8.0,"i":3.0,"r":7.0,"d":6.0,"t":5.0},"kp":["圆二色性[扭曲双曲范德华同质结构]: 实现纳米尺度最大/巨型圆二色性"]},{"i":60325,"as":"相对介电常数（εr）、品质因数（Q×f）和谐振频率温度系数（τf）是微波介质材料的关键参数，常规调谐策略依赖阳离子-氧八面体几何修饰，但外元素掺杂或固溶体方法缩小了可设计组分空间。研究引入构型熵作为结构指标，同时调控中心阳离子位移、八面体畸变和M-O键共价性，实现微波性能的协同改善。结果显示阳离子位移和八面体结构可被协同调控，从而突破传统方法的性能调节局限。","scd":{"b":6.0,"i":4.0,"r":6.0,"d":6.0,"t":5.0},"kp":["微波介电陶瓷[熵工程调控]: 通过熵工程突破掺杂与固溶设计的组分空间限制，协同调控相对介电常数、品质因数与谐振频率温度系数"]},{"i":60326,"as":"PbTe是优异的中温区热电材料，但商业应用受限于n型性能较低。研究通过溶质诱导晶格软化调控Peierls-Nabarro应力，产生高密度螺旋位错、位错环和亚晶界以阻挡热输运声子；同时Sb与TeO2的置换反应原位生成Sb6O13纳米包裹物，进一步抑制热传输，在773 K下实现约0.21 W m⁻¹ K⁻¹的超低晶格热导率。此外，Sb掺杂提高电子态密度，改善功率因子，实现n型PbTe的卓越热电性能。","scd":{"b":7.0,"i":4.0,"r":6.0,"d":7.0,"t":5.0},"kp":["n型PbTe热电性能[Peierls-Nabarro应力调控]: 通过溶质诱导晶格软化产生高密度螺旋位错、位错环和亚晶界阻塞传热声子"]},{"i":60327,"as":"氢沿碳骨架迁移在有机合成和烃类催化的异构化与重排反应中起关键作用。研究利用扫描隧道显微镜的单分子方法，在Cu(110)表面构建的双稳态CHCH2物种中实现了氢迁移的精确控制。热触发或电子触发的氢迁移表观活化能约0.2 eV，显著低于经典类似物的1.3 eV。氘代CDCD2物种中未观察到相应迁移，揭示主导的量子效应。深度学习辅助的路径积分蒙特卡洛模拟证实了表面辅助隧穿路径的存在。","scd":{"b":8.0,"i":2.0,"r":7.0,"d":6.0,"t":5.0},"kp":["氢转移活化能[CHCH2物种/Cu(110)表面]: ≈0.2 eV"]},{"i":60328,"as":"电晕放电检测对高压输电安全运行至关重要，但现有日盲紫外探测器灵敏度不足、稳定性差、抗干扰能力弱。研究通过低成本溶液刮涂技术制备了高灵敏度自适应有机神经形态日盲紫外传感器。器件可实现低至60 nW cm⁻²的超弱检测，关键指标包括光灵敏度1.1×10⁷、光响应度4.6×10⁷ A W⁻¹、探测率2.9×10¹⁸ Jones和外量子效率2.2×10⁸%，均超越现有先进日盲探测器。传感器具有强光谱选择性，光响应时间25 ms，稳定性良好。","scd":{"b":6.0,"i":4.0,"r":6.0,"d":7.0,"t":5.0},"kp":["探测灵敏度[有机神经形态日盲紫外传感器]: 检测下限低至60 nW cm−2"]},{"i":60329,"as":"多螺旋烯的催化不对称合成因螺旋骨架的精确构建和立体选择性控制而成为有机合成最具挑战性的难题之一。虽有S型双螺旋烯对映控制合成的零星报道，E型双螺旋烯的催化不对称合成此前尚未实现。研究报道了多环酚与2-炔基苯酚的有机催化分子间环加成反应，能够高效组装E型双螺旋烯类似物并具有优异的立体控制。位阻效应使反应偏离传统Friedel-Crafts路径，是实现立体选择性的关键。","scd":{"b":7.0,"i":2.0,"r":6.0,"d":5.0,"t":5.0},"kp":["E型双螺旋烯合成[有机催化分子间环加成]: 首次实现催化不对称立体选择性合成"]},{"i":60330,"as":"柔性电介质材料存在固有的极化-击穿权衡问题。研究提出氢键调制分子堆叠策略以改善高温电容储能性能，合成了一系列氢键供体和受体可调的聚醚酰亚胺共聚物。高极化羟基基团提高介电常数并增加氢键供体密度；构建的氢键网络增强分子间相互作用、热稳定性和击穿强度；大体积三氟甲基取代基扩大链间距并抑制链间电荷传输。最优分子堆叠的共聚物实现7.34 J/cm³的最大放电能量密度，效率超过（文中所述阈值）。","scd":{"b":7.0,"i":4.0,"r":6.0,"d":7.0,"t":5.0},"kp":["柔性电介质[氢键调制分子堆叠]: 高极性羟基提升介电常数并增加氢键给体密度，构建氢键网络增强分子间相互作用，克服极化-击穿权衡"]},{"i":60331,"as":"近红外自旋发光二极管可产生圆偏振光，在生物医学等领域有应用前景，但其最长发射波长此前限于782 nm，超过800 nm的自旋极化电致发光极具挑战。研究基于混合维度锡基钙钛矿异质结构，引入手性R/S-α-甲基苄基铵间隔阳离子。R/S-MBA⁺诱导的低维相提供手性光学活性，三维FA0.9Cs0.1SnI3结构域作为近红外发射中心。受控结晶产生柏树叶状形貌，促进载流子限制并改善电荷注入平衡，实现发射峰超过900 nm的高性能近红外圆偏振电致发光。","scd":{"b":7.0,"i":3.0,"r":6.0,"d":6.0,"t":5.0},"kp":["近红外圆偏振电致发光[混合维度锡基钙钛矿异质结构/手性MBA+间隔阳离子]: 发射峰超过900 nm，突破782 nm报道极限"]},{"i":60332,"as":"定制光形控制电子运动可实现对物质的前所未有操控，但标准手性光几乎无法影响化学反应的手性。研究通过将光的Lissajous图形扭曲成三维手性结构，可选择性激发分子对映体之一而非其镜像，实现直接不对称光化学，达到前所未有的对映选择性水平。从头算模拟显示手性部分电子激发中约30%的对映选择性，实验实现对映选择性增强1000倍，为控制化学反应手性开辟了新途径。","scd":{"b":9.0,"i":2.0,"r":8.0,"d":6.0,"t":6.0},"kp":["对映选择性增强[三维 shaping 光化学/扭曲光 Lissajous 图形]: 1000 倍"]},{"i":60333,"as":"单分子荧光技术通过解析系综测量无法获得的分子异质性和瞬态态，革新了生物分子动力学研究，但常规分析流程在可重复性和稀有生物学事件检测方面存在局限。研究开发了DASH自动化框架，整合双向长短期记忆网络、条件随机场和隐马尔可夫模型，对单分子荧光轨迹进行无偏分析。该统一平台执行三项关键功能：（1）自动化轨迹分类，（2）构象状态指认，（3）无需动力学方案的事件分选。","scd":{"b":6.0,"i":3.0,"r":6.0,"d":5.0,"t":5.0},"kp":["分析框架[单分子荧光事件自动分选]: DASH，集成双向长短期记忆网络的深度学习隐状态方法，无需动力学方案"]},{"i":60334,"as":"磁振子和声子等集体激发之间的相干非线性动力学驱动量子材料中的涌现现象，但其直接观测仍然有限。研究利用双太赫兹泵浦-光学探测光谱技术，在层状反铁磁绝缘体FePS3中直接观测到相干磁振子-声子三波混频。研究解析了反铁磁磁振子的二阶和三阶非线性响应，并在二维相干谱中识别出一系列非线性耦合，包括明确的磁振子与声子间的和频与差频产生，为利用相干非线性纠缠磁性和振动激发及量子控制奠定了基础。","scd":{"b":9.0,"i":2.0,"r":7.0,"d":7.0,"t":6.0},"kp":["非线性磁振子-声子耦合[层状反铁磁绝缘体 FePS3，双太赫兹泵浦-光学探测谱]: 直接观测到相干三波混频，并分辨二阶和三阶非线性响应"]},{"i":60335,"as":"由于C-F键强度高及全氟烷基的惰性，全氟烷基链的选择性脱氟仍具挑战。研究报道了一种拉链式反应，可将全氟烷基化烯烃完全脱氟并单硼化，生成具有合成价值的直链烷基硼烷，同时保留碳骨架。反应可放大规模进行，并通过简单过滤以LiF形式回收氟化物。该反应还可应用于偕二氟烯烃，后者被证实是迭代脱氟过程的中间体。","scd":{"b":8.5,"i":3.0,"r":7.0,"d":7.0,"t":6.0},"kp":["氟回收[全氟烷基化烯烃 zippe 式脱氟-单硼化反应]: 以 LiF 形式通过简单过滤回收","底物范围[zippe 反应]: 全氟烷基化烯烃可完全脱氟并保留碳骨架，生成直链烷基硼烷，可放大且适用于偕二氟烯烃"]},{"i":60336,"as":"","scd":null,"kp":[]},{"i":60337,"as":"","scd":null,"kp":[]},{"i":60338,"as":"","scd":null,"kp":[]},{"i":60339,"as":"","scd":null,"kp":[]},{"i":60340,"as":"","scd":null,"kp":[]},{"i":60341,"as":"","scd":null,"kp":[]},{"i":60342,"as":"","scd":null,"kp":[]},{"i":60343,"as":"","scd":null,"kp":[]},{"i":60344,"as":"","scd":null,"kp":[]},{"i":60345,"as":"","scd":null,"kp":[]},{"i":60346,"as":"研究提出一种整合多组学质谱成像（MSI）方法，可在单张肾组织切片上关联分析代谢物、脂质和N-糖链（包括连接特异的唾液酸信息）。该方案能在肾脏小细胞簇中依次检测数百种代谢物和脂质及多种糖基化特征。通过像素级共配准与聚类分析，将正离子模式下检测的糖链与负离子模式下检测的代谢物和脂质在肾脏微结构间建立关联，揭示了各分子类别之间的强相关性，为理解组织内代谢物、脂质与聚糖在同一细胞层的相互作用提供工具。","scd":{"b":6.5,"i":4.0,"r":7.5,"d":7.0,"t":5.0},"kp":["检测通量[整合质谱成像，单张肾组织切片]: 顺序检测数百种代谢物和脂质及多种糖型，含连接键特异性唾液酸信息"]},{"i":60347,"as":"","scd":null,"kp":[]},{"i":60348,"as":"","scd":null,"kp":[]},{"i":60349,"as":"","scd":null,"kp":[]},{"i":60350,"as":"研究揭示钙调蛋白样蛋白CML20整合光敏色素和钙信号通路，优化非生物胁迫下的种子萌发。盐和渗透胁迫迅速升高吸胀种子中细胞质Ca2+水平并抑制萌发，CML20对这些胁迫下的萌发耐受性至关重要。CML20以Ca2+依赖的方式直接与转录因子PIF1相互作用，抑制PIF1的自联和寡聚化，从而解除其对萌发的抑制，协调光照（通过光敏色素B降解PIF1）与钙信号两条通路，使植物在胁迫条件下维持萌发能力。","scd":{"b":7.0,"i":2.0,"r":7.0,"d":6.5,"t":5.0},"kp":["CML20[种子萌发光信号与钙信号整合]: 整合光敏色素与钙信号通路，优化非生物胁迫下萌发"]},{"i":60351,"as":"","scd":null,"kp":[]},{"i":60352,"as":"","scd":null,"kp":[]},{"i":60353,"as":"","scd":null,"kp":[]},{"i":60354,"as":"研究以生物基单体衣康酸二乙酯联合部分石油基丁二烯和4-乙烯基吡啶，通过环境友好的乳液聚合设计合成吡啶功能化生物基弹性体（极性橡胶基质），再以木质素为生物填料构建具有高生物基含量的阻尼弹性体复合材料（VPx-L-DIH）。该策略实现了优异的机械性能和阻尼性能，同时具备可回收性，满足轮胎、密封件和减震器等领域对下一代多功能阻尼弹性体在可持续性方面的需求。","scd":{"b":6.5,"i":3.0,"r":5.0,"d":6.5,"t":5.0},"kp":["弹性体基质[回收生物基衣康酸酯弹性体/木质素复合材料]: 吡啶功能化极性橡胶基质，具备优异机械与阻尼性能及可回收性"]},{"i":60355,"as":"研究以石墨二炔（GDY）的氮取代衍生物——三苯基取代三嗪石墨二炔（TPTG）为理想平台，诱导过渡金属铁（Fe）原子掺杂以调控电子态，实现室温铁磁性与本征半导体行为的共存。GDY家族因可调电子结构和本征半导体特性被视为自旋电子学的合适候选材料，但有效磁性引入方法及其器件应用一直面临挑战。该铁掺杂TPTG半导体为下一代自旋电子器件和多功能信息存储技术提供了新途径。","scd":{"b":7.5,"i":2.5,"r":6.0,"d":6.0,"t":5.0},"kp":["磁性[铁掺杂三苯基取代三嗪石墨二炔半导体]: 室温铁磁性"]},{"i":60356,"as":"","scd":null,"kp":[]},{"i":60357,"as":"综述了细胞外囊泡（EVs）与无机纳米颗粒（INPs）结合体的生产、表征与评估。EVs具有优异生物相容性、固有靶向能力和低免疫原性，是诊断与治疗的有前景生物材料；INPs则为纳米医学带来磁性、光学、热学和催化等多样功能，广泛应用于诊断、成像和药物递送。两者在临床转化中均面临重大挑战，将EVs与INPs整合可结合互补优势，增强生物相容性与递送效率、改善示踪能力并拓展诊断功能，有望推动临床应用。","scd":{"b":5.5,"i":2.5,"r":6.5,"d":5.0,"t":4.0},"kp":["细胞外囊泡特性[与无机纳米颗粒结合用于纳米医学]: 优异生物相容性、内在靶向能力和低免疫原性","无机纳米颗粒功能[纳米医学应用]: 磁性、光学、热学和催化等多样化功能，用于诊断、成像和药物递送"]},{"i":60358,"as":"研究设计了全生物基二嵌段共聚物，由亲水的麦芽六糖/麦芽七糖嵌段与疏水的植物来源茄尼醇嵌段组成。该共聚物自组装形成超高长径比（约1200）的蠕虫状胶束，具有茄尼醇核心和糖冠结构，展现出浓度依赖的粘弹性、机械响应性以及油水界面稳定能力，可用于稳定皮克林样乳液。该工作为将结构组织与宏观功能相结合的全生物基两亲性嵌段共聚物提供了通用设计框架。","scd":{"b":6.0,"i":2.5,"r":5.5,"d":5.5,"t":5.0},"kp":["嵌段共聚物[全生物基 Glc6/7-b-Sol]: 亲水麦芽寡糖区块（以麦芽六糖/七糖为主）与疏水植物源茄尼醇区块组成，可形成蠕虫状胶束用于皮克林样乳液"]},{"i":60359,"as":"研究通过选择性酸处理（H2SO4/HF引入SO42–、H3PO4/HF引入PO43–）对Ti3C2Tx MXene进行硫酸盐和磷酸盐表面功能化，以解决MXene层堆叠、离子可及性受限和赝电容活性不足等问题。表面官能团化通过增加反应位点显著改善MXene的吸附性能，同步增强了其作为超级电容器电极的电化学性能和电磁波吸收性能，为二维MXene材料的功能化改性提供了系统策略。","scd":{"b":6.0,"i":4.0,"r":5.0,"d":6.5,"t":5.0},"kp":["表面功能化[Ti3C2Tx MXene]: 硫酸盐(–S)和磷酸盐(–P)修饰，增强吸附性能","MXene电极问题[超级电容器]: 层状堆叠、离子可及性受限、赝电容活性不足"]},{"i":60360,"as":"该研究利用固态纳米孔研究环状DNA的易位行为。研究人员构建了一系列具有不同单链DNA比例（0%、33%、66%、100%）的环状DNA，并系统考察其电压依赖性易位。在固定偏压下，离子电流阻滞随单链含量线性增加，而驻留时间随单链比例呈指数增长。研究发现了两种电压依赖机制，并在临界单链比例处发生从熵势垒主导到拥挤主导动力学的转变。此前研究几乎全部聚焦线性DNA，该工作填补了环状DNA特别是单链/双链交替片段如何调控转运动力学方面的认知空白。","scd":{"b":6.5,"i":2.5,"r":6.5,"d":7.0,"t":5.0},"kp":["ssDNA比例[环状DNA纳米孔易位]: 0%、33%、66%、100%","动力学转变机制[环状DNA固态纳米孔易位]: 从熵势垒主导转变为拥挤主导动力学"]},{"i":60361,"as":"该研究通过非共面肖特基-欧姆混合接触结构构建高性能InGaZnO/InGaO/InGaZnO三层薄膜晶体管，解决了金属氧化物TFT在超低功耗应用中高迁移率与超低漏电难以兼得的问题。尽管上下均采用相同的ITO电极，差异化界面工程实现了载流子传输的解耦：底部界面形成670 meV肖特基势垒以严格抑制关态漏电，顶部界面则确保低阻欧姆抽取。此外，高阻抗InGaZnO包覆层与高导电InGaO芯层之间形成的深量子势阱（ΔEc=0.20 eV）将载流子强局域化于沟道内，从而实现超高开关比。","scd":{"b":7.0,"i":4.0,"r":5.5,"d":7.5,"t":5.0},"kp":["器件结构[氧化物TFT]: InGaZnO/InGaO/InGaZnO三层非共面肖特基-欧姆混合接触，ITO电极","肖特基势垒高度[底层界面]: 670 meV","器件优势[超低功耗TFT]: 高迁移率与超低漏电流兼得，超高开关比"]},{"i":60362,"as":"富镍层状氧化物因高比容量成为高能量密度锂电池的重要正极材料，但在高电压运行下存在严重的界面和结构退化。该研究开发了结合CeO2包覆与Fe3+掺杂的表面-体相差异化改性策略，利用Ce3+与Fe3+离子半径不同导致的扩散行为差异实现靶向改性。表面CeO2包覆抑制界面退化，Fe3+掺杂改善体相结构，有效缓解了富镍正极的界面退化和体相结构劣化，显著提升了高电压下的电化学稳定性和实用性能。","scd":{"b":6.0,"i":4.5,"r":5.0,"d":7.0,"t":5.0},"kp":["改性策略[高电压富镍正极]: CeO2包覆与Fe3+掺杂的表面-体相差异化修饰","改性目标[富镍层状氧化物]: 抑制高电压下界面与结构退化，提升电化学性能"]},{"i":60363,"as":"直接尿素燃料电池（DUFC）中阳极尿素氧化反应（UOR）动力学缓慢是限制功率输出的关键。该研究通过在泡沫镍上原位生长n型Ni3S2纳米片于p型CoSe2纳米针阵列上，制备出具有纳米珊瑚结构的Ni3S2/CoSe2 p-n异质结催化剂。Mott-Schottky分析、X射线光电子能谱和紫外光电子能谱表明，p-n异质结构促进电荷从Ni3S2纳米片向CoSe2纳米针转移，从而提升UOR性能，尤其在使用含尿素废水作为燃料时改善电池功率输出。","scd":{"b":6.0,"i":3.5,"r":5.0,"d":6.5,"t":5.0},"kp":["催化剂[直接尿素燃料电池阳极脲氧化]: Ni3S2/CoSe2-NF p–n异质结纳米珊瑚结构，原位生长于泡沫镍"]},{"i":60364,"as":"该研究报道了一种喷涂辅助飞秒激光策略，在2A12铝合金上制备分级超黑表面。首先通过飞秒激光扫描产生周期性微结构，提供几何光捕获和多次内反射；随后在激光结构化表面沉积含炭黑和碳纳米管的超黑涂层，在保留激光诱导捕获结构的同时引入强宽带吸收。理论分析和数值模拟表明，增加微结构深宽比可进一步提升吸收性能。这种宽带超黑表面可用于杂散光抑制、红外隐身、太阳能利用和热管理等应用。","scd":{"b":7.0,"i":3.0,"r":4.0,"d":7.0,"t":4.0},"kp":["制备工艺[超黑表面]: 飞秒激光扫描结合喷涂，2A12铝合金基底","结构特征[超黑表面]: 周期性微结构几何陷光与多次内反射实现宽波段抗反射"]},{"i":60365,"as":"","scd":null,"kp":[]},{"i":60366,"as":"","scd":null,"kp":[]},{"i":60367,"as":"","scd":null,"kp":[]},{"i":60368,"as":"水凝胶热电池面临机械性能与热电性能之间的根本性权衡：致密化聚合物网络或强化分子间相互作用等提升机械强度的策略会因网络阻碍效应妨碍离子传输而损害热电性能。该研究提出通用的机械取向增强（MeOB）策略，通过机械预取向聚合物链制备结构各向异性水凝胶，既强化聚合物骨架又建立顺畅的离子通路，从而同时提升机械与热电性能。该方法在三种不同的水凝胶体系中得到验证。","scd":{"b":7.5,"i":4.0,"r":5.0,"d":7.0,"t":5.0},"kp":["策略[水凝胶热电池]: 机械取向增强(MeOB)预排列聚合物链，解除机械性能与热电性能冲突"]},{"i":60369,"as":"高负载单原子催化剂（SACs）因活性位点完全利用、配位环境可调及原子级明确结构，成为电催化领域的前沿方向。然而，有限的金属含量和较低的活性位点密度阻碍了其在实际电解反应器中的大规模应用。该综述系统总结了高负载SACs合成的最新进展，包括在保持原子分散性和运行条件下稳定性的同时提高金属负载量的策略，以及先进的表征技术和在电解领域的应用。","scd":{"b":6.5,"i":3.0,"r":5.0,"d":6.0,"t":4.0},"kp":["关键挑战[高负载单原子催化剂电解]: 金属含量有限与活性位点密度低阻碍大规模应用"]},{"i":60370,"as":"","scd":null,"kp":[]},{"i":60371,"as":"该研究报道了一种具有异相分流结构的全范围汗液速率传感器，通过表皮微流控电导传感与湿度检测的非干扰性集成，实现0.182～10 μL/(min·cm²)范围的连续测量，可同时监测气态和液态汗液。LiCl掺杂的UiO-66-NH2提供了高灵敏度和快速响应的湿度传感。由聚二甲基硅氧烷和聚甲基丙烯酸甲酯共电纺膜构成的仿生异相分流结构具有超疏水特性，用于心理学、皮肤健康和身体脱水评估。","scd":{"b":6.5,"i":4.0,"r":5.0,"d":6.0,"t":4.0},"kp":["传感器设计[全范围汗率监测]: 表皮微流控电导传感与湿度检测非干扰集成，超疏水异相分流，可同时监测气态与液态汗液"]},{"i":60372,"as":"受生物材料分级组装启发，该研究通过凝胶纤维束的多尺度熔融纺丝制备仿生石墨烯纤维。100微米厚的纤维抗拉强度达3.0 GPa，弯曲刚度达1.6×10⁶ N/μm²，比凯夫拉纤维高10⁴倍以上，突破了抗拉强度与弯曲刚度之间的性能权衡。连续熔融诱导的缺陷抑制使厚纤维具有均匀有序结构和稳定性能。该纤维还表现出优异的热学和电学特性，适用于恶劣环境下的机器人技术。","scd":{"b":8.0,"i":4.0,"r":5.0,"d":8.0,"t":4.0},"kp":["拉伸强度[熔纺石墨烯纤维]: 3.0 GPa","结构特点[仿生石墨烯纤维]: 多尺度熔纺凝胶纤维束分级组装，高强度与低弯曲刚度协同"]},{"i":60373,"as":"MXenes因表面组成可调和插层化学多样，成为电化学储能、刺激响应体系和纳米流体技术的通用平台。然而水相或有机相中离子插层的相容性筛选仍主要依赖经验，尚无公认的定量评估框架。该研究提出普适的空间位阻相容性判据：当以分子晶体结构定义的插层分子有效三维尺寸满足几何条件时，插层在几何上变得可行，为评估客体分子进入MXene主体的可行性提供了定量框架。","scd":{"b":6.5,"i":3.0,"r":5.0,"d":6.0,"t":4.0},"kp":["插层剂筛选[MXenes]: 目前主要依赖经验，缺乏公认的定量筛选框架"]},{"i":60374,"as":"该研究报道了原子级分散Pd位点的剥离聚合物氮化碳光催化剂（Pd SA/PCN），可将废PET解聚得到的乙二醇选择性光氧化停留在乙二醛（C2醛）阶段，避免高活性醛中间体的过度氧化和C-C键断裂。在PET水解液中，优化的Pd SA/PCN乙二醛生成速率为2479 μmol g⁻¹ h⁻¹，选择性达92.8%；在克级规模的真实PET废料升级中选择性达95.9%。机理研究表明Pd单原子作为电子抽取中心，从PCN中长寿命低能量局域态移除电子。","scd":{"b":8.0,"i":3.0,"r":6.0,"d":7.0,"t":5.0},"kp":["催化剂[PEG光氧化制乙醛醇]: 原子级分散Pd单原子/剥离型聚合物氮化碳(Pd SA/PCN)","产物选择性[Pd SA/PCN光催化EG氧化]: 抑制过氧化与C-C断裂，终止于C2醛(乙醛醇)阶段"]},{"i":60375,"as":"2D钙钛矿具有强X射线吸收、高电阻率和低离子迁移等优点，但过大的层间距和有限的结构稳定性限制其应用。该研究设计芳香二胺2AMPY（2-氨甲基吡啶），通过调控定制氢键相互作用和有机阳离子在无机八面体框架中的嵌入深度，增强2D钙钛矿的结构刚性并减小层间距。研究还成功生长出厘米级高质量的(2AMPY)PbX4（X=Cl、Br、I）单晶，用于构建高灵敏度、低探测限的X射线探测器。","scd":{"b":7.0,"i":3.0,"r":6.0,"d":6.0,"t":5.0},"kp":["间隔层阳离子[2D钙钛矿单晶]: 芳香二胺2AMPY(2-氨甲基吡啶)","优势特性[2D钙钛矿X射线探测器]: 强X射线吸收、高电阻率、低离子迁移","现有局限[2D钙钛矿]: 层间距过大且结构稳定性受限"]},{"i":60376,"as":"该研究利用以Tm³⁺为发射离子、Yb³⁺为敏化剂的稀土核壳上转换纳米粒子（TmUCNP），对导电聚合物MEH-PPV实现纳米级光激发，用于激子能量转移的二维纳米成像。近红外激光激发TmUCNP后，Tm离子的可见发射通过激发能量转移产生MEH-PPV的激发态。由于MEH-PPV的发射在光谱上可与Tm发射分离，该方案突破了光学激发和检测受衍射限制于亚微米分辨率的问题，可在实空间评估纳米域内的激子迁移行为，为先进材料设计提供信息。","scd":{"b":7.0,"i":2.0,"r":7.0,"d":6.0,"t":4.0},"kp":["上转换纳米探针[共轭聚合物激子迁移纳米成像]: Tm3+为发射体、Yb3+为敏化剂的稀土核壳上转换纳米粒子(TmUCNP)","功能[纳米测绘]: 实现超越衍射极限的光激发与激子能量转移实空间评估"]},{"i":60377,"as":"该研究建立了自下而上的微芯片方法，支持运动神经元对三维人体肌肉的神经支配，并允许局部或浸浴施加特定化学刺激。同一架构还支持内皮细胞向内生长，形成神经和内皮整合并存的人肌肉束。重复局部L-谷氨酸刺激诱导了与活动依赖性肌肉适应相关的结构、代谢和转录变化，而高葡萄糖暴露引发代谢应激。该模型可模拟活动诱导重塑、代谢应激及内皮调控的兴奋性，弥补现有体外神经肌肉模型对活动依赖性适应和内皮细胞贡献表征不足的缺陷。","scd":{"b":7.0,"i":3.0,"r":6.0,"d":6.0,"t":4.0},"kp":["神经肌肉芯片模型[体外构建]: 自下而上微芯片方法，支持3D人肌肉的运动神经支配","刺激施加方式[微芯片]: 支持局部或浸浴式施加特定化学刺激","模型能力[神经肌肉系统]: 可研究活动依赖性适应、代谢应激及内皮细胞调节兴奋性"]},{"i":60378,"as":"该研究报道了热退火供体辅助顺序沉积（TD-SD）策略，用于调控有机太阳能电池活性层成膜动力学。传统顺序沉积面临界面侵蚀和无序结晶等挑战。通过对供体层预退火形成有序供体分子堆积，供体提供的热效应加速受体聚集动力学，从而缓解受体对供体的侵蚀，实现垂直相分离的动力学调控。该策略将有机太阳能电池的光电转换效率提升至20.81%。","scd":{"b":7.0,"i":4.0,"r":6.0,"d":7.0,"t":5.0},"kp":["转换效率[有机太阳能电池]: 20.81%","工艺策略[顺序沉积SD]: 热退火供体辅助顺序沉积(TD-SD)调控垂直相分离动力学","现有问题[传统SD方法]: 界面侵蚀和无序结晶限制效率提升"]},{"i":60379,"as":"有机场效应晶体管（OFET）是柔性电路的基本构件，但在运行和储存期间的不稳定性限制其实际应用。不稳定性源于两大因素：化学退化——环境中氧气和水通过氧化还原反应破坏有机半导体的分子完整性；物理退化——有机半导体电荷态和聚集态的不良变化。该综述系统探讨了各种应力条件下的退化机制，并批判性评估了通过抑制氧化还原反应的化学方法和稳定电荷与聚集态的物理方法提升稳定性的进展。","scd":{"b":5.0,"i":3.0,"r":6.0,"d":6.0,"t":4.0},"kp":["不稳定性来源[OFET运行与储存]: 化学降解(氧/水氧化还原破坏分子完整性)与物理降解(电荷及相关性质劣变)"]},{"i":60380,"as":"针对Y系列非富勒烯受体中H聚集与J聚集平衡难以控制的问题，研究者设计了三种具有相同共轭骨架但内侧烷基链系统变化的新型NFA（C8C8、C8-7R和C8EH）。理论计算和单晶分析表明，增加内侧链位阻可抑制涉及核的H型聚集接触，同时有利于端基介导的J型相互作用，从而精细调控聚集态。该策略实现了无添加剂、无退火有机太阳能电池20.73%的效率。","scd":{"b":7.0,"i":4.0,"r":6.0,"d":7.0,"t":5.0},"kp":["转换效率[无添加剂无退火有机太阳能电池]: 20.73%","聚集调控策略[Y系列NFA]: 内部烷基链引导有序J聚集，平衡H/J聚集行为","J聚集优势[NFA分子堆积]: 有利于电子耦合、发光并降低非辐射损失"]},{"i":60381,"as":"","scd":null,"kp":[]},{"i":60382,"as":"为实现不需要辅助电荷捕获组分的单组分光子突触，研究者提出非对称载流子捕获（ACT）策略，使n型共轭聚合物具备本征非易失性光响应。通过对前线轨道能量和分布的定制设计，ACT结合了深能级、离域的最低未占分子轨道（LUMO），从而在单一组分中实现光学感知与记忆的集成，避免了传统多组分结构带来的工艺复杂性和衬底兼容性问题，有利于大面积集成，适用于神经形态视觉应用。","scd":{"b":7.5,"i":3.0,"r":6.0,"d":6.0,"t":4.0},"kp":["单组分光突触[神经形态视觉]: 本征非易失性n型聚合物突触，无需辅助电荷捕获组分","现有挑战[光子突触]: 依赖辅助电荷捕获组件导致工艺复杂、基底兼容性差、限制大面积集成"]},{"i":60383,"as":"钠离子电池因地壳中元素储量丰富而被视为锂离子电池的有力继任者。其较低的能量密度常被提及，但该研究指出牺牲能量密度并不能保证安全性，正极结构才是决定钠离子电池安全性的关键因素。（正文内容不完整，无法提供更多细节。）","scd":{"b":6.0,"i":4.0,"r":6.0,"d":5.0,"t":5.0},"kp":["安全性与能量密度关系[钠离子电池]: 牺牲能量密度并不能保证安全性，正极结构决定钠电池安全性","优势[钠离子电池]: 地壳元素丰度高，被视为锂电池有前景的接替者"]},{"i":60384,"as":"针对传统荧光探针背景荧光高、靶标特异性有限的问题，研究者报道了基于多通道无势垒淬灭（MCBQ）的分子支架平台。该平台通过柔性吡啶鎓位置异构体设计实现向双扭曲分子内电荷转移（TICT）态的无势垒跃迁，从而抑制背景发射，构建超荧光性的线粒体探针平台，可用于线粒体动力学的非侵入性可视化成像。","scd":{"b":8.0,"i":3.0,"r":6.0,"d":7.0,"t":6.0},"kp":["荧光探针背景抑制机制[MCBQ平台]: 通过柔性吡啶鎓位置异构体设计实现双TICT态无势垒跃迁的多通道无势垒猝灭","探针靶向[MCBQ分子平台]: 线粒体动态成像"]},{"i":60385,"as":"","scd":null,"kp":[]},{"i":60386,"as":"全无机CsPbI3钙钛矿太阳能电池因中间相演化的异质性和不均匀结晶动力学导致晶体质量差。研究者开发了中间相均质化策略，利用抗坏血酸钙通过与钙钛矿组分的静电相互作用、氢键和配位键协同调节中间相，有效抑制Cs4PbI6中间体的形成并调控结晶过程，制备出均匀的CsPbI3薄膜，从而实现高效稳定的钙钛矿太阳能电池。","scd":{"b":7.0,"i":4.0,"r":5.0,"d":7.0,"t":5.0},"kp":["中间相均匀化策略[全无机CsPbI3钙钛矿太阳能电池]: 抑制中间相异质性演化以制备均匀CsPbI3薄膜，改善结晶质量","材料优势[全无机CsPbI3]: 相比杂化钙钛矿具有更优的抗热分解和卤化物偏析能力"]},{"i":60387,"as":"","scd":null,"kp":[]},{"i":60388,"as":"","scd":null,"kp":[]},{"i":60389,"as":"","scd":null,"kp":[]},{"i":60390,"as":"","scd":null,"kp":[]},{"i":60391,"as":"研究报道了亚稳态氪与铷原子冷电离碰撞中散射振荡的直接观测。通过结合激光冷却与速度映射离子成像技术，将碰撞能量精确控制在15毫开尔文至8开尔文范围并检测电离产物。在1开尔文以下，当德布罗意波长接近相互作用范围时，分波间出现显著的量子干涉。角振荡周期按θp∝E^(-1/3)标度，符合范德华主导相互作用的朗之万俘获模型，突破了以往实验局限于轻原子体系的限制。","scd":{"b":8.5,"i":2.0,"r":8.0,"d":8.0,"t":6.0},"kp":["碰撞能量控制范围[激光冷却+速度映射离子成像的Kr*+Rb冷碰撞]: 15 mK至8 K","量子散射振荡观测[亚稳氪-铷冷电离碰撞]: 首次在重原子体系中直接观测散射振荡"]},{"i":60392,"as":"","scd":null,"kp":[]},{"i":60393,"as":"","scd":null,"kp":[]},{"i":60394,"as":"植物细胞通过胞间连丝（PD）进行细胞间物质运输。正向遗传筛选发现了胚胎发生期间PD运输增加（ise1至ise4）或减少（dse1）的突变体。研究发现dse1、ise3和ise4的转录谱高度相似，例外的是受保守激酶TOR及其下游bZIP转录因子ABI5调控的基因集。葡萄糖-TOR-ABI5信号轴通过驱动定位于PD的胼胝质结合蛋白（PDCBs）的表达来调控PD运输，且PDCBs在ise与dse突变体中呈相反调控，从而通过胼胝质沉积限制细胞间通讯。","scd":{"b":7.0,"i":2.0,"r":5.0,"d":6.0,"t":5.0},"kp":["葡萄糖-TOR-PDCB信号通路[胼胝质沉积调控]: 通过胼胝质沉积限制胞间连丝介导的细胞间通讯","突变体表型[胚胎期PD运输遗传筛选]: ise1-ise4增加PD运输、dse1降低PD运输"]},{"i":60395,"as":"人工赝磁场结构可在色散关系中产生朗道能级，使弹性波在机械超材料中呈现类磁行为。该研究报道了由平行平台和主动连接弹簧组成的三类赝磁结构：锯齿边缘带、扶手椅边缘带和三轴构型。基于有效渐近模型研究了非均匀刚度分布周期单元中狄拉克锥的动量偏移。通过对动量偏移提供的矢量势施加不同规范，由单轴或三轴刚度调制生成赝磁场结构。随着朗道能级的出现，可选择多种传播模式，实现弹性波的主动调控。","scd":{"b":8.0,"i":3.0,"r":6.0,"d":7.0,"t":5.0},"kp":["赝磁场结构类型[弹性波拓扑机器人超材料]: 锯齿边缘条带、扶手椅边缘条带和三轴构型","朗道能级[人工赝磁结构]: 在弹性波色散关系中产生类磁场行为"]},{"i":60396,"as":"针对溶液法制备的二维/三维（2D/3D）钙钛矿异质结构中的相不纯问题，研究者利用过量碘化铅的模板生长策略，在3D钙钛矿表面引导形成稳健的相纯2D钙钛ite。该策略有效抑制了2D/3D界面的相分离和离子互扩散，并促进有利于电荷提取的能级对齐。所得2D/3D器件效率达26.8%（认证效率26.5%），连续运行3000小时后保持初始性能的95%以上，90天内几乎保持100%的初始性能。","scd":{"b":8.0,"i":4.0,"r":6.0,"d":8.0,"t":6.0},"kp":["模板生长策略[2D/3D钙钛矿异质结构]: 利用过量碘化铅引导在3D钙钛矿表面形成纯相2D钙钛矿","界面抑制效果[模板生长纯相2D钙钛矿]: 有效抑制相偏析和离子互扩散"]},{"i":60397,"as":"研究表征了嫦娥六号月球样品中一个多孔团聚富碳尘粒CE6-CDP，其平均δ13CVPDB值为-25.92±3.62‰，并表现出显著的氮富集。纳米红外光谱检测到N-H、C=N和C-H键，表明其碳质材料具有类有机物特征。尘粒内具有缠绕和同心纹理的石墨碳δ13CVPDB值相近（-27.31‰）但含氮量低，提示部分有机前驱体可能发生了石墨化。类有机碳质材料与石墨碳的共存与尘粒喷射事件相符。","scd":{"b":8.5,"i":2.0,"r":8.0,"d":8.0,"t":6.0},"kp":["碳同位素组成[嫦娥六号月壤富碳尘粒CE6-CDP]: δ13CVPDB平均值为−25.92±3.62‰","化学键特征[CE6-CDP纳米红外光谱]: 检测到N–H、C=N和C–H键，呈类有机碳特征并显著富氮","石墨化[CE6-CDP含氮类有机碳质材料]: 观察到石墨碳形成"]},{"i":60398,"as":"","scd":null,"kp":[]},{"i":60399,"as":"为实现肽凝聚层组装-解组装生命周期的远程、无创调控，研究者报道了通过螺吡喃光开关非共价整合的超分子设计，实现光和pH门控的肽可逆凝聚。其机制依赖于螺pyran光异构化诱导的电荷转移，进而调控肽间静电相互作用驱动凝聚层形成。撤光后通过热弛豫可逆发生解离，该过程进一步受pH调控，从而实现对液-液相分离形成的类细胞区室的按需控制。","scd":{"b":7.0,"i":2.0,"r":5.0,"d":6.0,"t":5.0},"kp":["可逆调制机制[多肽凝聚体]: 通过螺吡喃光开关的非共价整合实现光和pH门控的可逆凝聚","组装方式[多肽凝聚体]: 液液相分离（LLPS）"]},{"i":60400,"as":"为在分子框架中实现对外部自旋通信的稳健操控，研究者将两种二噻吩乙烯（DTE）单元引入基于三(2,4,6-三氯苯基)甲基（TTM）的双自由基，成功实现了分子光学和磁性质的双稳态切换。可见光照射开环形式可生成高达97%的闭环形式，其中两个自由基中心之间的共轭导致整个可见光范围的吸收以及单重态-三重态能隙翻倍。这些结果确立了TTM/DTE杂化体作为持久、多级响应双自由基材料的地位。","scd":{"b":7.0,"i":2.0,"r":5.0,"d":7.0,"t":5.0},"kp":["闭环产率[DTE桥连TTM双自由基光开关]: 可见光照射开环体生成高达97%的闭环体","双稳态开关特性[DTE-TTM双自由基]: 光学与磁性质可双稳态切换，用于自旋通信操控"]},{"i":60401,"as":"手性β-氟胺是药物和农药中的重要结构单元，其C─F和C─N立体中心的构型直接影响生物活性，但现有合成方法无法一步获得全部立体异构体。本研究通过立体发散性工程改造亚胺还原酶（IRED），构建一组立体互补的变体，利用α-氟代酮与胺的动态动力学还原胺化（DKRA），可编程地获得β-氟胺的全部四种立体异构体。","scd":{"b":7.5,"i":3.0,"r":6.0,"d":7.0,"t":5.0},"kp":["立体发散合成[工程化亚胺还原酶催化的动态动力学还原胺化]: 可获得β-氟胺的全部四种立体异构体","手性中心[β-氟胺]: C–F和C–N立体中心的构型直接影响生物活性"]},{"i":60402,"as":"非富勒烯受体有机太阳能电池（OSC）的光电转换效率已超20%，但长期稳定性受限于本体异质结薄膜中不受控的分子聚集和形貌退化。本研究报道噻唑基受体BDTTz作为分子堆积整形器，选择性调控受体H-聚集。理论计算表明BDTTz与L8-BO的相互作用强于与PM6的作用，可在不破坏给体组织的情况下强化受体堆积。将BDTTz掺入PM6:L8-BO共混体系，使受体结晶窗口从32 ms延长至48 ms，相干长度从50.2（单位未完整给出）增加。","scd":{"b":7.0,"i":4.0,"r":5.0,"d":7.0,"t":5.0},"kp":["转换效率[非富勒烯受体有机太阳能电池]: 超过20%","分子堆积整形器[调控受体H聚集]: 噻唑基受体BDTTz"]},{"i":60403,"as":"","scd":null,"kp":[]},{"i":60404,"as":"双折射材料可根据偏振和传播方向分光，在电信、成像、光子学及生物医学、航天等领域至关重要，但多数可切换双折射材料存在双折射值低或可调范围窄的问题。本研究报道了一种动态氢键有机框架（HOF），可在客体分子嵌入时发生可逆的单晶到单晶转变，从而实现巨大的OFF–ON双折射切换。","scd":{"b":8.0,"i":2.0,"r":6.0,"d":6.0,"t":5.0},"kp":["双折射材料[动态氢键有机框架]: 巨大OFF-ON双折射开关特性"]},{"i":60405,"as":"光催化由水和氧合成过氧化氢是蒽醌法的有前景替代方案，其效率取决于电荷分离和反应物传输。本研究采用侧链策略调控腙连接共价有机框架（COF）的纳米通道微环境，以相同苯并三噻吩节点合成了带H、OMe、OEt或OEtOMe基团的四种COF。烷氧基侧链可调节孔极性、孔隙率、电子性质及水和氧吸附。其中COF-Hz-OEtOMe具有最强的水氧亲和力和良好的电荷分离行为，在优化条件下H2O2产率达7240 µmol g−1 h−1。","scd":{"b":7.0,"i":3.0,"r":6.0,"d":7.0,"t":5.0},"kp":["侧链策略[调控COF纳米通道微环境]: H、OMe、OEt或OEtOMe基团","光催化H2O2合成[腙键连COF]: 以水和氧为原料替代蒽醌工艺"]},{"i":60406,"as":"双阳离子特烯（tetrylene）具有独特的σ-受体性质，但因内在不稳定性和配位化学有限，长期仅是化学奇观。Chen和Zhang将这些难以捉摸的物种转化为实用的、电子可编程的Z型配体，实现了铂亲电性和催化性能的系统性调控。该工作建立了Z型配体设计的新范式。","scd":{"b":8.0,"i":2.0,"r":7.0,"d":5.0,"t":5.0},"kp":["Z型配体[双阳离子特曲伦]: 电子可编程调谐铂电亲性与催化性能"]},{"i":60407,"as":"手性多环芳烃（PAH）因光学和电化学性质受到关注，但轴手性PAH研究较少。本研究设计合成了分别含两个和四个连续五边形的两种新型非交替PAH（1和2）。在酸性条件下，单体1和2发生二聚，生成轴手性二聚体AC1和AC2。单晶X射线分析表明，2和AC2中中央薁单元显示出异常短的跨环键（1.366 Å），导致独特芳香性。与单体不同，二聚体AC1和AC2表现出可逆的氧化还原行为。","scd":{"b":7.0,"i":2.0,"r":6.0,"d":6.0,"t":5.0},"kp":["非交替多环芳烃[含连续五元环]: 单体1和2分别含两个和四个连续五元环","合成条件[轴向手性PAH二聚]: 酸性条件下二聚"]},{"i":60408,"as":"碱金属氟化物因其宽电化学稳定性窗口和高机械刚度，可在金属电池中形成稳健的固态电解质界面（SEI），但SEI的复杂性和动态行为长期阻碍了对富氟畴的直接化学分辨可视化。本研究采用四(4-羧基苯基)乙烯（H4TCPE）作为荧光探针，基于晶格特异的基质配位诱导发光机制，实现碱金属富氟化物界面的便捷半定量可视化，其中结晶NaF通过强水合作用（正文截断）选择性激活H4TCPE荧光。","scd":{"b":7.0,"i":3.0,"r":7.0,"d":7.0,"t":5.0},"kp":["荧光探针[钠金属电池NaF富集界面可视化]: 四(4-羧基苯基)乙烯H4TCPE"]},{"i":60409,"as":"有效抑制光生电荷复合是光催化分解水的核心挑战。Bi4Ti3O12是用于全分解水的有前景的铁电半导体，但其量子效率受弱极化和缓慢载流子动力学限制。本研究证明等价A位取代可通过晶格规整化放大Bi4Ti3O12的内在极化：Sm取代通过减弱Bi3+孤对的立体化学活性抑制局域无序，减少过度八面体倾斜，实现更一致的偶极排列，从而增强的铁电极化场显著促进电荷（正文截断）传输与分离。","scd":{"b":7.0,"i":3.0,"r":5.0,"d":6.0,"t":5.0},"kp":["A位取代[Bi4Ti3O12铁电极化增强]: 等价A位取代通过晶格规整化放大本征极化"]},{"i":60410,"as":"生物分子是疾病发生、诊断和治疗的核心，但能主动与生物靶标相互作用的材料有限。镓基液态金属及其衍生复合材料具有金属液态核心、动态氧化物界面和可释放金属物种，支持多样的分子相互作用和调控过程。本综述提出液态金属分子医学（LMMM）作为跨学科框架，将液态金属活性成分、分子机制与生物医学功能相连接，并阐述了LMMM的机制基础，系统整理了当前研究进展。","scd":{"b":7.0,"i":3.0,"r":6.0,"d":5.0,"t":4.0},"kp":["液态金属[镓基生物医学材料]: 金属液核、动态氧化物界面与可释放金属物种支持多种分子相互作用"]},{"i":60411,"as":"在氟油介质中的水微滴赋予自折叠水溶性合成受体（深穴番）独特行为。这些亲脂但水溶性的穴番在水-油界面自组装，覆盖微滴表面而非扩散至内部。将受体与在主体空腔中结合的指示剂染料结合，可实现分子识别事件的简单光学检测及受体在液滴中的时空监测。界面自组装由穴番分子间疏水缔合驱动，可观察到对合适客体分子的可控分子识别，并通过液滴合并实验（正文截断）进行研究。","scd":{"b":6.0,"i":2.0,"r":6.0,"d":6.0,"t":5.0},"kp":["合成受体[水微滴油水界面自组装]: 深穴状受体在微滴表面涂层而非扩散入内部"]},{"i":60412,"as":"光辅助锂硫电池（PALSB）可加速硫正极缓慢的氧化还原动力学，但光场使界面反应复杂化，需要真实工况下的原位证据。本研究构建TiO2/FePS3（TF）p–n结双功能光电极，并采用多物理场耦合原位X射线谱学技术阐明从界面到体相的光调控催化。Operando低能XPS识别潜在界面催化位点；高能operando XAFS首次应用于PALSB，追踪循环过程中催化中心K边的位置变化，结果显示可逆的动态价态演变与逐步（正文截断）反应同步。","scd":{"b":7.5,"i":3.0,"r":7.0,"d":7.0,"t":5.0},"kp":["光电极[光辅助锂硫电池]: TiO2/FePS3 p-n结双功能光电极","表征技术[工况原位表征]: 多物理场耦合原位X射线光谱"]},{"i":60413,"as":"本研究建立了固相合成平台，用于快速、模块化、可规模化合成合成金属载体KO-NH2，其可被细菌铁载体转运蛋白识别，但对Ga3+的亲和力优于Fe3+。构建了四种原型铁载体类似物（KK-COOH、KO-NH2、KO-COOH和OK-COOH）。在大肠杆菌中的生长恢复、放射性摄取和共价光交联研究确定CirA和Fiu为可结合KO-NH2连接双功能构建体的主要外膜转运蛋白。计算研究进一步支持KO或OK肽可有效模拟PC的结构骨架，热力学稳定性研究揭示非典型的热力学稳定性反转（正文截断）。","scd":{"b":7.0,"i":3.0,"r":6.0,"d":7.0,"t":5.0},"kp":["合成金属载体[KO-NH2]: 对Ga3+的亲和力优于Fe3+，可被细菌铁载体转运体识别","合成平台[固相合成]: 快速、模块化、可规模化","优势外膜转运蛋白[大肠杆菌]: CirA和Fiu"]},{"i":60414,"as":"金属氢化物合成长期受制于传统范式：金属被认为只能与分子氢而非溶液中的质子反应生成氢化物，因此需要经由高纯氢气生产和压缩的间接路线。本研究利用酸性腐蚀和氢脆在金属内原位构建氢捕获笼（HTC），实现温和条件下（常压、温度降低约70%）质子直接转化为氢化物。该法直接以酸中的质子为氢源，无需高压氢气。","scd":{"b":9.0,"i":2.0,"r":7.0,"d":7.0,"t":6.0},"kp":["氢捕获笼[金属中原位构建]: 利用酸性腐蚀和氢脆实现质子直接转化为金属氢化物"]},{"i":60415,"as":"本研究开发了一种氧化还原中性的氢氨烷基化策略，由烯烃和炔烃合成1,1-二取代氨基环丙烷。通过简单的溶剂分解活化，易于获得且台架稳定的半缩醛胺前驱体在室温下即可高产率得到目标产物。该方法的底物耐受性与经典氨基环丙烷合成正交，用于制备药物活性偕-α-二甲基胺的生物电子等排体后获得了改善的生物学性质。","scd":{"b":6.5,"i":3.0,"r":5.0,"d":6.0,"t":5.0},"kp":["羟氨基烷基化[氧化还原中性]: 由烯烃和炔烃合成1,1-二取代氨基环丙烷","反应条件[半胺前体溶剂解活化]: 室温下优异产率，底物耐受性与经典方法正交"]},{"i":60416,"as":"在有机太阳能电池中实现理想双连续网络需平衡分子自组装与成膜动力学。强相互作用聚合物如D18的强烈骨架相互作用常导致动力学捕获的无序态。本研究提出分子对称破缺策略，采用不对称小分子给体BC-A2O作为客体调节剂。与其对称对应物BC-A4O相比，BC-A2O具有刚性绕丹宁钩和更高的液晶吉布斯自由能差，这种强热力学驱动力使其优先锚定在D18链上，建立溶液相界面预结构，诱导形成高度有序的纤维状主体网络，优化电荷传输通道。","scd":{"b":6.5,"i":4.0,"r":5.0,"d":7.0,"t":5.0},"kp":["客体调节剂[不对称小分子给体]: BC-A2O含刚性若丹宁钩，实现分子对称性破缺"]},{"i":60417,"as":"本研究披露了一种通用方案，利用镍催化和经sp3 C─C键断裂活化的脂肪族羰基前驱体，实现烯烃的三组分双官能化。在可见光照射下，该转化为从易得前驱体在烯烃上引入两个相邻碳-碳键提供了高效策略。值得注意的是，该烯烃双官能化被拓展为对映选择性变体，可便捷获得复杂的富对映体骨架。反应操作简单、底物范围广，具有优异的区域选择性和化学选择性，与生物活性结构兼容，并可加速药物相关分子的合成。","scd":{"b":6.5,"i":3.0,"r":5.0,"d":6.0,"t":5.0},"kp":["烯烃双官能化[镍/光氧化还原催化]: 可见光下经酮sp3 C─C键断裂实现三组分反应，可扩展至对映选择性变体"]},{"i":60418,"as":"水系锌碘电池在大规模储能方面具有前景，但受限于碘正极和锌负极稳定性不足。本研究提出空间电荷协同调制策略，通过阳离子缺陷、带负电的Ti0.87□0.13O2 0.52−纳米片功能化隔膜，同时抑制多碘化物穿梭效应和锌枝晶生长。纳米片内的亚纳米钛空位通过尺寸筛分效应选择性排斥多碘化物阴离子，同时允许Zn2+快速传输；带负电层通过静电作用排斥多碘化物并均匀化Zn2+离子通量，使功能化隔膜得以实现（正文截断）双界面稳定。","scd":{"b":6.5,"i":4.0,"r":5.0,"d":7.0,"t":5.0},"kp":["功能隔膜[水系锌碘电池]: 阳离子缺陷、带负电的Ti0.87□0.13O2^0.52-纳米片","双界面稳定策略[空间电荷协同调制]: 同时抑制多碘化物穿梭效应和锌枝晶生长"]},{"i":60419,"as":"在分子平台上实现精确、可调的手性表达对手性光学材料的设计合成具有重要意义。本研究构建了超分子穴番平台，实现光门控的手性信息可编程锁定、切换和重写。该基于间苯二酚[4]芳烃的穴番整合了多个光异构化二苯乙烯和交替咪唑片段。通过外壁结合策略结合多个手性羧酸，实现高效手性转移，构建超分子手性穴番。二苯乙烯单元的光异构化驱动路径依赖的构象转变，控制手性的诱导、保留和擦除。","scd":{"b":7.0,"i":2.0,"r":5.0,"d":6.0,"t":5.0},"kp":["超分子穴状配体[间苯二酚[4]芳烃基]: 整合光异构化茋与咪唑片段，实现光控手性锁定、切换和重写"]},{"i":60420,"as":"","scd":null,"kp":[]},{"i":60421,"as":"","scd":null,"kp":[]},{"i":60422,"as":"","scd":null,"kp":[]},{"i":60423,"as":"","scd":null,"kp":[]},{"i":60424,"as":"一种AI模型能够高精度预测热带气旋的路径和强度，有望将预警时间提前一天。若能在全球范围内负责任地共享该技术，将具有保护生命的潜力。","scd":{"b":7.0,"i":4.0,"r":5.0,"d":5.0,"t":7.0},"kp":["AI预测模型[热带气旋]: 路径和强度预测可额外提前一天预警"]},{"i":60425,"as":"欧洲四个国家的超精密光学钟实现了同步运转。研究人员通过光纤电缆传输信号进行比对，验证了分布在欧洲各地的七台光学钟之间的一致性，展现了跨地域高精度时间比对的能力。","scd":{"b":6.0,"i":3.0,"r":6.0,"d":6.0,"t":7.0},"kp":["光学钟比对[欧洲四国光纤信号]: 七台超精密光学钟跨欧洲高精度一致"]},{"i":60426,"as":"Nature工作人员讨论2026年搞笑诺贝尔奖得主，其中包括一项利用1000条埋在土中的内裤测量土壤健康的研究。此外还讨论了一个孤立的能量闪光，其可能是暗物质的首次观测迹象。","scd":{"b":2.0,"i":1.0,"r":3.0,"d":2.0,"t":6.0},"kp":["土壤健康测量[埋藏内裤法]: 1000条埋藏内裤用于评估土壤健康"]},{"i":60427,"as":"单细胞内的能量转换和信息传递与多种物理场的局部涨落相关，包括化学浓度场、热场、磁场、电场和机械力场。研究介绍了单细胞内的光学多物理场成像技术，可对细胞内多种物理场进行观测。","scd":{"b":7.0,"i":3.0,"r":6.0,"d":6.0,"t":5.0},"kp":["[单细胞内光学多物理场成像]: 涉及化学浓度场、热场、磁场、电场与机械力场的局部涨落"]},{"i":60428,"as":"该综述从化学驱动视角审视交磁体（altermagnets）这一新近确认的磁性材料类别，重点阐述晶体化学、对称性、成键及电子结构作为研究和开发交磁材料的关键使能因素。","scd":{"b":6.5,"i":3.0,"r":6.0,"d":5.0,"t":4.0},"kp":["[交变磁性材料]: 晶体化学、对称性、成键及电子结构为关键使能因素"]},{"i":60429,"as":"基于硼氮嵌入式多环芳烃的多共振（MR）型发光体具有高光致发光量子产率和窄发射光谱，是有机发光二极管（OLED）实现超纯色的最有前景候选材料，但发射寿命长限制了其作为非敏化TADF发光体的应用。研究通过环金属化将DBANA衍生框架引入Pt(II)配合物，与氮杂环卡宾组合形成双齿发色配体，使MR-B/N核心仍主导配合物的最低单重态和三重态激发态，从而改善蓝色MR-TADF发射。","scd":{"b":7.0,"i":4.0,"r":6.0,"d":7.0,"t":5.0},"kp":["发射体[窄带蓝色TADF]: B、N嵌入多环芳烃多共振框架环金属化融合铂(II)配合物","[MR-TADF瓶颈]: 非敏化发射寿命过长限制应用"]},{"i":60430,"as":"手性Josiphos钴配合物催化芳基、杂芳基和烯基卤化物对各类直链与支链脂肪醛的对映选择性加成，无需导向基团。该方法可放大制备，钴催化剂负载量低，已用于简捷合成药物或合成前体关键结构单元的手性醇。该催化剂对 手性氨基醛的加成也具有高非对映选择性。机理研究表明芳基钴(II)阳离子配合物是不对称插入的活性物种，Lewis酸性的钛醇盐辅助芳基钴卤化物电离形成阳离子配合物。","scd":{"b":6.5,"i":4.0,"r":6.0,"d":7.0,"t":5.0},"kp":["催化剂[芳基/杂芳基/烯基卤代物对脂肪醛对映选择性加成]: 手性Josiphos钴配合物","[催化体系特点]: 无需导向基、低钴催化剂负载量、易于放大"]},{"i":60431,"as":"共价有机框架（COFs）是氧还原反应（ORR）光催化制过氧化氢的有前景光催化剂，但不同基元步骤的电子需求难以兼顾。基于Sabatier原理和Marcus-Hush电子转移理论，研究报道了同时调控原子活性位点和分子骨架的PyaD COF：适度极化的活性位点平衡了吸附/脱附步骤，将H2O2脱附能垒从0.82 eV降至0.46 eV；骨架间增强的层间π-π电子耦合促进电子转移，使激发态寿命延长一个数量级以上。","scd":{"b":7.0,"i":3.0,"r":6.0,"d":7.0,"t":5.0},"kp":["[PyaD COF双电子调控光催化合成过氧化氢]: 中等极化活性位平衡吸附/脱附，基于Sabatier原理与Marcus-Hush电子转移理论"]},{"i":60432,"as":"聚硫酯因其优异的材料性能和更好的废弃处理选择而日益受到关注，但硫代内酯的环张力低于内酯，限制了常规开环聚合。硫代内酯异构化开环聚合可提供额外热力学驱动力。报道的生物基三环硫代内酯（TCTn）可选择性聚合生成高分子量的P(TCT)聚硫酯，解决了已有聚硫酯玻璃化转变温度偏低的问题。","scd":{"b":6.0,"i":3.0,"r":6.0,"d":6.0,"t":4.0},"kp":["[高Tg聚硫酯制备]: 可再生氧杂降冰片烷稠合硫代内酯的异构化开环聚合"]},{"i":60433,"as":"带位阻取代基的小分子受体（SMAs）可抑制过度聚集引起的非辐射能量损失，但常因破坏π轨道重叠和共混形貌而损害电荷传输。研究通过在SMA骨架中引入高结晶性发光的3,6-二氯咔唑单元进行连接拓扑工程，系统调控连接方式——从直接C-N连接（CHC-1）到柔性亚甲基桥（CHC-2）及刚性羰基连接——调节受体自聚集和给受体分子间相互作用，缓解了这一内在权衡，使有机太阳能电池效率超过20.5%。","scd":{"b":7.5,"i":5.0,"r":6.0,"d":8.0,"t":5.0},"kp":["转换效率[有机太阳能电池]: >20.5%","策略[小分子受体]: 引入3,6-二氯咔唑单元的连接子拓扑工程平衡受体聚集与给受体共混"]},{"i":60434,"as":"针对水系锌金属电池中锌负极在高倍率、高容量下面临的界面传质与动力学瓶颈（源于竞争性析氢反应和显著极化），研究建立了整合主动学习材料筛选与成分梯度合金（GL）负极及界面动力学补偿的预测性设计范式。梯度晶界避免了高倍率下应力集中导致的结构失效。GL负极在40 mA cm⁻²下实现20000次循环，在80 mA cm⁻²下累积容量达81.36 Ah。","scd":{"b":7.5,"i":4.0,"r":6.0,"d":7.0,"t":5.0},"kp":["[锌合金负极设计范式]: 主动学习材料筛选结合成分梯度合金负极，缓解析氢竞争与极化","[应用场景]: 水系锌金属电池高倍率高容量 pouch 电池，面向电网储能"]},{"i":60435,"as":"贵金属纳米颗粒在无锚定位点时通常经Ostwald熟化聚集，而在合适配位环境下可分散为热力学稳定的单原子。研究报道了氮掺杂碳上纳米颗粒与单原子间的意外交错转化：800°C构建的M(Rh、Ir、Pt)-Zn金属间化合物纳米颗粒与Ru单原子，在1000°C退火后转化为M单原子和Ru纳米颗粒。元动力学模拟表明1000°C下Ru-N键断裂伴随Rh回填在动力学上可行，自由能垒约2.30 eV。所得Rh12Ru1+Rh-N构型促进甲酸电氧化。","scd":{"b":7.0,"i":3.0,"r":6.5,"d":7.0,"t":5.0},"kp":["[甲酸电氧化增强机制]: 氮掺杂碳上Rh/Ir/Pt-Zn金属间化合物纳米颗粒与Ru单原子间的相变驱动原子穿梭交叠转变"]},{"i":60436,"as":"长波长多共振（MR）发光体是高色纯度OLED的理想材料，但传统红移策略常增强激发态离域和振动耦合导致光谱展宽。研究提出对称性重构策略打破红移与展宽之间的权衡：单侧和双侧萘并π扩展分别得到SN-BN和DN-BN，用于关联激发态对称性、振动耦合与发射带宽。SN-BN降低激发态能量但破坏了空穴-电子分布平衡，引入部分电荷转移特征并增强振动耦合。","scd":{"b":7.0,"i":3.5,"r":6.0,"d":7.0,"t":5.0},"kp":["[长波长多共振发射体]: 对称性重构策略（单/双侧萘并π拓展SN-BN与DN-BN）打破光谱红移与展宽的权衡"]},{"i":60437,"as":"J-聚集体因增强吸收、红移和光稳定性在光诊疗中极具吸引力，但通常需要高染料浓度或纳米载体。受DLVO理论启发（多价离子通过压缩双电层降低静电排斥促进胶体絮凝，Schulze-Hardy规则CCC∝1/z⁶），研究开发了基于长程静电相互作用的高价离子可编程J-聚集体策略：在阴离子五次甲基菁（ACy5）的meso位取代正负电荷基团调控其在离子环境中的堆积偏好，获得可响应高价离子发生急剧J-聚集的探针，用于糖尿病细菌感染的按需光疗。","scd":{"b":7.0,"i":3.0,"r":6.0,"d":7.0,"t":4.5},"kp":["J-聚集体形成策略[基于DLVO理论长程静电相互作用]: 多价离子压缩双电层降低静电排斥","临界聚沉浓度规则[Schulze-Hardy]: CCC ∝ 1/z⁶"]},{"i":60438,"as":"COF的制备仍严重依赖条件苛刻的传统溶剂热法。研究报道了以二醇和LiBH₄（或NaBH₄）为原料，在室温下快速、原子经济地机械化学合成柔性离子COFs（ICOFs）的方法。产物可在无溶剂条件下15分钟内以多克级（10 g）规模获得，材料具有良好结晶性、优异的溶剂稳定性，并表现出显著的抗菌活性。","scd":{"b":7.0,"i":4.0,"r":6.0,"d":6.5,"t":5.0},"kp":["合成方法[柔性离子COFs]: 室温机械化学合成","原料[机械化学合成ICOFs]: 二元醇与LiBH₄或NaBH₄"]},{"i":60439,"as":"Pt-Ni合金具有优异的氧还原反应（ORR）活性，但实现结构有序化以增强稳定性仍是挑战。研究提出数据库导向的筛选策略，通过筛选候选促进元素的有序-无序转变临界温度、固溶度和扩散前指因子，合成了六组L1₀-Pt(NiX)纳米颗粒。开发的L1₀-PtNiFe催化剂质量活性达4.38 A mg⁻¹(Pt)，在半电池5万次加速耐久性测试后保持82.1%，在膜电极组件中3万次循环后保持初始1.1 A mg⁻¹的79%。","scd":{"b":7.0,"i":3.5,"r":6.5,"d":7.5,"t":5.0},"kp":["筛选指标[数据库引导PtNi金属间化合物促进元素]: 无序-有序转变温度T_C、固溶度C_sol、扩散前置因子D₀","产物[L1₀-Pt(NiX)筛选]: 六组纳米金属间电催化剂"]},{"i":60440,"as":"研究聚焦单个蒸发中的带电醇（如1-壬醇）微液滴的氧化化学，发现生成了相应的醛、羧酸和酯。氧化仅在湿润条件下被观察到，表明水是氧化剂，H₂¹⁸O同位素实验支持这一假设。此外，氧化具有电荷依赖性——对于低电荷的醇微液滴未观察到氧化产物。","scd":{"b":6.5,"i":2.0,"r":6.5,"d":6.0,"t":5.0},"kp":["氧化化学[单一带电蒸发醇微滴如1-壬醇]: 生成相应醛"]},{"i":60441,"as":"","scd":null,"kp":[]},{"i":60442,"as":"研究报道了首例乙烯基连接的编织共价有机框架（woven COF）。该材料通过Cu(I)配位的新铜试剂节点（Cu(DmPhen)2）与延伸芳香族二醛连接体在熔融聚合条件下的Knoevenagel型缩合构建。刚性铜-菲咯啉节点与三联苯基醛的引入促进框架互锁，形成具有稳固C=C键和永久孔隙率的结晶编织结构。所得Cu-TPy COF展现出长程周期性，拓展了编织COF的连接化学。","scd":{"b":8.0,"i":2.5,"r":7.5,"d":6.5,"t":5.0},"kp":["合成方法[首例乙烯基连接编织COF]: Cu(I)配合新铜试剂节点与芳香二醛 linker 的Knoevenagel缩合熔融聚合"]},{"i":60443,"as":"研究突破了几十年来微孔钛硅分子筛孔道过小、无法容纳大体积反应物的共识。在环己烯环氧化反应中，钛硅分子筛TS-1在无溶剂条件下实现88.8%转化率和超过89%的环氧化物选择性，而在甲醇中转化率低于6.9%。结果表明无溶剂操作可显著提升原本受限的大分子在微孔沸石内的反应性，为精细化学品和制药工业的催化剂设计提供了超越单纯调孔的新思路。","scd":{"b":7.5,"i":3.0,"r":6.5,"d":6.5,"t":5.0},"kp":["反应模式[微孔钛硅分子筛大分子氧化]: 无溶剂操作可突破孔径限制增强大分子反应活性"]},{"i":60444,"as":"","scd":null,"kp":[]},{"i":60445,"as":"研究开发了用于神经形态传感与计算的仿生纳米流体突触。该平台将可编程DNA纳米通道阵列整合到原位组装于阳极氧化铝膜上的磷脂多层中（称为DPAM），形成仿生离子门控界面。DNA序列编程实现对多种神经递质的即插即用适应性，调节纳米通道尺寸可定制离子传输动力学。研究演示了谷氨酸门控的NMDA样信号传导，模拟生物突触通过神经递质和离子流耦合处理信息的机制。","scd":{"b":8.5,"i":3.0,"r":7.0,"d":7.0,"t":5.0},"kp":["结构[仿生纳米流体突触DPAM]: 可编程DNA纳米通道阵列嵌入原位组装磷脂多层于阳极氧化铝膜"]},{"i":60446,"as":"研究结合表面合成与扫描探针显微技术，在Au(111)表面实现了S=1/2反铁磁自旋梯的原子精度构建和逐单元操控，可构建不同长度的梯形结构。通过针尖诱导脱氢与微分电导谱技术，系统表征了横档和腿方向的自旋耦合强度，揭示均为反铁磁耦合，并观测了自旋激发谱的演化。自旋梯模型是连接一维和二维磁系统的重要平台，其S=1/2两腿反铁磁梯因与非常规超导电性的潜在联系而备受关注。","scd":{"b":8.0,"i":1.0,"r":8.0,"d":6.0,"t":5.0},"kp":[]},{"i":60447,"as":"","scd":null,"kp":[]},{"i":60448,"as":"研究发现在羟基化SiO2负载Pt催化剂上，甲醛（HCHO）可作为高效氢穿梭体，通过其碳中心可逆的sp2-sp3杂化切换介导氢转移。DFT计算和从头算分子动力学模拟表明，HCHO辅助氢传递通过两种空间不同的模式进行：在Pt簇附近，HCHO捕获氢原子形成表面锚定的氢化中间体，经旋转重取向将氢转移给邻近HCHO分子。这为SiO2等不可还原氧化物上低效的氢溢流问题提供了新途径。","scd":{"b":8.0,"i":2.0,"r":8.0,"d":7.0,"t":5.0},"kp":["氢穿梭机制[羟基化SiO₂负载Pt]: 甲醛通过碳中心sp²-sp³杂化可逆切换介导氢转移"]},{"i":60449,"as":"","scd":null,"kp":[]},{"i":60450,"as":"","scd":null,"kp":[]},{"i":60451,"as":"研究对长江中下游成矿带斑岩和矽卡岩铜金矿相关火成岩中赋存于锆石、角闪石和黑云母内的含硫原生磷灰石颗粒，原位定量测定了S6+、S4+和S2-的相对丰度。计算得到的含硫磷灰石S6+/ΣS比值在0.18至0.97之间变化，且与寄主矿物的结晶压力和温度无关。数据揭示了斑岩铜成矿岩浆的氧化态硫与还原态硫之争的新证据，显示成矿流体源岩浆存在两个不同的群体。","scd":{"b":7.0,"i":3.0,"r":8.0,"d":8.0,"t":5.0},"kp":["测量方法[斑岩铜矿岩浆硫氧化态]: 原位定量测定磷灰石中S⁶⁺、S⁴⁺、S²⁻相对丰度"]},{"i":60452,"as":"","scd":null,"kp":[]},{"i":60453,"as":"研究报道了一种硼烯介导的多金属位点共锚定策略，合成负载于原始碳上的亚4纳米高熵Pt4FeCoNiCu金属间化合物催化剂（MMCA-HEIMCs）。强金属-硼烯相互作用抑制了高温有序化与小尺寸稳定性之间的相互制约，实现Pt与非贵金属在碳载体上的同步锚定，解决了高金属负载下颗粒长大及金属颗粒与碳载体在工况下腐蚀的问题，提升质子交换膜燃料电池氧还原反应的质量活性和长期耐久性。","scd":{"b":7.5,"i":4.0,"r":6.0,"d":8.0,"t":5.0},"kp":["催化剂[亚4纳米Pt₄FeCoNiCu高熵金属间化合物]: 硼烯介导共锚定实现高金属载量下小尺寸稳定与高ORR活性"]},{"i":60454,"as":"研究将电催化中局部反应环境调控原理引入电有机合成，建立了机理独特的氧驱动Baeyer-Villiger氧化（BVO）电合成路径，并据此开发了局部pH设计框架。电有机转化不仅由电子转移决定，反应周转常与离子转移尤其是质子转移耦合；高速率运行下质子流会使电极附近质子活性极化。这种浓度极化在电合成设计中虽广泛存在且影响重大，却长期被忽视。","scd":{"b":7.0,"i":3.0,"r":6.0,"d":6.0,"t":5.0},"kp":["[电化学界面]: 通过局域pH/质子活度调控促进氧原子转移电合成","[高倍率运行]: 电极附近质子活度发生极化，反应耦合离子与质子转移"]},{"i":60455,"as":"研究引入一种名为'双光子蛋白氧化（TPOP）'的新型蛋白足迹技术。该方法采用纳秒级高功率248 nm准分子激光诱导水和蛋白内芳香族氨基酸的双光子吸收：水的双光子吸收产生羟基自由基用于足迹标记，芳香氨基酸的双光子激发产生自由基阳离子并与周围水反应生成羟基化产物。该光化学可在纯水中微秒时间尺度内完成蛋白侧链氧化标记，无需外部氧化剂或自由基前体，提供更简便、高效、生物相容的替代方案。","scd":{"b":7.5,"i":3.0,"r":7.0,"d":6.0,"t":5.0},"kp":["[TPOP蛋白质足迹技术]: 无过氧化物、激光诱导水双光子吸收产生羟基自由基","[激光参数]: 纳秒级248 nm准分子激光，高功率双光子激发"]},{"i":60456,"as":"研究利用水微滴的光催化样还原能力，提出无催化剂、自由基介导的氧化还原偶联策略，在环境条件下由CH3OH和N2合成尿素。在纯N2气氛、2 vol% CH3OH条件下，优化尿素产率约10.8微克/小时，可与部分尿素人工光合产率相当。相比高能耗的Bosch-Meiser工艺，该方法摆脱了对催化剂组成和结构性质的依赖，综合实验与理论研究表明水微滴可替代传统光催化剂。","scd":{"b":8.5,"i":2.5,"r":7.5,"d":6.0,"t":5.0},"kp":["[尿素合成]: 甲醇与氮在水的微液滴上经自由基介导氧化还原偶联，无需催化剂","[微液滴]: 具有类光催化氧化还原能力，替代Bosch–Meiser高能耗工艺"]},{"i":60457,"as":"研究鉴定了酶TunB，其可在无任何辅因子存在下催化分支酸的分子间碳-碳键形成。TunB参与甲烷氧化菌天然产物tundrenone的生物合成，且基于氨基酸序列同源性无法预测其以分支酸为底物。分支酸是众多初级和次级代谢物的重要前体，其转化酶是构建生物活性分子的有用生物催化剂，但已知分支酸生物化学范围有限。TunB功能的发现揭示了意料之外的分支酸转化酶，有望拓展基于该重要代谢物的分子骨架构建。","scd":{"b":7.0,"i":2.5,"r":7.0,"d":5.0,"t":5.0},"kp":["[TunB酶]: 催化分支酸分子间C–C键形成，无需任何辅因子"]},{"i":60458,"as":"提出基于基础模型增强的条件扩散方法，生成考虑老化的居民负荷场景，用于未来能源系统。","scd":{"b":4.0,"i":2.5,"r":5.0,"d":3.5,"t":4.0},"kp":["[居民负荷场景生成]: 基础模型增强的条件扩散方法，考虑老化因素"]},{"i":60459,"as":"提出多重鲁棒优化方法，考虑小时内不确定性，优化可再生能源虚拟电厂的市场参与策略。","scd":{"b":3.5,"i":2.5,"r":5.0,"d":3.5,"t":4.0},"kp":["[虚拟电厂市场参与]: 多重鲁棒优化，计及小时内不确定性"]},{"i":60460,"as":"研究电力与交通耦合网络的多时段协调调度，结合动态车道重构提升系统效率。","scd":{"b":3.5,"i":2.5,"r":5.0,"d":3.5,"t":4.0},"kp":["[电力-交通耦合网络]: 多时段协调调度结合动态车道重构"]},{"i":60461,"as":"研究将网络耦合部署框架——整合Bass扩散模型与资本约束下基于强化学习的加氢站选址排序——应用于基于货运分析框架数据的美国东南部货运网络，系统改变氢成本轨迹和部署速度。研究指出，现有规划工具将节点级需求视为均匀，忽视了货运流与技术采用动态之间的耦合，而这种耦合对资本受限的部署决策至关重要。研究发现部署速度产生非线性收益等三项主要结论，服务于长途货运脱碳中氢能与电能的竞争分析。","scd":{"b":5.5,"i":4.0,"r":6.5,"d":6.0,"t":5.0},"kp":["[氢能长途货运脱碳]: 网络耦合部署框架，整合Bass扩散与强化学习","[现有规划工具局限]: 将节点级需求视为均匀，忽略货运流与技术采纳耦合"]},{"i":60462,"as":"基于光纤传感器分布式应变测量，对刀片电池进行机理驱动的原位退化诊断。","scd":{"b":5.5,"i":4.0,"r":6.0,"d":4.0,"t":5.0},"kp":["[刀片电池退化诊断]: 光纤传感器分布式应变测量的机理驱动原位诊断"]},{"i":60463,"as":"对直接空气捕获与大气水收集集成系统开展技术经济分析，评估其可行性与成本。","scd":{"b":4.5,"i":3.5,"r":6.0,"d":5.5,"t":4.5},"kp":["[DAC与大气水收集集成系统]: 技术经济分析评估可行性与成本"]},{"i":60464,"as":"研究基于PRISMA指南和Scopus检索，对交通领域氢能经济评估相关近期研究进行系统综述，分析了57篇期刊文献数据。虽然氢的生产、运输和加注过程已被证实可行，但经济可行性仍是待解决的关键挑战。研究强调正确使用经济指标以及信息和参数的清晰性，对公平评估氢能在交通领域的应用、提升项目可融资性至关重要。氢被视为交通脱碳乃至摆脱烃基经济的潜在能量载体。","scd":{"b":5.0,"i":3.0,"r":5.5,"d":5.0,"t":3.0},"kp":["经济可行性[氢能在交通领域]: 生产、运输和加注工艺已被验证，但经济性仍是主要挑战"]},{"i":60465,"as":"Lan Wen讨论了高效液相色谱（HPLC）如何用于监测光电化学系统中的产物和产率。作为一种表征手段，HPLC可对光电化学系统产生的化学产物进行定量分析，为评估此类系统的性能提供数据支持。","scd":{"b":4.0,"i":3.0,"r":4.0,"d":3.5,"t":4.0},"kp":["表征方法[光电化学系统]: 高效液相色谱用于监测产物与产率"]},{"i":60466,"as":"通过用多个微波频率驱动磁性薄膜，可以产生包含数千条自旋波梳线的磁振子频率梳，为芯片级微波计算提供了一条潜在途径。","scd":{"b":8.0,"i":3.0,"r":6.5,"d":6.0,"t":6.0},"kp":["频率梳线数[磁振子频率梳]: 数千条自旋波梳线","技术特征[微波驱动磁膜]: 提供芯片级微波计算的潜在途径"]},{"i":60467,"as":"仅半个晶胞厚的氧化镓层可通过应变工程转变为闪锌矿相，具有可切换的铁电性，矫顽电压低于1伏。","scd":{"b":8.5,"i":3.0,"r":6.5,"d":7.0,"t":6.0},"kp":["厚度[应变工程氧化镓铁电层]: 半个晶胞（亚纳米级）","矫顽电压[锌blende相可切换铁电性]: 低于1 V"]},{"i":60468,"as":"报道了一种光催化脱硝氰化反应，可在温和条件下直接将硝基烷烃转化为腈。反应在蓝光LED照射下快速进行，具有广泛的官能团耐受性。机理研究支持α-硝基自由基与氰离子之间的阴离子-自由基偶联路径：硝酮离子经单电子氧化生成α-硝基自由基，被氰离子捕获形成α-硝基腈自由基阴离子，随后挤出亚硝酸根离子生成α-氰基自由基，经还原和质子化得到腈产物。该转化以同时瞬时容纳亲核试剂和离去基团的独特自由基阴离子中间体为特征。","scd":{"b":7.0,"i":2.0,"r":5.5,"d":6.5,"t":5.0},"kp":["反应条件[硝基烷烃脱硝氰化]: 蓝光LED照射下温和条件快速进行","机理[阴离子-自由基偶联路径]: 硝酮酸离子经单电子氧化生成α-硝基自由基，被氰根离子捕获"]},{"i":60469,"as":"负载型Au纳米团簇是高效催化剂但易因烧结失活。研究团队利用神经网络势研究了氧化条件下锐钛矿TiO2(101)表面负载Au纳米团簇的奥斯特瓦尔德熟化（OR）过程，确定Au和AuO为主要可迁移物种。研究开发了系统性的单体脱附映射（MDMAP）工作流程以高效采样脱附景观。动力学分析表明，低能亚稳态系综（LEMEs）是关键的动力学中间体。通过评估不同尺寸和氧覆盖度的团簇，确定界面氧是调控熟化过程的关键因素。","scd":{"b":6.0,"i":2.0,"r":5.5,"d":6.5,"t":5.0},"kp":["迁移物种[锐钛矿TiO2(101)氧化条件下Au团簇奥斯特瓦尔德熟化]: Au和AuO为主要可迁移物种","研究方法[Au纳米团簇烧结研究]: 神经网络势结合单体脱附映射(MDMAP)工作流"]},{"i":60470,"as":"酶是生物催化的核心，但其应用常受催化转换数（Kcat）不足的限制，而已测速率常数稀缺且序列空间庞大。现有深度学习模型虽能预测Kcat，但通常在序列生成后才用于打分或筛选候选者，将动力学目标与设计过程分离。CatESO是一种可微分序列优化器，通过对跨模态Kcat预测器进行反向传播，实现了对底物特异性催化转换数的直接梯度引导设计，架起了序列生成与动力学评估之间的桥梁。","scd":{"b":7.0,"i":3.0,"r":6.0,"d":6.0,"t":5.0},"kp":["优化框架[CatESO酶序列优化]: 底物感知Kcat预测引导的可微分酶序列优化"]},{"i":60471,"as":"","scd":null,"kp":[]},{"i":60472,"as":"空间不均匀的等离激元异质结构可将光浓缩到纳米尺度体积，但热载流子在极端纳米光子约束下（尤其在界面转移过程中）如何演化和损失能量仍不清楚。研究证明，合理设计的具有强纳米级场局域化的等离激元纳米腔可通过在亚40飞秒时间尺度上实现非热电荷注入来绕过热化能量损失通道。利用偏振分辨和时间分辨多光子光电发射光谱，揭示了等离激元-腔模式耦合产生的强局域场建立了加速且直接的电子转移。","scd":{"b":7.5,"i":2.5,"r":6.0,"d":6.5,"t":5.0},"kp":["技术特征[等离激元纳米腔水氧化]: 超快界面电荷转移可绕过热化能量损失"]},{"i":60473,"as":"核酮糖-1,5-二磷酸羧化酶/加氧酶（rubisco）是重要但极具挑战性的蛋白质工程目标。研究采用将rubisco活性与聚球藻Synechocystis sp. PCC 6803生长速率耦合的体内筛选方法，对来自Gallionella sp.的form II rubisco包含15000个单位点和多位点变体的条形码突变文库进行筛选。活性位点附近loop 6、二聚体界面及潜在气体通道中的氨基酸替换提高了rubisco适应性。数据集还通过重组和训练的transformer模型指导蛋白质工程，体外表征验证了改造结果。","scd":{"b":7.0,"i":3.0,"r":6.0,"d":6.0,"t":5.0},"kp":["筛选方法[form II rubisco工程]: 体内筛选将rubisco活性与聚光自养蓝细菌Synechocystis sp. PCC 6803生长速率耦合","工程目标[Gallionella sp. form II rubisco]: 耐氧性工程改造"]},{"i":60474,"as":"","scd":null,"kp":[]},{"i":60475,"as":"代谢改变为癌细胞提供适应性优势，亟需改进的细胞代谢非侵入性长期监测方法。研究提出了一种快速活细胞NADH成像方法——双光子荧光偏振比率显微技术（FPRM），可实时测量未结合NADH的比例水平，是细胞代谢状态的可靠指标。该方法易于实施且成本低廉，比常用的荧光寿命成像显微术（FLIM）快一个数量级以上。FPRM返回的比率参数与药物和环境因素引起的预期代谢变化相关，且不依赖仪器。","scd":{"b":6.0,"i":3.0,"r":5.0,"d":6.0,"t":4.0},"kp":["技术特征[双光子NAD(P)H荧光偏振显微(FPRM)]: 实时测量未结合NADH比例，作为细胞代谢状态稳健指标","优势[FPRM活细胞成像]: 实现简单、低成本、可长期无损监测细胞代谢"]},{"i":60476,"as":"","scd":null,"kp":[]},{"i":60477,"as":"高精度低频加速度传感对导航、地震学和结构健康监测至关重要，但在可扩展平台上同时实现高灵敏度和紧凑性仍具挑战性。研究报道了一种全光学元加速度计，将偏振编码超构表面与机械弹簧结构集成，在超紧凑尺寸内实现加速度到位移的转换和光学偏振读出。实验证明该传感器在1赫兹处位移噪声底为340 pm/√Hz。通过将超构表面与3D打印弹性悬挂结构耦合，实现了惯性加速度传感，1赫兹处噪声水平为900 ng/√Hz，振幅动态范围为85.6分贝。","scd":{"b":7.0,"i":3.0,"r":6.0,"d":7.0,"t":4.0},"kp":["加速度计[全光超构表面]: 偏振编码超构表面与机械弹簧结构集成，实现加速度-位移转换与光学偏振读out，超紧凑 footprint"]},{"i":60478,"as":"","scd":null,"kp":[]},{"i":60479,"as":"","scd":null,"kp":[]},{"i":60480,"as":"","scd":null,"kp":[]},{"i":60481,"as":"自由电子与光子之间的量子耦合使得量子光学技术可应用于电子显微学，例如通过强激光场操控电子波函数相位。研究建立了弹性耦合的量子光学框架，揭示了隐藏的反作用：电子通过时对光子模式诱导的相移。这种“相位反冲”可被量化为自由电子的折射率或表述为色散哈密顿量。这种弹性散射为通过非破坏性计数自由电子实现电子数态铺平道路，从而实现埃格斯特朗尺度的亚散粒噪声传感和成像。","scd":{"b":8.0,"i":2.0,"r":7.0,"d":6.0,"t":4.0},"kp":["相位反冲[自由电子-光子弹性耦合]: 电子对光子模式诱导的相移可量化为折射率变化"]},{"i":60482,"as":"平衡比能量和循环耐久性是实用电池系统的关键挑战。研究设计了共生的Li-SiOx混合阳极，实现时空协调的锂金属电镀和锂离子合金化。优先生成的锂化LixSi形成Li+导电网络，引导并限制SiOx层下的锂成核，这种对锂沉积的精确控制可补充活性锂库存，稳定电化学反应并最小化锂损失。与LiNi0.8Co0.1Mn0.1O2正极（4 mAh/cm2）配对时，全电池比能量比SiOx基锂离子电池高50%，同时保持80%容量保持率。","scd":{"b":7.0,"i":4.0,"r":6.0,"d":7.0,"t":5.0},"kp":["混合阳极[Li-SiOx协同双机制]: 优先锂化的LixSi形成Li+导电网络，引导并限制SiOx层下锂金属成核，实现镀锂与合金化时空协同"]},{"i":60483,"as":"通过组合一对垂直偏振的太赫兹脉冲并设置合适的相对延迟，构建了手性太赫兹驱动场以激发铌酸锂（LiNbO3）中的手性声子极化子。超快法拉第旋转探针的幅度与每个晶胞约10 μN内磁化强度的预期相符，而产生同等效果需要超过10特斯拉的外磁场。当输入太赫兹脉冲从左旋变为右旋偏振时，法拉第旋转信号方向切换，表明磁化方向改变。研究还通过改进先前实验方法提升了测量精度。","scd":{"b":7.5,"i":2.0,"r":6.0,"d":7.0,"t":4.0},"kp":["法拉第旋转[LiNbO3手性声子极化子]: 超快法拉第旋转对应每单位晶胞约10 μN的内禀磁化强度"]},{"i":60484,"as":"","scd":null,"kp":[]},{"i":60485,"as":"","scd":null,"kp":[]},{"i":60486,"as":"研究人员开发了受视网膜启发的新型光子计算系统，利用随机网络激光器中空间竞争的激光模式作为异质化、抑制性耦合的神经元，类似生物视网膜神经节细胞通过侧向抑制从稀疏输入中检测特征。该系统结合异质性兴奋性和抑制性非线性响应，实现特征检测、少样本分类和图像分割任务，与硅工艺兼容。研究表明生物神经元的多样化非线性响应与低数据量条件下的鲁棒学习和优异性能相关，该方案为模拟大脑从有限数据中提取结构能力的AI硬件提供了新途径。","scd":{"b":7.5,"i":4.0,"r":7.0,"d":6.0,"t":5.0},"kp":["神经形态视觉[非线性光子网络激光器]: 类视网膜侧抑制与异质非线性响应，实现少镜头低数据学习"]},{"i":60487,"as":"研究人员开发了一种血液干燥处理方案，可直接从全血中检测RNA，无需提取、纯化或冷链物流，解决了全血中RNA快速酶降解和基质抑制效应的根本限制。该平台对寨卡病毒检测灵敏度达每微升10个拷贝，对丙型肝炎病毒达每微升1个国际单位。通过热处理样品结合引物限制性逆转录步骤，稳定干燥血基质中的RNA。该方案可扩展至更大血量体积，在不损失样品的情况下实现单拷贝灵敏度检测。","scd":{"b":6.0,"i":5.0,"r":7.0,"d":8.0,"t":5.0},"kp":["检测灵敏度[全血 Zika病毒RNA]: 10 copies/μL","检测灵敏度[全血 HCV RNA]: 1 IU/μL","样品处理[全血RNA检测]: 血液干燥方案，无需提取、纯化或冷链"]},{"i":60488,"as":"","scd":null,"kp":[]},{"i":60489,"as":"","scd":null,"kp":[]},{"i":60490,"as":"","scd":null,"kp":[]},{"i":60491,"as":"","scd":null,"kp":[]},{"i":60492,"as":"研究采用整合自下而上质谱（位点特异性动力学）和自上而下蛋白质形态表征的混合质谱方法，通过可控生化反应解析AMPK激活过程中的蛋白质形态。研究发现AMPK磷酸化通过级联反应而非二元开关进行，具有双重入口：经典钙/钙调素依赖性蛋白激酶激酶2（CaMKK2）介导的磷酸化或别构激活剂PF-739均可触发广泛的自身磷酸化。该研究为理解化学扰动如何触发和调节治疗靶点中的磷酸化级联提供了新方法。","scd":{"b":7.0,"i":3.0,"r":6.0,"d":7.0,"t":5.0},"kp":["分析方法[AMPK磷酸化级联]: 自下而上MS（位点动力学）与自上而下蛋白形态表征整合的混合质谱"]},{"i":60493,"as":"","scd":null,"kp":[]},{"i":60494,"as":"研究在酿酒酵母中重构了完整的叶绿素生物合成途径，整合13个异源基因并敲除3个内源基因，构建出能以每克干细胞重26微克产量生产叶绿素a的酵母底盘。该平台进一步扩展酮类胡萝卜素合成模块以生产海胆酮和斑蝥黄质，实现两种不同色素-蛋白复合物的体内共组装：植物来源的水溶性叶绿素蛋白和蓝细菌橙色胡萝卜素蛋白。该成果克服了叶绿素异源生产中途径复杂性和资源分流的关键挑战，为合成生物学提供了重要平台。","scd":{"b":8.5,"i":3.0,"r":7.5,"d":8.0,"t":7.0},"kp":["叶绿素a产量[酿酒酵母重构叶绿素途径]: 26 μg/g干细胞","基因工程[酵母叶绿素合成]: 整合13个异源基因，敲除3个内源基因"]},{"i":60495,"as":"研究结合超柔性电极实现稳定的皮质内微刺激（ICMS），配合纵向成像和电生理记录，追踪数周学习过程中单细胞和群体反应的变化。检测任务结果显示，检测阈值随学习而降低，表明神经可塑性的存在。慢性成像显示固定电流下刺激诱发的神经元募集范围扩大，但持续有相同数量的神经元支撑行为反应。一部分学习敏感细胞增强了调制幅度并缩短了反应潜伏期。该研究揭示了人工激活响应随学习演化的机制。","scd":{"b":7.5,"i":3.5,"r":7.0,"d":7.5,"t":7.0},"kp":["检测阈值[皮质内微刺激学习]: 随学习降低，伴随单细胞与群体响应的纵向变化"]},{"i":60496,"as":"该综述总结了应变工程作为调控高熵电催化剂电子结构和催化行为的有效策略。电化学水分解中，析氢和析氧反应的缓慢动力学主要受限于标度关系和关键中间体吸附能的非优化。高熵材料具有多主元组成和显著晶格畸变，原子尺寸失配产生的固有微应变场结合迟滞扩散和鸡尾酒效应，提供可调电子结构和丰富的亚稳态活性位点，为应变介导的催化调控提供了独特平台。综述系统总结了该领域的最新进展、机理和策略。","scd":{"b":6.5,"i":3.0,"r":6.0,"d":6.5,"t":4.0},"kp":["应变工程[高熵电催化剂]: 通过多主元组分与晶格畸变调控电子结构与中间体吸附能，用于电化学水分解"]},{"i":60497,"as":"无负极钠金属电池（AFSMBs）具有超高能量密度（>350 Wh/kg）和低成本优势，但低温和快充条件下面临钠存量有限和界面动力学迟缓的限制，形成'稳定性悖论'：追求高能量密度加剧界面不稳定性，导致钠沉积不均匀和容量快速衰减。该综述系统分析了极端条件下AFSMB的失效机制，指出突破瓶颈需要在四个协同领域进行集成设计：(1)通过弱溶剂化、高浓度和高熵设计调控电解液溶剂化结构以降低去溶剂化能垒，以及集流体界面工程等协同优化策略。","scd":{"b":6.0,"i":3.0,"r":6.0,"d":7.0,"t":5.0},"kp":["能量密度[无负极钠金属电池]: >350 Wh/kg","关键挑战[无负极钠金属电池低温快充]: 钠储量有限与界面动力学迟缓导致稳定性悖论，引发钠沉积不均与容量快速衰减"]}]);